// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 굳건
// ==========================================
// 방패병 · 생존가 · 결계술사 · 외공 수련생 · 광부
// 굳건 — 비 오는 밤, 닫히는 문과 줄어드는 시간 앞에서 먼저 맞고, 오래 버티고, 끝내 서 있는 자리

// ------------------------------------------
// 방패병 · 무력
// ------------------------------------------
kJob('shield', 'B', [

{ at:'B', t:'빗속 — 우는 쇠판',
  x:`비가 방패를 친다. 쇠판 위에서 빗방울이 북처럼 운다.<br><br>
    다른 사람들 옷은 비를 먹는다. 소리가 안 난다. 이 밤에 소리를 내는 것은 방패 하나다.<br>
    쫓는 쪽은 귀가 밝다. 빗소리 속 쇠 우는 소리 하나면 충분하다.<br><br>
    등 뒤 골목 어귀에서 손전등이 켜졌다. 빛이 사람 가슴 높이를 찾는다.`,
  o:[
    { l:'① 방패 앞면에 젖은 천을 덮어 묶는다.', k:'fix', dc:19,
      ok:`외투 안감을 뜯어 방패 앞면에 덮고 끈으로 묶었다.<br><br>빗소리가 둔해졌다. 쇠가 아니라 천이 맞는다. 천은 울지 않는다.<br>손전등 빛이 골목을 한 번 훑고 지나갔다.<br><br>천이 물을 먹어 방패가 한 근쯤 무거워졌다. 소리 대신 무게를 졌다.`,
      ng:`묶는데 끈이 젖어 매듭이 안 선다. 천이 반쯤 흘러내렸다.<br><br>드러난 쇠 모서리에 빗방울이 떨어진다. 똑, 똑. 작은데 맑다.<br>빛이 그 소리를 따라 와서 이쪽 무릎에 멈췄다. 몸을 굴려 상자 뒤로 들어갔다. 무릎이 바닥에 찢겼다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 방패를 비스듬히 눕혀 비를 흘려보낸다.', k:'steady', dc:20, wake:1,
      ok:`방패를 조금 눕혔다. 빗방울이 쇠를 때리지 않고 미끄러진다. 소리가 쉭 하고 낮아졌다.<br><br>한 치 더 눕히면 물이 고인다. 한 치 덜 눕히면 다시 운다. 그 사이 한 각도에서 방패가 조용해졌다.<br>팔이 그 각도를 외웠다. 걸으면서도 놓치지 않는다.<br><br>오는 것을 받기만 하면 소리가 난다. 흘리면 소리조차 안 남는다. 손목이 그걸 먼저 알았다. 이 밤 내내 방패는 한 번도 울지 않았다.`,
      ng:`눕혔는데 팔이 떨려 각이 흔들린다. 빗소리가 났다 그쳤다 다시 난다.<br><br>그 들쭉날쭉한 소리가 오히려 귀에 걸렸다. 빗소리 사이에서 사람 숨 박자처럼 들린다.<br>빛이 곧장 이쪽으로 왔다. 방패를 세워 얼굴을 가렸다. 빛이 쇠판에 부딪혀 골목 가득 튄다. 다 들켰다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 배 부른 상자',
  x:`건어물 상자가 천장 가까이 쌓였다. 맨 아래 상자가 젖어 배가 불룩하다.<br><br>
    상자에서 기름 냄새가 난다. 쇠 냄새도. 들어 있는 것은 건어물이 아니다. 무겁다.<br>
    쪽문으로 가는 통로가 그 상자 탑 옆으로 나 있다. 어깨 하나 너비다.<br><br>
    탑이 숨을 쉬듯 한 번 기울었다가 돌아왔다. 다음번에는 안 돌아올지도 모른다.`,
  o:[
    { l:'① 무력을 쓴다 — 방패와 어깨로 탑을 받친다.', k:'steady', dc:21, cost:{ might:25 }, wake:1,
      ok:`탑에 방패를 대고 어깨를 붙였다. 무력을 허리로 내렸다.<br><br>무겁다. 팔로는 못 든다. 방패 밑 모서리를 바닥에 박았다. 그러자 무게 반이 바닥으로 빠졌다. 남은 반만 어깨에 남는다.<br>동료들이 그 옆을 하나씩 지났다.<br><br>혼자 받친 게 아니다. 바닥과 같이 받쳤다. 방패를 세우는 자리 하나로 무게가 반이 된다. 그다음부터는 서는 곳마다 바닥부터 봤다.`,
      ng:`받쳤는데 맨 아래 상자가 터졌다. 배가 갈라지며 기름 먹은 짚이 쏟아졌다.<br><br>탑이 이쪽으로 내려앉는다. 방패로 머리를 덮었다. 상자 둘이 방패를 치고 셋째가 등을 쳤다.<br>쇳덩이가 바닥에 굴렀다. 소리가 창고 끝까지 갔다. 저 안쪽에서 대걸레 소리가 멈췄다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12, might:-5 } },
    { l:'② 방패를 맨 아래 상자 옆구리에 쐐기로 박는다.', k:'fix', dc:20,
      ok:`방패 모서리를 불룩한 상자와 바닥 사이에 밀어 넣고 발로 찼다.<br><br>탑이 반대쪽으로 한 치 기울었다. 벽에 기댔다. 벽이 받아 준다.<br>방패는 거기 두고 갔다. 동료들이 다 지난 뒤 뽑아 왔다. 뽑는 순간 탑이 다시 이쪽을 봤다.`,
      ng:`밀어 넣는데 상자가 물러서 방패가 그대로 박혀 들어갔다.<br><br>빼려니 안 빠진다. 탑이 끙 하고 운다. 위에서 상자 하나가 미끄러져 떨어졌다.<br>방패를 놓고 비켰다. 상자가 방패 손잡이 위로 떨어졌다. 손이 거기 있었으면 손이 없다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 다른 길로 일행을 돌린다.', k:'sense', dc:20,
      ok:`탑 반대편을 봤다. 지게차가 다니는 넓은 길이 있다. 바닥에 바퀴 자국이 깊다.<br><br>넓은 길은 눈에 잘 띈다. 그래도 위에서 떨어질 것은 없다.<br>일행을 그쪽으로 돌렸다. 맨 뒤에서 방패를 등에 메고 따라갔다. 지나온 자리에서 탑이 천천히 무너졌다. 비 소리에 묻혔다.`,
      ng:`넓은 길로 돌렸는데 거기에 회색 비옷이 서 있다. 등을 보이고. 바닥을 민다.<br><br>멈춰 섰다. 그 사람도 멈췄다. 대걸레 끝만 계속 움직인다.<br>되돌아 탑 옆길로 뛰었다. 어깨가 상자에 걸려 탑이 흔들렸다. 등에 떨어진 상자 모서리가 한 번 찍었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B2', t:'폐쇄 병동 — 빈손',
  x:`눈을 뜨니 병원 침대다. 손이 허전하다. 왼팔이 무언가를 쥐려다 시트를 쥐었다.<br><br>
    방패가 없다. 어깨에 끈 자국만 남았다. 몇 해를 메고 다닌 자리다.<br>
    복도에서 딸깍 소리가 온다. 그 앞에서 고무바퀴 소리. 보호사 둘이 묶는 띠를 실은 수레를 민다.<br><br>
    옆 침대 동료가 일어나 앉아 있다. 누워 있지 않은 사람은 묶는다. 문 앞에 적혀 있다.`,
  o:[
    { l:'① 배식 수레의 쇠 식판을 집는다.', k:'fix', dc:20,
      ok:`문 옆 배식 수레에서 쇠 식판 하나를 뽑아 왼팔에 댔다.<br><br>작다. 가슴 반만 가린다. 그래도 손이 쥘 것을 찾았다. 손이 쥐니 발이 선다.<br>보호사가 문을 열었다. 식판을 든 채 동료 앞에 섰다. 보호사가 식판을 보고, 이쪽 얼굴을 보고, 수레를 밀고 지나갔다. 식판 든 사람은 배식 중인 사람이다.`,
      ng:`식판을 뽑는데 위 칸 국그릇이 같이 쏟아졌다. 쨍 하는 소리가 복도에 퍼졌다.<br><br>딸깍 소리가 멈췄다. 보호사 둘이 들어왔다. 식판을 빼앗고 이쪽 손목을 잡았다.<br>띠가 감겼다. 정각이 지나서야 풀렸다. 풀어 준 사람이 누군지는 모른다. 손목에 버클 자국이 남았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 맨팔로 방패 자리를 잡고 동료 앞에 선다.', k:'steady', dc:21, wake:1,
      ok:`침대에서 내려와 동료 앞에 섰다. 왼팔을 가슴 앞에 비스듬히 걸었다. 방패가 있을 자리다.<br><br>보호사의 손이 동료를 향해 왔다. 그 손이 팔뚝에 걸렸다. 쇠가 아니라 뼈에. 그래도 각이 같다. 손이 미끄러져 옆으로 빠졌다.<br>보호사가 이쪽을 내려다봤다. 한참. 그리고 수레를 밀고 나갔다.<br><br>방패는 손에 쥐는 것인 줄 알았다. 서는 자리와 팔의 각도와 발의 넓이가 이미 방패였다. 쇠는 그 위에 얹는 것이다.`,
      ng:`팔을 걸었는데 보호사가 팔을 안 잡는다. 이쪽 어깨를 잡았다. 방패가 없으면 어깨가 비는 줄을 그쪽이 먼저 안다.<br><br>침대로 눕혀졌다. 띠가 감겼다. 동료도.<br>천장 형광등이 지직거린다. 정각 점검이 둘을 세고 지나갔다. 어깨의 끈 자국 위로 새 자국이 겹쳤다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B3', t:'9호차 — 통로 너비',
  x:`열차 통로는 어깨 하나 너비다. 양옆이 좌석, 위가 선반.<br><br>
    방패를 가로로 들어 봤다. 양쪽 등받이에 테가 닿는다. 통로가 꼭 방패 너비다.<br>
    뒤에서 누가 온다. 아까 맨 뒷자리에서 자던 남자다. 걸음마다 얼굴이 조금씩 다른 사람이 된다.<br><br>
    앞쪽에 일행이 있다. 앞 칸 문을 열려고 손잡이와 씨름하고 있다.`,
  o:[
    { l:'① 방패를 통로에 가로로 세우고 등을 붙인다.', k:'steady', dc:21, wake:1,
      ok:`방패를 통로에 가로질러 세웠다. 양쪽 등받이에 테가 물렸다. 등으로 방패 뒷면을 눌렀다.<br><br>남자가 방패 앞에 섰다. 넘어오려면 선반을 타야 한다. 손을 뻗는다. 손이 테에 걸린다. 밀어도 방패가 안 밀린다. 등받이가 같이 받는다.<br>뒤에서 문 열리는 소리가 났다.<br><br>앞을 막는 게 아니었다. 통로를 닫았다. 방패 하나가 문짝이 되는 너비가 따로 있다. 들어서는 통로마다 그 너비를 재게 됐다.`,
      ng:`세웠는데 열차가 굽이를 돌았다. 방패 한쪽 테가 등받이에서 빠졌다.<br><br>틈이 생겼다. 남자 손이 그 틈으로 들어와 이쪽 손목을 잡았다. 차다. 젖지 않았는데 차다.<br>뿌리치고 방패를 다시 박았다. 손목에 손가락 자국 다섯이 남았다. 남자 얼굴이 또 바뀌어 있었다. 이번엔 이쪽 얼굴과 조금 닮았다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 일행을 먼저 보내고 맨 뒤로 붙는다.', k:'bond', dc:20,
      ok:`앞으로 가서 문손잡이를 같이 당겼다. 열렸다. 일행을 하나씩 밀어 넣었다.<br><br>마지막에 들어서며 방패로 등 뒤를 덮었다. 문이 닫히는 순간 방패에 무언가 부딪혔다. 손바닥 하나.<br>문 유리에 김이 서렸다가 손 모양으로 지워졌다. 그 너머 얼굴은 이미 다른 얼굴이었다.`,
      ng:`앞으로 갔는데 문이 안 열린다. 둘이 당겨도. 셋이 당겨도.<br><br>뒤를 비웠다. 돌아봤을 때 남자가 일행 맨 끝 사람 바로 뒤에 서 있었다. 귀에 대고 무어라 속삭인다.<br>방패로 밀어냈다. 끝 사람은 무슨 말을 들었는지 말하지 않았다. 그 뒤로 내내 손을 떨었다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'쫓기는 길 — 뒷걸음',
  x:`뒤에서 발소리가 따라온다. 서두르지 않는다. 쫓는 쪽이 서두르지 않으면 쫓기는 쪽만 지친다.<br><br>
    방패는 앞을 막는다. 쫓는 것은 뒤에 있다.<br>
    돌아서서 방패를 뒤로 향하면 앞이 안 보인다. 앞에는 젖은 계단과 꺾인 골목과 일행이 있다.<br><br>
    맨 뒤에 서는 사람은 늘 하나다. 오늘도 그 하나다.`,
  o:[
    { l:'① 뒤를 보고 뒷걸음으로 따라간다.', k:'steady', dc:21, wake:1,
      ok:`돌아서서 방패를 뒤로 세웠다. 앞사람에게 말했다. 등에 손을 대 달라고.<br><br>손바닥이 등에 닿았다. 손이 왼쪽으로 기울면 왼쪽으로, 멈추면 멈췄다. 발이 계단 모서리를 더듬고 젖은 쇠판을 더듬는다. 넘어지지 않았다.<br>발소리가 방패 앞 열 걸음에서 따라오다가, 한참 뒤 멈췄다. 쫓는 쪽이 지쳤다.<br><br>앞이 안 보여도 걷는다. 등에 닿은 손 하나가 눈 노릇을 했다. 발바닥이 길을 외우는 속도가 날마다 빨라질 것이다.`,
      ng:`뒷걸음질 치는데 앞사람 손이 등에서 떨어졌다. 계단에서 미끄러졌다고 한다.<br><br>그 사이 이쪽 발이 허공을 밟았다. 계단 다섯 칸을 등으로 내려갔다. 방패가 먼저 굴러 소리를 냈다.<br>발소리가 빨라졌다. 처음으로 서두른다. 일어나 방패를 주워 들었을 때 팔꿈치가 안 펴졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 돌아서서 다 같이 뛴다.', k:'evade', dc:20,
      ok:`방패를 등에 돌려 메고 뛰었다. 등이 방패다.<br><br>골목을 둘 꺾었다. 셋째에서 등에 무언가 쾅 하고 맞았다. 던진 것이다. 쇠판이 받았다.<br>뛰는 동안 발소리가 멀어졌다. 등에 맞은 자국은 남았다. 움푹하다. 무엇이었는지는 보지 않았다.`,
      ng:`뛰는데 방패 끈이 끊겼다. 등에서 미끄러져 다리에 걸렸다.<br><br>앞으로 고꾸라졌다. 턱이 젖은 바닥에 닿았다. 방패를 끌어안고 굴렀다.<br>발소리가 이쪽 머리맡까지 와서 섰다. 숨을 참았다. 한참 뒤 발소리는 다른 쪽으로 갔다. 이쪽이 아니라 앞서 간 일행 쪽으로.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-25, spirit:-13 } }
  ] },

{ at:'B1', t:'야적장 — 탐조등과 쇠판',
  x:`크레인 꼭대기 탐조등이 야적장을 훑는다. 하얀 빛 속에서만 빗줄기가 보인다.<br><br>
    방패 앞면은 오래 써서 반들반들하다. 빛을 받으면 되쏜다.<br>
    컨테이너 골목에서 사람은 그림자로 숨는다. 쇠판은 그림자 속에서도 번쩍인다.<br><br>
    빛이 한 바퀴 돌아온다. 마흔 걸음쯤 남았다.`,
  o:[
    { l:'① 방패 앞면을 땅으로 엎고 그 위에 엎드린다.', k:'hide', dc:20,
      ok:`방패를 엎어 놓고 그 위에 배를 대고 엎드렸다. 쇠판은 등 밑에 있다.<br><br>빛이 위를 지나갔다. 젖은 외투는 빛을 먹는다. 아무것도 되쏘지 않았다.<br>빛이 지나간 뒤 일어났다. 배가 다 젖었다. 쇠판이 빗물을 모아 두었다가 다 넘겨줬다.`,
      ng:`엎는데 방패 테가 바닥 철판에 부딪혀 쩡 울렸다.<br><br>빛이 멈췄다. 이쪽 컨테이너 위에서. 빗줄기가 빛 속에서 바늘처럼 선다.<br>엎드린 채 숨을 죽였다. 빛이 너무 오래 머문다. 결국 지나갔지만 그동안 등을 두드린 빗방울을 다 셀 수 있었다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-15, spirit:-12 } },
    { l:'② 빛을 되쏘아 탐조등 위로 돌려보낸다.', k:'luck', dc:21,
      ok:`빛이 오는 순간 방패를 들어 크레인 꼭대기로 각을 맞췄다.<br><br>쇠판에 맞은 빛이 그대로 위로 올라갔다. 꼭대기 운전실 유리가 하얗게 빛났다. 탐조등이 휘청 하고 엉뚱한 쪽을 비췄다.<br>그 틈에 골목 셋을 지났다. 위에 있던 사람은 한동안 눈을 비볐을 것이다.`,
      ng:`각을 맞췄는데 빛이 위가 아니라 옆 컨테이너로 튀었다.<br><br>거기 숨어 있던 것은 일행이었다. 일행 얼굴이 하얗게 드러났다.<br>탐조등이 그쪽에 멈췄다. 다 같이 뛰었다. 뛰는 동안 빛은 이쪽 방패를 따라왔다. 쇠판은 끝까지 번쩍였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'③ 컨테이너 벽에 방패를 붙이고 그 뒤에 선다.', k:'steady', dc:20,
      ok:`녹슨 컨테이너 벽에 방패를 붙이고 그 뒤에 몸을 붙였다. 움직이지 않았다.<br><br>빛이 왔다. 방패 앞면에 닿았다. 되쏘지 않는다. 벽에 붙은 쇠는 벽의 일부다. 녹슨 철판 사이의 철판 하나.<br>빛이 지나갔다. 움직이지 않는 것은 짐이다. 이 항구에서 짐은 아무도 안 쳐다본다.`,
      ng:`붙였는데 방패가 벽보다 한 뼘 튀어나왔다. 그림자가 생겼다.<br><br>빛이 그 그림자 모양에서 멈췄다. 사람 모양이다.<br>버텼다. 움직이면 끝이다. 빛이 떠날 때까지 숨을 몇 번 쉬었는지 모른다. 다리가 얼어 첫걸음에 무릎이 꺾였다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 붙어 오는 서가',
  x:`서가가 바닥 레일 위에 앉아 있다. 손잡이를 돌리면 옆으로 밀려 붙는다. 통로는 하나만 열렸다.<br><br>
    일행이 그 통로 안쪽에서 기록철을 뒤진다. 출구 도면이 거기 있다.<br>
    어디선가 손잡이 도는 소리가 났다. 끼릭, 끼릭. 서가 한 줄이 이쪽으로 한 치씩 온다.<br><br>
    레일에 끼인 슬리퍼 한 짝이 납작하게 눌린 채다. 서가는 사람 사정을 안 본다.`,
  o:[
    { l:'① 통로에 방패를 가로로 세워 서가를 받친다.', k:'steady', dc:21,
      doom:{ title:'붙어 버린 서가', what:'서가 사이에 눌리고 있습니다', dc:17, sec:55,
        text:`통로에 방패를 가로로 세웠다. 양쪽 서가에 테가 닿았다. 등과 팔로 받쳤다.<br><br>서가가 온다. 방패가 운다. 테가 휘기 시작한다. 일행이 안쪽에서 기어 나온다. 하나, 둘.<br>셋째가 나올 때 방패 가운데가 접혔다.<br><br>이제 받치는 것은 이쪽 팔과 어깨다. 종이 냄새가 코를 막는다. 서가 사이가 한 뼘씩 좁아진다.`,
        dieText:`서가는 사람 사정을 안 본다.<br><br>통로 하나가 닫혔다. 레일 위에 접힌 방패 테가 조금 삐져나와 있다. 슬리퍼 옆에.<br>다음 정각 장부에는 들어옴과 나감이 같게 적힐 것이다. 서가 사이에 든 것은 숫자에 들지 않는다.` },
      ok:`방패를 가로로 세우고 등을 댔다. 서가가 방패에 닿아 멈칫했다. 끼릭 소리가 버거워진다.<br><br>일행이 하나씩 빠져나왔다. 도면을 쥐고. 마지막 사람이 나오자 방패를 비틀어 뺐다.<br>서가가 쿵 하고 붙었다. 통로가 없어졌다. 방패 테에 두 군데 휜 자국이 남았다. 펴지 않았다. 그 정도 휜 것은 쓸 만하다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 손잡이 도는 쪽으로 달려간다.', k:'evade', dc:21,
      ok:`서가 끝으로 달렸다. 맨 끝 줄 손잡이 앞에 흰 가운이 서서 돌리고 있다.<br><br>방패로 손잡이 바퀴를 쳐서 끼웠다. 가운이 손을 떼고 이쪽을 본다. 표정이 없다.<br>그 사이 통로 안 일행이 다 나왔다. 가운은 손잡이를 놓고 걸어갔다. 딸깍 소리를 내며. 다음 정각에 다시 올 것이다.`,
      ng:`달려갔는데 끝 줄 손잡이 앞에 아무도 없다. 손잡이가 혼자 돈다.<br><br>멈추려고 잡았다. 손잡이가 손을 끌고 돈다. 손목이 꺾였다.<br>통로 안 일행이 겨우 빠져나왔다. 마지막 사람 옷자락이 서가에 물렸다. 찢고 나왔다. 서가가 붙는 소리가 등 뒤에서 났다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B3', t:'연결 통로 — 어긋나는 발판',
  x:`9호차와 8호차 사이. 고무 주름막이 찢어져 빗물이 들이친다.<br><br>
    발판 두 장이 겹쳐 있다. 열차가 휠 때마다 어긋났다가 맞물린다. 어긋날 때 틈으로 선로가 하얗게 흐른다.<br>
    일행 중에 다리를 다친 사람이 있다. 뛰어 건널 수가 없다.<br><br>
    뒤 칸에서 문 열리는 소리가 났다. 아무도 남아 있지 않은 칸이다.`,
  o:[
    { l:'① 무력을 쓴다 — 방패를 틈에 걸치고 위에서 누른다.', k:'steady', dc:20, cost:{ might:22 },
      ok:`방패를 두 발판 사이에 걸쳤다. 한쪽 테는 이쪽 발판에, 다른 쪽은 저쪽에. 무력을 실어 무릎으로 눌렀다.<br><br>열차가 휜다. 발판이 어긋나려 한다. 방패가 양쪽을 문 채 버틴다. 다리가 하나 놓였다.<br>다친 사람이 그 위로 건넜다. 다 건넌 뒤 방패를 들자 발판이 철컥 어긋났다. 틈 밑으로 침목이 날아간다.`,
      ng:`걸치는 순간 열차가 크게 휘었다. 방패가 틈에 비스듬히 끼었다.<br><br>무릎으로 눌러도 안 펴진다. 테가 선로 쪽으로 미끄러진다. 놓으면 방패를 잃는다.<br>안 놓았다. 팔 하나가 틈 위로 빠졌다. 바람이 팔을 잡아당긴다. 일행이 허리를 잡아 끌어 올렸다. 소매가 다 찢어져 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12, might:-6 } },
    { l:'② 맞물리는 박자를 세어 하나씩 건네준다.', k:'sense', dc:20,
      ok:`발판을 봤다. 어긋났다가 맞물리는 데 일정한 박자가 있다. 이음매를 넘는 소리 둘에 한 번.<br><br>맞물리는 순간마다 하나씩 건넸다. 다친 사람은 방패를 쥐게 하고 끌었다.<br>다 건넜다. 뒤 칸 문은 아직 열려 있다. 아무도 나오지 않았다. 나오지 않은 채 열려 있다.`,
      ng:`박자를 셌는데 굽이에서 박자가 바뀌었다.<br><br>다친 사람 발이 틈에 빠졌다. 정강이까지. 방패로 틈을 벌리고 끌어냈다.<br>신발 한 짝은 선로가 가졌다. 정강이에 쇠가 긁은 자국이 길다. 그 사람이 이를 악물고 소리를 안 냈다. 그게 더 아팠다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'문 — 저쪽에서 미는 손',
  x:`문을 닫았다. 저쪽에서 민다.<br><br>
    빗장이 없다. 손잡이 밑 구멍은 비어 있다. 열쇠는 저쪽 사람이 가져갔다.<br>
    일행이 뒤에서 창문을 뜯고 있다. 창살 나사가 넷이다. 둘 남았다.<br><br>
    미는 힘이 멎었다. 문 너머에서 손잡이를 쥐는 소리가 난다. 이번에는 당길 생각이다.`,
  o:[
    { l:'① 어깨로 문을 누르고 버틴다.', k:'steady', dc:21,
      doom:{ title:'당겨진 문', what:'문 너머로 끌려갑니다', dc:17, sec:50,
        text:`어깨를 문에 대고 발을 벌렸다. 밀면 버틴다. 그건 안다.<br><br>문이 당겨졌다. 한꺼번에. 기대던 몸이 문을 따라 쏠렸다. 문틈이 한 뼘 열리고 그 틈으로 손이 들어왔다. 팔이 셋인지 넷인지 모르겠다.<br>멱살이 잡혔다. 방패 테가 문틀에 걸려 버틴다.<br><br>저쪽은 어둡다. 빗물 냄새와 표백제 냄새. 몸이 반쯤 넘어갔다.`,
        dieText:`미는 것은 버틸 줄 알았다. 당기는 것은 몰랐다.<br><br>문이 다시 닫혔다. 저쪽에서 조용히. 빗장 거는 소리가 났다.<br>문틀에 방패 테 자국이 깊게 남았다. 문 밑 틈으로 빗물이 들어온다. 붉은 것이 섞였다가 금방 묽어진다.` },
      ok:`어깨를 대고 버티면서 발을 문 밑에 끼웠다. 미는 쪽이 아니라 당기는 쪽에 대비했다.<br><br>문이 당겨졌다. 발이 문을 물었다. 한 치 이상은 안 열린다. 그 한 치 틈으로 손가락이 들어오다 방패에 찍혀 나갔다.<br>등 뒤에서 창살 떨어지는 소리가 났다. 마지막으로 빠졌다. 문은 그 뒤에 활짝 열렸다. 아무도 서 있지 않았다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 경첩 쪽 틈에 방패 모서리를 박는다.', k:'fix', dc:20,
      ok:`문을 놓고 경첩 쪽 틈에 방패 모서리를 박아 넣었다. 문짝과 문틀 사이가 쇠로 물렸다.<br><br>문이 당겨졌다. 덜컹. 안 열린다. 경첩이 비명을 질렀다. 방패는 소리를 안 냈다.<br>창살이 다 빠졌다. 방패를 그대로 두고 갔다. 다른 방패는 없다. 그래도 두고 갔다. 팔은 아직 둘이다.`,
      ng:`박는데 문이 먼저 당겨졌다. 모서리가 틈에 반만 들어갔다.<br><br>문이 열리며 방패가 튕겨 나와 이쪽 정강이를 쳤다. 문틈으로 빛이 들어온다. 손전등이다.<br>몸으로 다시 막았다. 빛이 얼굴을 한 번 핥고 갔다. 창살 하나가 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'③ 문 밑 틈으로 저쪽 발을 본다.', k:'gaze', dc:21,
      ok:`엎드려 문 밑 틈을 봤다. 장화가 둘. 둘 다 왼쪽으로 기울었다. 오른손으로 쥐고 당길 자세다.<br><br>문 오른쪽 아래에 방패를 박고 왼쪽에 등을 댔다. 당기는 힘이 비틀려 들어왔다. 비틀린 힘은 반밖에 안 된다.<br>창살이 다 빠질 때까지 버텼다. 장화가 물러났다. 하나는 젖었고 하나는 마른 채로.`,
      ng:`틈으로 봤는데 아무 발도 없다.<br><br>그런데 문이 당겨진다. 발 없이 당기는 것이 저쪽에 있다.<br>보는 사이 문이 한 뼘 열렸다. 차가운 것이 이마에 닿았다. 뒤로 굴러 다시 문을 쳤다. 이마에 둥근 자국이 남았다. 무엇에 닿았는지 말하지 않기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B1', t:'정문 — 닫히는 철문',
  x:`정문 철문이 옆으로 미끄러지며 닫힌다. 사슬이 덜컹 울 때마다 한 뼘씩.<br><br>
    문틈은 지금 두 사람 너비다. 문 기둥 시계는 다섯 시 사 분.<br>
    일행 중 둘이 아직 선착장 쪽에 있다. 백 걸음 밖이다. 뛰어오는 중이다.<br><br>
    방패는 쇠다. 철문도 쇠다. 쇠와 쇠가 만나면 둘 중 하나가 휜다.`,
  o:[
    { l:'① 방패를 문틈에 세워 철문을 문다.', k:'steady', dc:22,
      doom:{ title:'물린 철문', what:'철문 사이에 끼었습니다', dc:18, sec:50,
        text:`방패를 문틈에 세로로 세우고 어깨로 받쳤다. 철문이 와서 방패에 닿았다.<br><br>멎었다. 사슬이 덜컹 운다. 다시 운다. 철문이 방패를 민다. 방패가 이쪽 어깨를 민다.<br>둘이 뛰어온다. 하나가 지났다.<br><br>방패가 휘기 시작했다. 휜 방패는 문틈을 지키지 못한다. 휜 만큼 철문이 들어와 어깨를 문다.`,
        dieText:`쇠와 쇠가 만나면 둘 중 하나가 휜다.<br><br>그날은 방패가 휘었고, 그다음은 사람이었다.<br>다섯 시 십 분에 정문이 다 닫혔다. 문 기둥 아래 휜 쇠판이 하나 물려 있다. 빗물이 그 위로 흘러 큰길로 나간다. 물만 나간다.` },
      ok:`방패를 문틈에 세웠다. 철문이 와서 물었다. 사슬이 덜컹 울고 멎었다. 기계실 톱니가 헛돈다.<br><br>뛰어온 둘이 방패 옆을 지나 문밖으로 빠졌다. 마지막으로 어깨를 빼며 방패를 뽑았다.<br>철문이 탕 하고 닫혔다. 방패 가장자리에 철문 모양으로 패인 자국이 생겼다. 손가락 두 마디 깊이. 문 쪽도 패였을 것이다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 뛰어오는 둘에게 달려가 등을 민다.', k:'bond', dc:21,
      ok:`문을 두고 둘 쪽으로 뛰었다. 하나는 다리를 절고 있다.<br><br>그 사람 겨드랑이에 어깨를 넣고 방패를 등 뒤로 돌렸다. 둘을 앞세우고 밀었다.<br>문틈이 한 사람 너비일 때 첫째가, 반 사람 너비일 때 둘째가 빠졌다. 이쪽은 옆으로 비틀어 빠졌다. 방패가 걸렸다. 끈을 풀었다. 문이 방패만 물고 닫혔다. 다시 사면 된다.`,
      ng:`달려갔는데 다리 저는 사람이 넘어졌다. 일으키는 데 숨 다섯을 썼다.<br><br>문틈이 반 사람 너비다. 둘을 밀어 넣었다. 이쪽 차례에 틈이 손바닥만 해졌다.<br>방패를 틈에 걸고 비집었다. 갈비뼈가 철문을 긁고 나왔다. 숨 쉴 때마다 옆구리에서 쇳소리가 난다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'B2', t:'응급실 통로 — 무릎 높이',
  x:`구급차 출입구 셔터가 내려온다. 모터가 딸깍딸깍 끊어지며 돈다.<br><br>
    셔터 밑 틈은 무릎 높이다. 그 밑으로 비가 들이친다. 바깥 가로등이 젖은 바닥에 주황으로 번진다.<br>
    뒤 계단에서 계수기 누르는 소리가 내려온다. 딸깍. 딸깍.<br><br>
    셔터는 무겁다. 방패도 무겁다. 어느 쪽이 더 무거운지는 들어 보면 안다.`,
  o:[
    { l:'① 무력을 쓴다 — 방패 모서리를 세워 셔터를 받친다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`방패를 세로로 세워 셔터 밑에 넣었다. 셔터가 방패 머리에 닿았다. 무력을 팔에서 바닥까지 내렸다.<br><br>모터가 버둥거린다. 셔터가 더는 안 내려온다. 방패 높이만큼 틈이 남았다.<br>일행이 하나씩 엎드려 빠졌다. 마지막으로 이쪽이 방패를 쥔 채 굴렀다. 방패를 빼는 순간 셔터가 바닥을 쳤다. 계수기 소리가 그 너머에서 멈췄다.`,
      ng:`세웠는데 모터가 셌다. 방패가 바닥으로 기울었다.<br><br>틈이 정강이 높이로 줄었다. 일행이 배를 바닥에 대고 기어 나갔다. 이쪽 차례에는 손바닥 높이.<br>방패를 놓고 옆으로 누워 비집고 나왔다. 셔터 밑단이 귀를 긁었다. 방패는 안에 남았다. 셔터에 눌려 우는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12, might:-5 } },
    { l:'② 셔터 모터함을 쳐서 멈춘다.', k:'break', dc:21,
      ok:`셔터 옆 벽에 모터함이 붙었다. 쇠 뚜껑. 방패 모서리로 내리쳤다. 두 번.<br><br>뚜껑이 우그러지며 딸깍 소리가 멎었다. 셔터가 정강이 높이에 섰다.<br>다 기어 나갔다. 모터함 안에서 연기가 한 줄 올라왔다. 이 건물에서 처음으로 무언가가 멈췄다.`,
      ng:`내리쳤는데 뚜껑이 안 우그러진다. 대신 경보가 울렸다.<br><br>복도 형광등이 한꺼번에 켜졌다. 계수기 소리가 빨라진다.<br>셔터 밑으로 굴렀다. 정강이가 셔터 밑단에 찍혔다. 안쪽으로 손을 뻗어 마지막 사람을 끌어냈다. 그 사람 발목에 흰 손이 잡혔다가 떨어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 먼저 기어 나가 바깥에서 들어 올린다.', k:'evade', dc:20,
      ok:`엎드려 먼저 셔터 밑을 빠졌다. 빗속이다. 바깥에서 셔터 밑단에 손가락을 걸었다.<br><br>안에서 미는 것보다 밖에서 드는 게 낫다. 다리 힘이 다 쓰인다. 셔터가 한 뼘 올라갔다.<br>일행이 굴러 나왔다. 손을 놓자 셔터가 내려앉았다. 손가락 끝이 한동안 하얬다.`,
      ng:`빠졌는데 바깥에 주차장 경비가 서 있다. 우산을 들었다. 이쪽을 보고 웃는다.<br><br>못 본 척하고 셔터를 들었다. 경비가 우산 끝으로 이쪽 손등을 눌렀다. 아프게.<br>일행이 다 나올 때까지 손등을 내줬다. 경비는 웃으며 계수기를 한 번 눌렀다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B3', t:'4호차 지붕 — 한 뼘',
  x:`3호차 문이 쇠판으로 막혔다. 지붕으로 넘어가야 한다.<br><br>
    지붕에 올라서니 비가 옆으로 쏟아진다. 앞에서 기적이 길게 운다. 터널이 다가온다는 소리다.<br>
    터널 천장은 객차 지붕보다 한 뼘 높다고 했다. 엎드린 사람 하나가 한 뼘이다.<br><br>
    방패를 등에 멨다. 등에 멘 방패가 한 뼘보다 두껍다.`,
  o:[
    { l:'① 방패를 멘 채 엎드려 기어간다.', k:'steady', dc:22,
      doom:{ title:'한 뼘', what:'터널 천장에 쓸려 갑니다', dc:18, sec:45,
        text:`방패를 멘 채 지붕에 엎드렸다. 손으로 환기구 테를 잡고 기었다.<br><br>터널이 왔다. 소리가 먼저 귀를 막았다. 바람이 몸을 지붕에 누른다.<br>등에서 쇳소리가 났다. 방패가 터널 천장에 닿았다. 긁힌다. 끈이 어깨를 잡아당긴다.<br><br>천장이 방패를 끌고 간다. 방패가 등을 끌고 간다. 손이 환기구 테에서 미끄러진다.`,
        dieText:`엎드린 사람 하나가 한 뼘이다. 방패를 멘 사람은 한 뼘이 아니었다.<br><br>터널을 빠져나온 지붕 위에 끈 한 줄이 환기구 테에 감겨 펄럭인다.<br>터널 안 어딘가에서 쇠판 하나가 오래 굴렀다. 열차는 그 소리를 듣지 못했다.` },
      ok:`방패를 멘 채 엎드렸다가, 터널 소리가 들리는 순간 끈을 풀어 방패를 옆구리로 끌어내렸다.<br><br>터널이 왔다. 등 위를 무언가 스치고 지나간다. 천장의 이끼가 목덜미를 핥는다. 한 뼘이 정말 한 뼘이다.<br>터널을 빠져나왔다. 방패는 옆구리에 안겨 있다. 다시 멨다. 3호차 뚜껑까지 네 걸음.`,
      win:{ exp:24, dream:3 } },
    { l:'② 방패를 벗어 앞으로 밀며 납작하게 간다.', k:'fix', dc:21,
      ok:`방패를 벗어 앞에 눕혔다. 그 뒤에 몸을 붙이고 방패를 밀며 기었다. 썰매 끄는 꼴이다.<br><br>터널이 왔다. 방패가 지붕 철판에 붙어 바람을 막는다. 얼굴에 빗물이 안 들이친다.<br>천장이 머리 위를 지나갔다. 머리카락이 쓸렸다. 그것뿐이다. 3호차 뚜껑에 방패가 먼저 닿았다.`,
      ng:`밀며 기는데 바람이 방패 밑으로 들어갔다. 방패가 들린다. 연처럼.<br><br>잡았다. 놓으면 날아간다. 잡으면 몸이 들린다. 터널이 다가온다.<br>방패를 지붕에 엎어 누르고 그 위에 엎드렸다. 터널 천장이 등을 긁고 지나갔다. 외투 등판이 터널에 남았다. 살갗도 조금.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 선 채로',
  x:`누울 자리가 없다. 바닥에 물이 찼다. 앉으면 엉덩이가 잠긴다.<br><br>
    일행이 벽에 기대 선 채로 눈을 감는다. 고개가 떨어질 때마다 깨어난다.<br>
    방패를 땅에 세우면 기댈 데가 하나 생긴다. 사람 하나 몫이다.<br><br>
    쫓는 것들은 자지 않는다. 쉬는 시간은 길어야 숨 백 번이다.`,
  o:[
    { l:'① 방패를 세우고 기대어 선 채로 잠든다.', k:'steady', dc:20, wake:1,
      ok:`방패를 비스듬히 세우고 바닥에 박았다. 이마와 어깨를 방패 위 테에 걸었다. 무릎을 반쯤 굽혔다.<br><br>무게가 방패와 발로 나뉜다. 어느 쪽도 쓰러지지 않는다. 눈을 감았다. 꿈은 없었다.<br>숨 백 번이 지나자 저절로 눈이 떠졌다. 다리가 안 저리다. 방패 위 테에 이마 자국이 하얗다.<br><br>버티는 자세로 잤다. 자는 동안에도 몸이 버텼다. 언제 어디서든 설 수 있으면, 언제 어디서든 쉴 수도 있다.`,
      ng:`기댔는데 잠이 깊게 들었다. 무릎이 풀렸다.<br><br>방패와 같이 물바닥에 쓰러졌다. 쇠판이 물을 치는 소리가 컸다.<br>다들 깨서 이쪽을 봤다. 멀리서 무언가 그 소리 쪽으로 방향을 바꾸는 소리가 났다. 아무도 다시 잠들지 못했다.`,
      win:{ exp:22, dream:2, hp:8 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 동료를 방패에 기대어 재우고 혼자 깨어 있는다.', k:'bond', dc:20,
      ok:`방패를 벽에 비스듬히 세우고 제일 지친 동료를 거기 기대게 했다. 금방 잠들었다.<br><br>그 앞에 섰다. 졸지 않으려고 손톱으로 손바닥을 눌렀다.<br>숨 백 번. 동료가 눈을 떴다. 얼굴에 핏기가 돌아왔다. 이쪽 손바닥에는 손톱 자국이 반달로 줄을 섰다.`,
      ng:`세워 주고 깨어 있었는데 이쪽이 먼저 졸았다. 선 채로.<br><br>눈을 떴을 때 방패 앞에 누가 서 있었다. 이쪽 대신. 젖은 우비. 자는 동료를 내려다본다.<br>소리를 지르자 사라졌다. 동료 머리맡에 젖은 발자국이 둘 남았다. 그 뒤로 동료는 이쪽 옆에서만 잤다.`,
      win:{ exp:15, mind:8 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 쇠 손잡이',
  x:`냉동 창고 문 위 온도계가 영하 이십 도를 가리킨다. 숨을 데는 이 안밖에 없다.<br><br>
    방패 손잡이는 쇠다. 가죽 감은 데가 닳아 쇠가 드러났다.<br>
    이 추위에 맨손으로 쇠를 쥐면 손이 쇠에 붙는다. 떼면 살갗이 남는다.<br><br>
    뒤 골목에서 손전등이 돌아온다. 쥐는 법을 고를 시간은 한 번뿐이다.`,
  o:[
    { l:'① 맨손으로 쥔 채 들어가 끝까지 놓지 않는다.', k:'steady', dc:21,
      ok:`쥔 채로 들어갔다. 손바닥이 손잡이에 쩍 하고 붙었다. 놓지 않았다.<br><br>놓지 않으면 안 찢어진다. 쥔 손에 숨을 불어 넣으며 버텼다. 매달린 고기 사이에서 한 시간.<br>밖으로 나와서야 천천히 녹여 뗐다. 살갗 한 겹이 손잡이에 남았다. 그 대신 방패는 한 번도 떨어지지 않았다. 고기 사이를 지나던 것이 방패 테를 두 번 건드리고 갔다.`,
      ng:`쥐고 들어갔는데 고기 사이에서 무언가 부딪혀 왔다. 방패를 휘둘렀다.<br><br>휘두르다 손이 미끄러지며 떨어졌다. 손바닥 살갗이 손잡이에 그대로 남았다.<br>피가 금방 얼었다. 아프지 않다. 그게 더 나쁘다. 한 시간 동안 다른 손으로만 방패를 쥐었다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-26, mind:-12 } },
    { l:'② 소매를 끌어내려 손을 감싸 쥔다.', k:'fix', dc:20,
      ok:`소매를 손등까지 끌어내리고 그 위로 손잡이를 쥐었다. 천 한 겹이 쇠와 살을 갈랐다.<br><br>안은 하얗다. 매달린 고기에 성에가 피었다. 고기 하나를 끊어 품에 넣었다. 얼었어도 고기다.<br>한 시간을 버텼다. 소매가 손잡이에 얼어붙어 나올 때 소매째 뜯었다. 손은 멀쩡하다.`,
      ng:`소매를 끌어내렸는데 젖은 소매다. 쇠보다 먼저 얼었다.<br><br>손이 소매 안에서 굳어 간다. 손가락이 안 움직인다. 방패를 쥔 모양 그대로 굳었다.<br>나와서 녹이는 데 반 시간. 손가락 마디가 바늘로 쑤시듯 깨어났다. 손톱 하나가 검게 변했다.`,
      win:{ exp:15, item:'짐승 고기' }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B2', t:'주방 — 열두 번째 박자',
  x:`조리대마다 배식 직원이 칼을 든다. 탁, 탁, 탁. 도마 위에 아무것도 없는데 썬다.<br><br>
    열두 번에 한 번, 다 같이 칼을 든 채 멈춘다. 숨 한 번의 틈이다.<br>
    음식 승강기는 조리대 줄 끝에 있다. 칼 든 손 사이로 지나가야 한다.<br><br>
    칼이 멈출 때 다들 고개를 든다. 위생모 밑 눈들이 같은 곳을 본다. 지나가는 것을.`,
  o:[
    { l:'① 방패를 옆에 세우고 멈춘 박자에 지나간다.', k:'steady', dc:21,
      ok:`방패를 칼 쪽 옆구리에 세워 붙였다. 일행을 방패 뒤에 줄 세웠다.<br><br>열둘. 칼이 멈췄다. 걸었다. 눈들이 고개를 든다. 방패를 본다. 쇠판을 보는 눈은 쇠판만 본다.<br>탁. 다시 썰기 시작했을 때 줄 끝에 닿았다. 칼 하나가 방패 테를 스치고 도마로 돌아갔다. 테에 하얀 금이 하나 생겼다.`,
      ng:`세우고 걸었는데 일행 하나가 박자를 놓쳤다. 칼이 다시 움직일 때 그 사람이 방패 밖에 있었다.<br><br>칼 하나가 도마 대신 그쪽으로 내려왔다. 방패를 휘둘러 막았다. 칼날이 방패에 박혀 손목이 울렸다.<br>칼을 든 직원이 칼을 뽑아 도마로 돌아갔다. 다시 썬다. 아무 일 없었다는 듯이. 손목이 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'② 박자를 세어 한 사람씩 보낸다.', k:'sense', dc:20,
      ok:`벽에 붙어 박자를 셌다. 열하나에 첫 사람 등을 쳤다. 열둘에 그 사람이 지났다.<br><br>한 박자에 한 사람. 다섯 번을 기다렸다. 그동안 칼이 예순 번 내려왔다. 셌다.<br>마지막이 이쪽이다. 방패를 머리 위에 얹고 지났다. 눈들이 이쪽을 봤다. 위생모 하나가 고개를 갸웃했다. 숫자가 맞는지 세는 얼굴이다.`,
      ng:`셌는데 박자가 열둘이 아니라 열셋이었다. 이번에만.<br><br>지나가던 사람이 칼 내려오는 데 섰다. 끌어당겼다. 칼끝이 그 사람 소매를 도마에 박았다.<br>소매를 찢고 빠졌다. 그 사이 다른 칼들이 다 멈췄다. 열세 번째 박자에. 눈들이 다 이쪽을 봤다. 오래.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-14 } },
    { l:'③ 구석 선반의 소금 단지를 챙기며 돈다.', k:'luck', dc:20,
      ok:`조리대 뒤로 돌아가는 길이 있다. 선반 사이 좁은 틈. 칼 쪽에서 안 보인다.<br><br>선반에 굵은 소금 덩이가 한 단지 놓였다. 한 덩이 집었다. 소금은 썩지 않는다.<br>틈은 좁아 방패를 옆으로 들어야 했다. 테가 선반을 긁는 소리가 칼 소리에 묻혔다. 묻히는 박자에만 움직였다.`,
      ng:`돌아가는데 선반 끝에 위생모 하나가 서 있다. 칼 대신 국자를 들었다.<br><br>국자가 솥을 휘젓다 멈췄다. 고개가 이쪽으로 돈다. 방패를 얼굴 앞으로 들었다.<br>국자가 방패를 두드렸다. 탁, 탁, 탁. 칼 박자에 맞춰. 열두 번. 그리고 비켜 줬다. 귀가 멍했다.`,
      win:{ exp:14, item:'소금 덩이' }, lose:{ mind:-14, spirit:-12 } }
  ] },

{ at:'B3', t:'탄수차 — 흘러내리는 석탄',
  x:`탄수차 위다. 지붕이 없다. 젖은 석탄이 산처럼 쌓였다.<br><br>
    열차가 휠 때마다 석탄이 한쪽으로 쏟아져 내린다. 가장자리에 난간이 없다. 아래는 다리 밑 검은 강이다.<br>
    앞서 가던 일행 하나가 석탄과 같이 미끄러진다. 손이 허공을 긁는다.<br><br>
    방패를 석탄에 박으면 박힌다. 얼마나 버틸지는 모른다.`,
  o:[
    { l:'① 무력을 쓴다 — 방패를 석탄에 박고 손목을 잡는다.', k:'steady', dc:21, cost:{ might:26 },
      ok:`방패를 석탄 더미에 세로로 박았다. 한 팔로 손잡이를 감고, 무력을 다 실어 다른 팔을 뻗었다.<br><br>손목이 잡혔다. 미끄러지는 사람 무게와 석탄 무게가 같이 왔다. 방패가 석탄을 가르며 반 뼘 밀렸다. 거기서 섰다.<br>끌어올렸다. 둘이 방패를 끌어안고 숨을 몰아쉬었다. 석탄 가루가 빗물에 녹아 얼굴이 검게 흘러내린다.`,
      ng:`박고 잡았는데 방패가 석탄째 미끄러진다. 박힌 데가 같이 흐른다.<br><br>가장자리까지 갔다. 다리 하나가 허공에 나갔다. 손목을 놓지 않았다.<br>열차가 반대로 휘었다. 석탄이 거꾸로 흘렀다. 그 덕에 살았다. 어깨가 빠졌다가 제자리에 들어갔다. 들어갈 때 소리가 났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12, might:-6 } },
    { l:'② 방패를 깔고 미끄러져 내려가 아래에서 받는다.', k:'evade', dc:21,
      ok:`방패를 석탄 위에 깔고 앉아 미끄러졌다. 빨리. 미끄러지는 사람보다 빨리.<br><br>가장자리 바로 앞에서 발로 방패를 세웠다. 쇠판이 턱이 됐다. 미끄러지던 사람이 그 턱에 걸렸다.<br>둘이 같이 가장자리에 걸터앉았다. 발밑이 강이다. 방패 테 하나가 둘을 붙들고 있다.`,
      ng:`미끄러졌는데 방패가 너무 빨랐다. 그 사람을 지나쳤다.<br><br>가장자리에서 방패가 허공으로 튀었다. 몸이 따라 나가려는 걸 석탄에 손을 박아 멈췄다. 손톱이 다 들렸다.<br>그 사람은 위에서 혼자 멈췄다. 방패는 강으로 떨어졌다. 다음 칸 연결 고리에 걸려 대롱대롱 매달렸다. 겨우 건졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B', t:'배신 — 등 뒤에 둔 얼굴',
  x:`앞에서 손전등들이 온다. 방패를 앞으로 세웠다.<br><br>
    등 뒤에는 아까 구해 준 사람이 있다. 젖은 외투. 고맙다고 두 번 말했다. 두 번째는 너무 정확했다.<br>
    방패는 한쪽만 막는다. 앞을 막으면 등이 빈다. 등은 늘 동료에게 맡겼다.<br><br>
    등 뒤에서 금속이 칼집에서 빠지는 소리가 났다. 아주 작게. 빗소리보다 작게.`,
  o:[
    { l:'① 반쯤 돌아서서 방패를 옆으로 세운다.', k:'steady', dc:21, wake:1,
      ok:`정면에서 반쯤 몸을 틀었다. 방패를 옆구리에 세웠다. 앞의 빛도, 등 뒤의 사람도 한 눈에 걸린다.<br><br>등 뒤 사람의 손이 왔다. 방패 테에 걸렸다. 칼날이 쇠를 긁었다. 앞의 손전등들은 아직 다섯 걸음 밖이다.<br>테로 그 손목을 쳤다. 칼이 물에 떨어졌다. 사람은 빗속으로 뛰었다.<br><br>앞과 뒤 사이에 옆이 있다. 옆으로 서면 방패 하나가 두 쪽을 본다. 발이 그 각도를 기억했다. 이제는 등을 맡기기 전에 반 걸음 비켜 선다.`,
      ng:`돌아서는데 반 박자 늦었다. 등 뒤 손이 먼저 왔다.<br><br>옆구리가 뜨겁다. 깊지는 않다. 방패 끈이 칼을 반쯤 막았다.<br>그 사람은 빗속으로 사라졌다. 앞의 손전등들이 그제야 이쪽에 닿았다. 옆구리를 누르며 방패를 들었다. 손이 젖는다. 빗물보다 따뜻하다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-14 } },
    { l:'② 그 사람을 앞으로 세운다.', k:'gaze', dc:21,
      ok:`돌아보지 않고 말했다. 앞으로 오라고. 빛이 오는 쪽을 같이 보자고.<br><br>그 사람이 머뭇거렸다. 한 박자. 그 한 박자가 대답이다.<br>방패 옆으로 끌어내 앞에 세웠다. 손에 든 것이 빛에 번쩍했다. 손전등 줄이 그 사람을 보고 멈췄다. 서로 아는 얼굴이다. 그 사이로 일행이 빠져나갔다.`,
      ng:`앞으로 오라고 했는데 그 사람이 순순히 왔다. 웃으며.<br><br>앞에 서자마자 손전등 쪽으로 손을 흔들었다. 여기 있다고.<br>빛이 다 이쪽으로 꽂혔다. 방패를 들고 뒷걸음질 쳤다. 그 사람은 빛 쪽으로 걸어갔다. 우산을 받아 쓰고.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'③ 그대로 믿고 앞만 막는다.', k:'bond', dc:22,
      ok:`등을 그대로 뒀다. 방패는 앞에. 믿기로 했다. 믿는 것도 버티는 일이다.<br><br>등 뒤에서 칼집 소리가 한 번 더 났다. 이번엔 들어가는 소리다.<br>손전등들이 지나갔다. 그 사람이 등 뒤에서 작게 말했다. 미안하다고. 무엇이 미안한지는 말하지 않았다. 날이 밝을 때까지 다시 묻지 않았다.`,
      ng:`믿었다. 등 뒤 사람이 등에 손을 얹었다. 따뜻하다.<br><br>그 손이 등을 밀었다. 방패째 앞으로 넘어졌다. 손전등 줄 한가운데로.<br>빛이 내리꽂혔다. 방패를 머리 위로 덮고 굴렀다. 다 빠져나왔을 때 그 사람은 없었다. 등에 손바닥 자국이 남은 것 같았다. 아무도 못 봤다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'B', t:'시계 — 다리 다친 사람',
  x:`남은 시간은 칠 분이다. 문까지는 계단 셋과 복도 하나.<br><br>
    일행 하나가 다리를 다쳤다. 발목이 돌아갔다. 혼자 서지 못한다.<br>
    업으면 방패를 버려야 한다. 방패를 메면 업을 수 없다.<br><br>
    등 뒤에서 무언가 계단을 오른다. 한 칸씩. 서두르지 않는다.`,
  o:[
    { l:'① 다친 사람을 방패에 눕혀 끈다.', k:'steady', dc:21,
      ok:`방패를 뒤집어 눕히고 다친 사람을 그 위에 앉혔다. 끈을 어깨에 걸고 끌었다.<br><br>쇠판이 젖은 바닥에서 미끄러진다. 끌린다. 계단에서는 방패 테가 모서리마다 쿵, 쿵.<br>다친 사람이 이를 악물었다. 칠 분 중 육 분을 썼다. 문 앞에서 끈을 놓았을 때 어깨에 끈이 파고든 줄이 둘이다. 하나는 방패 끈, 하나는 오늘 생긴 것.`,
      ng:`눕혀 끄는데 계단에서 방패가 옆으로 돌았다. 다친 사람이 떨어졌다. 다친 발부터.<br><br>소리를 질렀다. 등 뒤 발소리가 한 칸에서 두 칸으로 빨라졌다.<br>다시 올려 끌었다. 문에 닿았을 때 남은 시간은 없었다. 문은 아직 열려 있었다. 운이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 방패를 계단에 박아 두고 업고 뛴다.', k:'bond', dc:21,
      ok:`방패를 계단 중간에 가로로 박았다. 올라오는 것의 길을 막는 턱이다. 다친 사람을 업었다.<br><br>뛰었다. 등 뒤 계단에서 쇠판이 무언가에 부딪히는 소리가 났다. 한 번. 그리고 그 소리가 멈췄다.<br>문에 닿았다. 방패는 저 계단에 있다. 다친 사람이 이쪽 귀에 대고 말했다. 다시 사 주겠다고.`,
      ng:`박고 업었는데 다친 사람이 생각보다 무겁다. 계단 두 칸에서 무릎이 꺾였다.<br><br>등 뒤 계단에서 방패가 우는 소리가 났다. 넘어오는 소리다. 생각보다 빨리.<br>다시 일어나 뛰었다. 문에 닿았을 때 무릎에서 물이 찬 소리가 났다. 방패는 다시 볼 일이 없을 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'골목 — 젖은 총성',
  x:`골목 끝 어둠에서 불꽃이 튀었다. 소리는 그다음에 왔다. 빗소리를 찢고.<br><br>
    벽에 구멍이 났다. 이쪽 머리 한 뼘 옆이다.<br>
    방패는 화살을 막는다. 돌을 막는다. 이것을 막아 본 적은 없다.<br><br>
    두 번째 불꽃이 튈 자리를 저쪽이 고르고 있다. 일행은 아직 골목 한가운데다.`,
  o:[
    { l:'① 무력을 쓴다 — 방패를 세우고 일행 앞에 선다.', k:'steady', dc:22, cost:{ might:20 }, wake:1,
      ok:`일행 앞으로 나가 방패를 세웠다. 무력을 발바닥까지 내렸다.<br><br>두 번째가 왔다. 방패 가운데에 맞았다. 망치로 친 것 같다. 몸이 뒤로 밀리려 할 때 반 걸음 물러서며 받았다. 버티지 않고 반 걸음 내줬다. 그 반 걸음이 충격을 다 먹었다.<br>팔이 안 꺾였다. 셋째, 넷째. 그때마다 반 걸음. 일행이 골목을 빠졌다.<br><br>버티는 것은 서 있는 것이 아니었다. 내줄 만큼만 내주고 나머지를 지키는 것이다. 무릎이 그 셈을 배웠다. 방패 가운데 움푹 들어간 자국 넷이 그 셈이다.`,
      ng:`세웠는데 두 번째가 방패 가장자리에 맞았다. 방패가 돌았다.<br><br>돈 방패 테가 이쪽 턱을 쳤다. 이가 흔들린다. 셋째는 방패 밑으로 와서 허벅지를 긁었다.<br>일행이 이쪽을 끌어 골목 밖으로 빠졌다. 피가 신발 안으로 고인다. 깊지 않다. 그래도 많다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-34, mind:-12, might:-6 } },
    { l:'② 다 같이 엎드려 벽에 붙는다.', k:'evade', dc:20,
      ok:`엎드리라고 소리쳤다. 다들 젖은 바닥에 배를 깔았다. 이쪽은 방패를 머리 위로 덮었다.<br><br>세 번째, 네 번째가 위로 지나갔다. 벽돌 조각이 방패 위로 쏟아진다.<br>불꽃이 멈췄다. 탄을 갈아 끼우는 소리. 그 틈에 다 같이 기어서 모퉁이를 돌았다.`,
      ng:`엎드렸는데 물웅덩이 한가운데다. 몸이 다 잠겼다.<br><br>방패를 덮었는데 웅덩이에 비친 불꽃이 방패 밑으로 보였다. 이쪽 위치도 비쳤을 것이다.<br>바로 옆 물이 튀었다. 한 번, 두 번. 기었다. 모퉁이를 돌았을 때 귀에서 소리가 안 빠졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B', t:'네온 아래 — 쇠판에 비친 것',
  x:`붉은 네온이 젖은 골목을 칠한다. 글자 하나가 나가 깜빡인다.<br><br>
    방패 앞면이 그 빛을 받아 붉게 번들거린다. 쇠판에 골목이 비친다. 거꾸로, 일그러져.<br>
    비친 골목 맨 끝에 사람이 하나 서 있다. 이쪽 등 뒤 방향이다.<br><br>
    돌아보면 없을 것이다. 이런 밤에는 늘 그렇다.`,
  o:[
    { l:'① 방패 면을 소매로 닦아 뒤를 비춰 본다.', k:'gaze', dc:21, wake:1,
      ok:`돌아보지 않았다. 소매로 쇠판 한 귀퉁이를 닦았다. 손바닥만 하게 맑아졌다.<br><br>방패를 조금 기울이자 등 뒤 골목이 그 안에 들어왔다. 사람이 우산을 접는다. 접은 우산 끝을 이쪽으로 겨눈다. 끝이 쇠다.<br>방패를 기울인 채 걸었다. 우산이 따라온다. 모퉁이에서 방패를 돌려 그 끝을 받았다. 등 뒤에서 오는 것을 앞으로 받았다.<br><br>방패는 앞만 막는 줄 알았다. 닦으면 뒤를 본다. 쇠판 한 귀퉁이를 늘 닦아 두게 됐다. 거기가 등 뒤의 눈이다.`,
      ng:`닦는데 쇠판에 비친 사람이 이쪽을 보고 손을 흔든다.<br><br>손을 흔드는 쪽이 이쪽 어깨 바로 뒤다. 쇠판 속에서는 그렇다. 등에 숨이 닿는다.<br>방패를 휘두르며 돌았다. 아무도 없다. 방패 테가 벽을 쳐 네온 간판 하나가 깨졌다. 골목이 어두워졌다. 어둠 속에서 누가 웃었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 홱 돌아본다.', k:'sense', dc:20,
      ok:`홱 돌았다. 골목 끝은 비었다. 그런데 바닥 물웅덩이 하나가 아직 흔들린다. 방금 누가 밟았다.<br><br>웅덩이 옆 벽에 우산 하나가 기대 있다. 접힌 채. 손잡이가 따뜻하다.<br>우산은 두고 왔다. 그 사람은 우산 없이 이 비를 맞고 있을 것이다. 이쪽을 보면서.`,
      ng:`돌았는데 골목이 비었다. 다시 방패를 봤다. 쇠판 속 사람이 한 걸음 가까워졌다.<br><br>다시 돌았다. 비었다. 방패를 봤다. 또 한 걸음.<br>그 뒤로 방패를 안 봤다. 방패 앞면을 몸 쪽으로 돌려 멨다. 등에 쇠판이 닿을 때마다 차가운 것이 쇠판 너머에서 같이 닿는 것 같았다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 방패를 등에 메고 걸음을 바꾸지 않는다.', k:'steady', dc:20,
      ok:`방패를 등에 돌려 멨다. 앞면이 뒤를 본다. 걸음은 그대로.<br><br>등 뒤에서 무언가 쇠판에 부딪혔다. 툭. 가볍다. 돌멩이인지 손가락인지.<br>안 돌아봤다. 걸음을 안 바꿨다. 뒤의 것은 이쪽이 겁을 먹는 순간을 기다렸다. 그 순간이 오지 않자 골목 끝에서 멈췄다.`,
      ng:`메고 걸었다. 쇠판에 무언가 계속 부딪힌다. 툭, 툭, 툭. 걸음 박자에 맞춰.<br><br>참았다. 열 걸음, 스무 걸음. 박자가 점점 세진다.<br>서른 걸음째 결국 돌았다. 아무것도 없다. 등이 아프다. 방패 뒷면을 보니 안쪽에 손가락 자국이 찍혀 있다. 등과 방패 사이에서.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] }

]);

// ------------------------------------------
// 생존가 · 자원 없음
// ------------------------------------------
kJob('survivor', 'B', [

{ at:'B', t:'들어가는 밤 — 젖은 주머니',
  x:`비가 옷을 지나 주머니까지 들어왔다.<br><br>
    주머니를 뒤집었다. 성냥은 젖었다. 말린 것은 불었다. 끈은 물을 먹어 두 배로 무겁다.<br>
    살아남는 데 익은 사람은 가진 것을 먼저 센다. 오늘은 세는 것보다 버릴 것을 고르는 게 먼저다.<br><br>
    젖은 것은 무겁다. 무거운 것은 뛰지 못하게 한다. 이 밤은 뛸 일이 많을 것이다.`,
  o:[
    { l:'① 성냥을 머리카락 속에 넣어 말린다.', k:'fix', dc:19,
      ok:`성냥 다섯 개를 골라 머리카락 속에 꽂았다. 정수리 쪽이 몸에서 제일 따뜻하고 비를 늦게 맞는다.<br><br>모자를 눌러 썼다. 한 시간쯤 지나 하나를 꺼내 긁었다. 불이 붙었다.<br>나머지 넷은 그대로 두었다. 머리 위에 불 넷을 이고 다닌다.`,
      ng:`꽂았는데 모자 챙에서 물이 흘러 정수리로 들어갔다.<br><br>한 시간 뒤 꺼낸 성냥은 머리끝까지 젖었다. 긁자 머리가 뭉개졌다.<br>남은 넷도 다 그렇다. 머리카락에서 유황 냄새만 난다. 밤새 그 냄새가 이쪽 자리를 알렸다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-12, spirit:-12 } },
    { l:'② 젖은 것을 다 버리고 마른 것 셋만 남긴다.', k:'steady', dc:20, wake:1,
      ok:`하나씩 쥐어 봤다. 무겁고 젖은 것은 바닥에 내려놓았다. 끈, 여분 양말, 불은 빵.<br><br>남은 것은 셋이다. 칼, 기름종이에 싼 성냥, 말린 고기 한 줄. 주머니가 가볍다. 발이 가볍다.<br>버린 것들이 아깝지 않았다. 아깝다는 마음도 같이 버렸다.<br><br>모으는 것은 오래 배웠다. 버리는 것은 오늘 배웠다. 무엇이 사람을 살리는지 손이 무게로 안다. 이제 쥐어 보기만 하면 남길 것과 버릴 것이 갈린다.`,
      ng:`버리다가 손이 멈췄다. 이것도 쓸 데가 있을 것 같다. 저것도.<br><br>하나도 못 버렸다. 젖은 주머니가 허벅지에 들러붙는다.<br>뛸 일이 생겼을 때 주머니 하나가 터져 쏟아졌다. 줍지 못하고 뛰었다. 결국 다 버렸다. 고르지 못하고.`,
      win:{ exp:22, dream:2, item:'말린 고기' }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 한 시간',
  x:`냉동 창고 문이 등 뒤에서 닫혔다. 안쪽 문고리는 떼어져 나사 구멍만 남았다.<br><br>
    온도계는 영하 이십 도. 누가 바늘 옆에 손톱으로 그어 놓았다. 한 시간.<br>
    추위는 사람을 금방 죽이지 않는다. 먼저 졸리게 한다. 졸린 사람은 앉는다. 앉은 사람은 안 일어난다.<br><br>
    밖에서 손전등이 지나가려면 한 시간은 걸릴 것이다. 문이 다시 열리려면 그보다 더.`,
  o:[
    { l:'① 매달린 고기 사이에 붙어 숨을 아낀다.', k:'steady', dc:21, wake:1,
      ok:`고기 사이로 들어가 등을 붙였다. 얼어도 고기는 바람을 막는다.<br><br>숨을 코로만 들이쉬었다. 길게. 입으로 내쉬지 않고 다시 코로. 입김이 안 생긴다. 입김은 몸에서 나가는 열이다.<br>손은 겨드랑이에, 턱은 깃 속에. 졸음이 오면 발가락을 하나씩 셌다.<br><br>한 시간이 지났다. 손톱 밑이 하얗지만 손가락은 다 움직인다. 숨 쉬는 법 하나로 열을 붙잡았다. 추위 속에서는 숨이 이불이다.`,
      ng:`붙었는데 고기가 생각보다 차다. 등의 열이 고기로 빨려 나간다.<br><br>숨을 아끼려다 오히려 가빠졌다. 입김이 하얗게 줄을 선다.<br>졸음이 왔다. 앉았다. 앉은 것을 몰랐다. 동료가 뺨을 때려서 깼다. 뺨이 아픈지도 몰랐다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 제자리에서 쉬지 않고 발을 구른다.', k:'break', dc:20,
      ok:`발을 굴렀다. 작게, 쉬지 않고. 무릎을 올렸다 내렸다. 땀이 나지 않을 만큼만.<br><br>땀이 나면 진다. 땀이 얼면 옷 속에 얼음을 입는다.<br>한 시간 동안 그 선을 지켰다. 다리가 뻐근하다. 대신 몸은 따뜻하다. 발을 구르는 소리는 냉각기 소리에 묻혔다.`,
      ng:`구르다가 너무 세게 했다. 등에 땀이 배었다.<br><br>멈추자 땀이 식는다. 식은 땀이 얼어 붙는다. 셔츠가 등에 판자처럼 붙었다.<br>남은 반 시간은 이가 맞부딪히는 소리로 셌다. 다 셌을 때 혀끝을 깨문 걸 알았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-12 } },
    { l:'③ 빈 상자를 깔고 그 안에 몸을 접어 넣는다.', k:'fix', dc:20,
      ok:`구석에 빈 생선 상자가 쌓였다. 바닥에 하나를 깔고, 하나를 등에 대고, 하나를 덮었다.<br><br>몸을 접어 넣었다. 언 바닥과 몸 사이에 판자 한 장. 그것만으로 열이 덜 샌다.<br>상자 틈으로 숨이 나간다. 상자 안은 생선 비린내와 이쪽 숨으로 조금 따뜻하다. 한 시간을 거기서 났다.`,
      ng:`상자를 깔았는데 바닥에 얼어붙은 상자였다. 떼는 소리가 크게 났다.<br><br>창고 안쪽에서 고기 사이를 헤치는 소리가 났다. 이쪽 말고 무언가가 같이 갇혀 있다.<br>상자를 덮고 숨을 죽였다. 소리가 상자 앞에서 멈췄다가 갔다. 한 시간이 두 시간 같았다.`,
      win:{ exp:15, dream:1, hp:6 }, lose:{ mind:-15, spirit:-14 } }
  ] },

{ at:'B2', t:'폐쇄 병동 — 약 봉투',
  x:`정각이다. 간호사가 수레를 밀고 들어온다. 약 봉투가 침대 번호대로 꽂혔다.<br><br>
    알약 셋. 흰 것, 노란 것, 반으로 쪼갠 것. 물 한 컵.<br>
    간호사가 기다린다. 삼키는 것을 봐야 다음 침대로 간다. 계수기를 쥔 엄지가 움직이지 않는다.<br><br>
    살아남는 사람은 모르는 것을 입에 넣지 않는다. 그런데 안 넣으면 여기서는 세어지지 않는다.`,
  o:[
    { l:'① 삼키는 척하고 혀 밑에 감춘다.', k:'hide', dc:21,
      ok:`알약을 입에 털어 넣고 물을 마셨다. 목울대를 크게 움직였다. 알약은 혀 밑에 있다.<br><br>간호사가 입을 벌려 보라고 했다. 벌렸다. 혀를 들라고는 안 했다.<br>딸깍. 다음 침대로 갔다. 알약을 손바닥에 뱉었다. 혀 밑이 쓰다. 반쯤 녹았다. 반은 이미 몸에 들어갔다. 반만큼 졸리다.`,
      ng:`털어 넣었는데 쪼갠 알약이 혀 밑으로 안 들어가고 목으로 미끄러졌다.<br><br>간호사가 입을 벌려 보라고 했다. 혀를 들라고 했다. 남은 둘이 보였다.<br>간호사가 새 물컵을 가져왔다. 다 넘길 때까지 서 있었다. 그 뒤 한 시간이 통째로 없다. 깨어 보니 손목에 띠가 감겨 있었다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-18, spirit:-14 } },
    { l:'② 삼키고 손톱으로 손바닥을 누르며 깨어 있는다.', k:'steady', dc:21,
      ok:`삼켰다. 셋 다. 간호사가 갔다.<br><br>곧 눈꺼풀이 무거워졌다. 손톱을 손바닥에 세웠다. 졸릴 때마다 눌렀다. 한 군데만 누르면 무뎌진다. 손톱 자리를 옮겨 가며 눌렀다.<br>한 시간 동안 열두 군데. 눈은 한 번도 감기지 않았다. 손바닥에 반달이 열두 개 떴다. 다음 정각 전에 약이 다 풀렸다.`,
      ng:`삼키고 눌렀는데 손이 먼저 잠들었다. 손톱이 손바닥에서 미끄러졌다.<br><br>천장이 기울었다. 형광등이 길게 늘어진다.<br>깨어 보니 정각이 두 번 지났다. 침대 발치 명패에 이름이 바뀌어 있다. 이쪽 이름이 아니다. 아까 부르던 이름도 아니다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-18 } }
  ] },

{ at:'B3', t:'바 카운터 — 단내 나는 잔',
  x:`바텐더가 잔 하나를 이쪽으로 민다. 따뜻한 물에 무언가 탔다. 단내가 난다.<br><br>
    젖고 언 몸에 따뜻한 것이 앞에 놓였다. 손이 먼저 간다. 몸이 원하는 것이다.<br>
    카운터 끝에 할머니가 보따리를 안고 앉았다. 젖은 머릿수건. 나물 냄새가 난다.<br><br>
    바텐더 뒤 거울에 할머니는 비친다. 바텐더는 안 비친다. 잔은 거울에 비친다.`,
  o:[
    { l:'① 한 모금만 머금고 혀로 맛을 읽는다.', k:'steady', dc:21,
      doom:{ title:'단내 나는 잔', what:'잠에 끌려 들어갑니다', dc:17, sec:55,
        text:`한 모금 머금었다. 삼키지 않았다. 혀 위에서 굴렸다.<br><br>달다. 꿀이다. 그 밑에 쓴 것. 아주 조금. 혀끝이 저리기 시작한다.<br>뱉으려는데 열차가 덜컹 했다. 반 모금이 넘어갔다.<br><br>카운터가 멀어진다. 바텐더가 잔을 닦는다. 천천히. 이쪽 고개가 카운터로 내려가는 박자에 맞춰.`,
        dieText:`따뜻한 것은 몸이 원하는 것이다. 이 열차는 그걸 안다.<br><br>카운터 끝 의자가 하나 비었다. 바텐더가 잔을 닦아 선반에 올렸다.<br>다음 역에서 승강장에 우산 쓴 사람이 하나 늘었다. 머리가 젖지 않았다.` },
      ok:`한 모금 머금고 혀 위에서 굴렸다. 꿀 맛 밑에 쓴 것이 있다. 혀끝이 저린다.<br><br>삼키지 않고 소매에 뱉었다. 잔을 바텐더 쪽으로 도로 밀었다.<br>바텐더가 웃었다. 웃는 얼굴이 거울에 안 비친다. 할머니가 이쪽을 보고 고개를 끄덕였다. 잘했다는 뜻이다. 보따리에서 나물 한 줌을 꺼내 줬다.`,
      win:{ exp:24, dream:3, item:'산나물' } },
    { l:'② 잔은 두고 할머니에게 나물을 청한다.', k:'bond', dc:20,
      ok:`잔에는 손을 대지 않았다. 할머니 옆에 앉아 보따리를 봤다. 산나물이다. 이 열차에서 처음 맡는 산 냄새다.<br><br>말린 고기 한 조각을 내밀었다. 할머니가 받고 나물 한 줌을 줬다. 날로 씹어도 된다고 했다. 쓴 것이 몸에 좋다고.<br>씹었다. 쓰다. 쓴 맛이 혀에 남아 있던 단내를 지웠다.`,
      ng:`청했는데 할머니가 보따리를 꼭 안았다. 고개를 젓는다.<br><br>바텐더가 잔을 이쪽으로 한 번 더 민다. 단내가 코를 찌른다. 손이 또 간다.<br>손을 거두려고 주먹을 쥐었다. 손톱이 손바닥에 박혔다. 잔이 다 식을 때까지 그 주먹을 풀지 못했다.`,
      win:{ exp:16, item:'산나물' }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'쫓기는 길 — 서두르지 않는 걸음',
  x:`뒤에서 따라오는 발소리가 서두르지 않는다. 한 시간째 같은 빠르기다.<br><br>
    일행은 뛰었다가 쉬었다가 다시 뛴다. 뛸 때 멀어지고 쉴 때 따라잡힌다.<br>
    쫓는 쪽은 안다. 쫓기는 쪽은 결국 지친다.<br><br>
    살아남는 사람은 다른 것을 안다. 지치지 않는 빠르기가 사람마다 하나씩 있다.`,
  o:[
    { l:'① 일행을 붙들고 같은 빠르기로 쉬지 않고 걷는다.', k:'steady', dc:21, wake:1,
      ok:`뛰지 말자고 했다. 쉬지도 말자고. 숨이 차지 않을 만큼 걷자고.<br><br>처음엔 다들 불안해했다. 발소리가 가까워지는 것 같다. 그런데 한 시간이 지나도 거리가 같다. 두 시간째에도.<br>쫓는 쪽은 서두르지 않는다. 이쪽도 이제 서두르지 않는다. 같은 빠르기면 영영 안 닿는다.<br><br>세 시간째 발소리가 멈췄다. 쫓는 쪽도 지치는 줄 처음 알았다. 이 걸음은 배운 것이 아니다. 오늘 몸이 찾아냈다. 다음부터는 처음부터 이 걸음으로 걷는다.`,
      ng:`같은 빠르기로 걷자고 했는데 일행 하나가 못 참고 뛰었다. 다들 따라 뛰었다.<br><br>혼자 걸을 수는 없다. 이쪽도 뛰었다. 숨이 찼다. 다리가 떨렸다.<br>쉴 때 따라잡혔다. 모퉁이 하나 차이로 겨우 빠졌다. 그 뒤로는 아무도 걷자는 말을 안 들었다. 다들 뛸 힘도 없었다.`,
      win:{ exp:22, dream:2, mind:6 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 한 번 크게 뛰어 거리를 벌린다.', k:'evade', dc:20,
      ok:`골목 셋을 쉬지 않고 뛰었다. 다들 따라왔다. 넷째 골목에서 담을 넘었다.<br><br>담 너머에서 숨을 죽였다. 발소리가 담 앞까지 와서 멈췄다. 한참.<br>그리고 왔던 쪽으로 돌아갔다. 담을 넘는 것은 쫓는 쪽 일이 아닌 모양이다. 다들 담 밑에서 숨을 몰아쉬었다. 다리가 오래 떨렸다.`,
      ng:`뛰었는데 둘째 골목에서 다리가 꼬였다. 무릎이 바닥을 찍었다.<br><br>일어나 다시 뛰었다. 무릎에서 피가 바지로 번진다.<br>거리는 벌어졌다가 금방 줄었다. 뛰는 쪽은 지치고 걷는 쪽은 안 지친다. 이쪽이 그걸 몰랐던 게 아니다. 알면서 뛰었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B1', t:'수로 — 밀물',
  x:`배수 수로에 물이 들어온다. 허리에서 가슴으로. 짜고 차다.<br><br>
    쇠창살이 수로를 막았다. 밑동이 녹슬어 물에 잠겼다. 창살 너머로 바닷바람이 들어온다.<br>
    물때표대로라면 네 시 반이면 천장까지 찬다. 천장과 물 사이에 숨 쉴 틈이 남을지는 모른다.<br><br>
    창살에 걸린 찢어진 그물 속에서 붕어 몇 마리가 퍼덕인다. 나갈 데가 없는 것은 저것들도 같다.`,
  o:[
    { l:'① 물이 차오르기를 기다렸다가 창살 위쪽 틈으로 빠진다.', k:'steady', dc:22,
      doom:{ title:'차오르는 수로', what:'물에 잠기고 있습니다', dc:18, sec:50,
        text:`창살 위쪽과 천장 사이에 틈이 있다. 머리 하나 너비. 지금은 손이 안 닿는다.<br><br>물이 차면 몸이 뜬다. 뜨면 닿는다. 기다렸다. 물이 가슴에서 목으로. 목에서 턱으로.<br>떴다. 손이 틈에 닿았다. 머리를 밀어 넣었다. 어깨가 걸린다.<br><br>물이 입까지 왔다. 어깨를 비틀어도 안 빠진다. 코로 마지막 숨을 들이켰다. 짜다.`,
        dieText:`살아남는 사람은 기다릴 줄 안다. 물도 기다릴 줄 안다.<br><br>네 시 반에 수로가 천장까지 찼다.<br>썰물 때 창살 위 틈에 외투 한 자락이 걸려 있었다. 그물 속 붕어들은 그 사이에 바다로 나갔다.` },
      ok:`물이 차기를 기다렸다. 턱까지 왔을 때 몸이 떴다. 창살 위쪽 틈에 손을 걸었다.<br><br>외투를 벗어 물에 버렸다. 젖은 외투는 한 사람 몫의 무게다. 어깨를 비스듬히 넣었다. 빠졌다.<br>저편에서 뒤따라오는 일행 손을 하나씩 잡아 끌었다. 마지막 사람이 넘어올 때 물이 천장에 닿았다. 숨은 다들 저편에서 쉬었다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 그물의 붕어를 챙기고 창살 밑동 녹을 판다.', k:'fix', dc:21,
      ok:`그물을 뜯어 붕어를 허리춤에 넣었다. 나갈 수 있으면 먹을 것이다.<br><br>창살 밑동을 더듬었다. 녹이 부풀어 떡처럼 무르다. 칼끝으로 후볐다. 한 대가 덜렁거린다. 둘째도.<br>두 대를 비틀어 뽑았다. 그 틈으로 잠수해 빠졌다. 물속에서 눈을 떴다. 짜서 눈이 따갑다. 빠진 뒤에도 한참 따가웠다.`,
      ng:`그물을 뜯다가 붕어가 다 빠져나갔다. 손에는 그물만.<br><br>밑동을 후비는데 칼이 녹에 박혀 부러졌다. 칼끝이 물 밑으로 사라졌다.<br>맨손으로 창살을 흔들었다. 손바닥이 녹에 찢겼다. 물은 목까지 왔다. 결국 위쪽 틈으로 빠졌다. 외투를 두고.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-28, mind:-12 } },
    { l:'③ 숨을 크게 모아 두고 잠수해 밑동 틈을 찾는다.', k:'sense', dc:21,
      ok:`숨을 세 번 크게 쉬고 네 번째에 가득 채웠다. 잠수했다.<br><br>밑동을 손으로 훑었다. 창살 하나가 바닥에서 떨어져 있다. 손 하나 들어갈 틈. 그 밑 진흙을 파냈다. 몸 하나 들어갈 틈.<br>올라와 숨을 쉬고 다시 내려가 빠졌다. 일행에게 위치를 알려 줬다. 손을 잡고 하나씩.`,
      ng:`잠수했는데 물이 흐리다. 아무것도 안 보인다. 손만 더듬었다.<br><br>손에 무언가 걸렸다. 창살이 아니다. 부드럽다. 천이다. 천 안에 무언가 들었다.<br>놓고 올라왔다. 숨이 터졌다. 다시 내려가지 못했다. 위쪽 틈으로 빠졌다. 손에 닿았던 것을 생각하지 않으려고 숨을 셌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-18 } }
  ] },

{ at:'B2', t:'세탁물 투입구 — 사람 투입 금지',
  x:`복도 끝 벽에 쇠 뚜껑. 세탁물 투입구다. 들면 아래로 통이 뚫렸다.<br><br>
    통에서 따뜻한 바람과 세제 냄새가 올라온다. 아래에서 기계가 돈다. 쿵, 쿵, 쿵.<br>
    뚜껑 안쪽에 종이가 붙어 있다. 사람 투입 금지. 금지라고 적은 데는 이유가 있다.<br><br>
    비상계단 쪽에서 딸깍 소리가 내려온다. 계단은 아까부터 같은 층만 돌았다.`,
  o:[
    { l:'① 시트로 몸을 감고 통으로 내려간다.', k:'steady', dc:21,
      doom:{ title:'세탁물 통', what:'통 아래로 떨어지고 있습니다', dc:17, sec:55,
        text:`복도 수레에서 시트를 두 장 꺼내 몸에 감았다. 머리까지. 그리고 통에 발부터 넣었다.<br><br>미끄러진다. 빨라진다. 통이 꺾이는 데서 어깨가 쇠벽에 부딪혔다. 시트가 받았다.<br>아래에서 쿵 소리가 가까워진다. 떨어지는 곳이 빨래 더미가 아니다. 돌고 있는 것 위다.<br><br>시트 한 장이 먼저 빨려 들어갔다. 다리가 따라간다. 따뜻하다. 너무 따뜻하다.`,
        dieText:`금지라고 적은 데는 이유가 있다.<br><br>3층 세탁실에서 드럼 하나가 한동안 다른 박자로 돌았다. 쿵, 쿵, 덜컥.<br>다음 날 다림질된 가운들 사이에 어깨가 둥근 가운이 한 벌 늘었다.` },
      ok:`시트 두 장으로 몸을 감고 발부터 넣었다. 미끄러졌다.<br><br>꺾이는 데마다 시트가 받았다. 아래에서 쿵 소리가 가까워진다. 소리가 바로 밑에 왔을 때 팔다리를 쫙 폈다. 통 벽에 몸이 걸려 멈췄다.<br>멈춘 데서 내려다봤다. 바로 밑이 돌고 있는 드럼 입구다. 옆에 점검 덮개가 있다. 발로 차 열고 그쪽으로 빠졌다. 세탁실 바닥이 젖어 있다. 따뜻하다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 통을 두고 비상계단 같은 칸을 표시하며 내려간다.', k:'sense', dc:20,
      ok:`계단으로 돌아갔다. 같은 층만 돈다. 4, 4, 4.<br><br>층마다 벽에 손톱으로 금을 하나씩 그었다. 다섯 번째 4층에서 금이 이미 넷 그어져 있었다. 계단이 원을 돈다. 원에는 끊긴 데가 있다.<br>금이 안 그어진 칸을 찾았다. 미끄럼 방지 고무가 하나만 새것인 칸. 거기를 밟자 벽 숫자가 3이 됐다.`,
      ng:`계단을 내려가며 금을 그었다. 그은 금이 다음 층에도 있다. 그다음에도.<br><br>금이 점점 늘어난다. 이쪽이 그은 것보다 많다. 다른 사람이 그은 금이 섞였다. 다섯 개씩 묶어서. 아주 많이.<br>계단에 주저앉았다. 딸깍 소리가 위에서 내려온다. 다시 일어나 걸었다. 숫자가 바뀐 건 한참 뒤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'2호차 — 얼음 칸',
  x:`화물칸 뒤쪽이 얼음 칸이다. 두꺼운 문이 열려 있다. 찬 김이 바닥을 기어 나온다.<br><br>
    앞 칸으로 가려면 이 안을 지나야 한다. 문 안쪽에 손잡이가 없다. 밖에서만 연다.<br>
    얼음 상자마다 생선이 들었다. 물안에서 실었다는 꼬리표. 하구 쪽 민물고기다.<br><br>
    들어가는 동안 누가 문을 닫으면, 반대편 문이 열려 있기를 바라야 한다.`,
  o:[
    { l:'① 문틈에 생선 상자를 끼워 두고 지난다.', k:'fix', dc:20,
      ok:`생선 상자 하나를 문과 문틀 사이에 끼웠다. 얼음이 든 상자라 무겁다. 문이 닫히려 해도 상자가 문다.<br><br>안으로 들어갔다. 숨이 하얗게 언다. 반대편 문까지 열두 걸음. 걷는 동안 생선 한 마리를 품에 넣었다.<br>반대편 문은 열려 있었다. 뒤에서 문이 상자를 무는 소리가 났다. 누군가 닫으려 했다.`,
      ng:`끼웠는데 열차가 휘며 상자가 미끄러져 나갔다. 문이 천천히 닫힌다.<br><br>뛰었다. 반대편 문까지 열두 걸음. 반대편 문도 닫혀 있다. 두드렸다.<br>한참 뒤에 열렸다. 연 사람은 화물칸 일꾼 차림이다. 얼굴을 안 들었다. 손가락 끝이 하얗게 얼었다. 귀도.`,
      win:{ exp:16, item:'민물고기' }, lose:{ hp:-24, mind:-14 } },
    { l:'② 숨을 고르고 천천히, 얼음 위를 밟지 않고 지난다.', k:'steady', dc:21,
      ok:`숨을 고르고 들어갔다. 바닥에 녹았다 언 얼음이 깔렸다. 상자 사이 판자 위만 밟았다.<br><br>뛰면 미끄러진다. 미끄러지면 상자에 머리를 찧는다. 찧으면 일어나기 전에 언다.<br>천천히 열두 걸음. 등 뒤에서 문이 닫혔다. 돌아보지 않았다. 반대편 문 손잡이를 잡았다. 열렸다. 천천히 간 사람만 손잡이를 잡을 수 있었다.`,
      ng:`판자를 밟는데 판자가 얼어 있다. 미끄러졌다. 상자 모서리에 옆구리를 찧었다.<br><br>일어나려는데 손이 얼음에 붙었다. 떼었다. 손바닥 살갗이 반쯤 남았다.<br>등 뒤에서 문이 닫혔다. 반대편 문까지 기어갔다. 다행히 열려 있었다. 그 뒤로 손바닥이 쥐는 걸 싫어했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'쉬는 자리 — 젖은 옷',
  x:`비 맞은 옷이 몸에 붙었다. 쉬려고 멈추자 그게 차가워진다.<br><br>
    젖은 옷은 사람의 열을 가져간다. 천천히, 다 가져간다. 비에 젖어 죽는 사람은 대개 쉬다가 죽는다.<br>
    일행이 벽에 기대 앉았다. 이가 맞부딪히는 소리가 난다.<br><br>
    바닥에 지난 신문 뭉치가 굴러다닌다. 젖지 않은 것도 몇 장 있다.`,
  o:[
    { l:'① 옷을 짜서 다시 입고 그 안에 신문을 받친다.', k:'fix', dc:20, wake:1,
      ok:`웃옷을 벗어 비틀어 짰다. 물이 바닥에 쏟아졌다. 다시 입기 전에 마른 신문을 가슴과 등에 한 장씩 댔다.<br><br>신문은 바람을 막고 물을 먹는다. 옷과 살 사이에 마른 것이 한 겹 생기면 열이 덜 샌다.<br>일행에게도 그렇게 하게 했다. 한 사람에 두 장씩. 이 맞부딪히는 소리가 하나씩 멎었다.<br><br>마른 것 한 장이 젖은 것 열 장을 이긴다. 그 한 장을 어디에 대야 하는지 손이 안다. 몸에서 열이 제일 먼저 새는 데부터.`,
      ng:`짜서 입었는데 신문이 다 젖은 것이었다. 마른 줄 알았는데 속이 젖었다.<br><br>젖은 신문이 살에 들러붙어 오히려 차다. 떼어 내는데 잉크가 살에 찍혀 글자가 거꾸로 남았다.<br>그대로 쉬었다. 쉬는 동안 이가 맞부딪혔다. 일어날 때 무릎이 펴지지 않았다.`,
      win:{ exp:22, dream:2, hp:8 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 다 같이 등을 맞대고 앉아 몸을 붙인다.', k:'bond', dc:20,
      ok:`둥글게 등을 맞대고 앉자고 했다. 바깥으로 등을, 안으로 무릎을.<br><br>젖은 등 위로 젖은 등. 그래도 붙으면 덜 춥다. 열이 사람 사이를 돈다.<br>한 사람씩 돌아가며 바깥 자리를 맡았다. 다 돌았을 때 다들 이가 멎었다. 잠깐이지만.`,
      ng:`등을 맞댔는데 한 사람이 자꾸 일어난다. 무서워서 등을 못 붙이겠다고 한다.<br><br>둥근 원에 틈이 생겼다. 틈으로 바람이 든다.<br>그 사람 자리를 이쪽이 메웠다. 등 두 쪽이 다 바깥이다. 쉬는 동안 등이 얼음판이 됐다.`,
      win:{ exp:15, mind:6 }, lose:{ hp:-20, spirit:-14 } },
    { l:'③ 쉬지 않고 제자리에서 몸을 움직인다.', k:'steady', dc:21,
      ok:`쉬지 않았다. 일어서서 팔을 휘두르고 무릎을 굽혔다 폈다. 작게.<br><br>앉은 사람들이 이쪽을 봤다. 하나씩 따라 일어섰다. 다들 작게 움직였다.<br>쉬는 자리에서 아무도 쉬지 않았다. 대신 아무도 얼지 않았다. 다시 걸을 때 다리가 먼저 나갔다.`,
      ng:`움직였는데 혼자만이다. 다들 앉아 있다. 같이 하자고 해도 고개만 젓는다.<br><br>혼자 움직이다 지쳤다. 지쳐서 앉았다. 앉으니 땀이 식는다.<br>젖은 옷이 땀까지 가져갔다. 다시 일어날 때 어지러웠다. 벽을 짚은 손이 미끄러졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B1', t:'경매장 — 생선 상자',
  x:`노란 비옷 셋이 장대로 얼음 더미를 찌른다. 한 뼘 간격으로. 빠짐없이.<br><br>
    노인이 이쪽 팔을 잡고 고개를 저었다. 얼음 속은 안 된다는 뜻이다.<br>
    경매대 옆에 생선 상자가 줄지어 놓였다. 갈치, 고등어, 장어. 상자마다 얼음과 생선이 반씩.<br><br>
    숨을 곳을 찾는 눈은 사람 크기의 빈틈을 찾는다. 찾는 쪽 눈도 그렇다.`,
  o:[
    { l:'① 빈 상자 줄에 몸을 접어 생선처럼 눕는다.', k:'steady', dc:21,
      ok:`빈 상자 셋을 붙이고 그 안에 몸을 접어 넣었다. 위에 생선 몇 마리와 얼음을 덮었다.<br><br>사람 크기의 빈틈이 아니다. 상자 셋 크기의 짐이다. 찾는 눈은 짐을 안 본다.<br>장대 끝이 얼음 더미를 찌르고 지나갔다. 상자 줄은 안 찔렀다. 일어났을 때 등이 생선 비린내로 젖었다. 냄새는 남았다. 사람은 남았다.`,
      ng:`접어 넣었는데 상자 하나가 모자라 발이 삐져나왔다.<br><br>얼음을 덮어 감췄다. 발끝이 시리다. 그 위로 장화가 지나가다 멈췄다. 장화 끝이 발을 툭 찼다.<br>참았다. 장화가 떠났다. 발가락 하나가 그 뒤로 감각이 없다. 생선과 같이 얼었다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 노인을 따라 흐린 수조 뒤로 돈다.', k:'sense', dc:20,
      ok:`노인이 가리키는 쪽으로 갔다. 흐린 수조 뒤. 벽과 수조 사이에 사람 하나 들어갈 틈이 있다.<br><br>노인은 이 항구에서 삼십 년을 짐을 졌다. 숨을 데를 아는 사람이다. 숨는 법도 안다. 숨을 쉬지 않는 게 아니라 수조 기포 소리에 맞춰 쉬는 것.<br>따라 했다. 장대가 수조 앞을 지나갔다. 기포 소리만 들렸다.`,
      ng:`따라갔는데 수조 뒤에 이미 누가 웅크리고 있다. 처음 보는 사람이다. 손가락을 입에 댄다.<br><br>둘이 들어갈 틈이 아니다. 셋은 더욱. 노인이 그 사람을 보고 얼굴이 굳었다.<br>되돌아 나왔다. 장대 끝이 이쪽 옆구리를 스쳤다. 찢긴 외투 사이로 얼음물이 들어왔다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B2', t:'휴게실 — 달력의 금',
  x:`휴게실 탁자에서 여자가 달력에 금을 긋는다. 다섯 개씩 묶어서. 금이 칸 밖으로 넘쳐 벽까지 갔다.<br><br>
    창가 노인은 약 봉투로 종이학을 접는다. 창틀에 스무 마리쯤 줄을 섰다.<br>
    여기 사람들은 밤 직원보다 오래 있었다. 오래 있는 데는 요령이 있다.<br><br>
    살아남는 사람은 다른 살아남은 사람을 알아본다. 눈 밑이 다르다.`,
  o:[
    { l:'① 여자 옆에 앉아 금 긋는 손을 지켜본다.', k:'gaze', dc:21, wake:1,
      ok:`옆에 앉았다. 여자가 볼펜을 내밀었다. 받았다.<br><br>여자는 금을 아무 때나 긋지 않는다. 정각마다 하나. 점검이 지나간 다음에. 세어진 다음에 자기가 다시 센다.<br>점검은 숫자를 센다. 여자는 시간을 센다. 숫자는 남이 세지만 시간은 자기가 센다. 그래서 여자는 아직 여자다.<br><br>손목에 볼펜으로 금 하나를 그었다. 이제 이쪽도 센다. 들어온 뒤로 몇 번 세어졌는지. 그 수를 잊지 않는 동안은 이쪽이 이쪽이다.`,
      ng:`옆에 앉았는데 여자가 금 긋던 손을 멈췄다. 이쪽 손목을 잡았다.<br><br>손목에 금을 긋는다. 하나, 둘, 셋, 넷. 다섯째에 가로로. 아프게.<br>뺄 수가 없다. 여자 손이 생각보다 세다. 열다섯 개를 긋고 놓아줬다. 손목에 이쪽이 여기 있은 날보다 많은 날이 적혔다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 노인에게서 종이학 하나를 받는다.', k:'bond', dc:20,
      ok:`노인 앞에 앉자 노인이 학 하나를 내밀었다. 받아서 폈다. 약 봉투다. 안에 약은 없다. 대신 설탕 덩이 같은 것이 하나.<br><br>꿀을 굳힌 것이다. 노인이 배식 때마다 조금씩 모았다고 했다. 단 것은 오래 버티게 한다고.<br>입에 넣었다. 단 맛이 머리 끝까지 갔다. 노인은 다시 학을 접는다.`,
      ng:`받아서 폈는데 안에 약이 들었다. 노인이 삼키지 않고 모은 약이다. 수십 알.<br><br>노인이 이쪽 손을 감싸 쥐며 말했다. 언젠가 다 같이 먹으면 된다고. 그러면 안 세어진다고.<br>손을 빼고 학을 돌려줬다. 노인은 웃으며 받았다. 그 웃음이 밤새 떠나지 않았다.`,
      win:{ exp:16, item:'꿀 한 줌' }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B3', t:'9호차 — 잠든 사람들의 선반',
  x:`객차 사람들이 다 잔다. 고개가 전부 창 쪽으로 기울었다. 외투가 젖었다.<br><br>
    선반 위 가방들이 이음매를 넘을 때마다 흔들린다. 가방 하나 지퍼가 반쯤 열렸다. 기름종이에 싼 것이 보인다.<br>
    배고프다. 언제 먹었는지 모르겠다. 이 열차에 탄 뒤로 시계는 한 시간쯤 갔다. 배는 하루가 갔다고 한다.<br><br>
    남의 것을 먹는 것도 살아남는 법이다. 들키지 않는다면.`,
  o:[
    { l:'① 지퍼 열린 가방에서 기름종이 꾸러미를 꺼낸다.', k:'luck', dc:21,
      ok:`선반에 손을 뻗었다. 가방 주인은 자는 숨이 고르다. 꾸러미를 꺼냈다.<br><br>펴 보니 말린 고기다. 짜고 질기다. 진짜다. 한 줄을 빼고 나머지는 도로 넣었다.<br>자리로 돌아와 씹었다. 가방 주인 숨소리가 그 사이 한 번 멎었다가 이어졌다. 깼다면 깬 척을 안 한 것이다.`,
      ng:`꺼내는데 가방 주인 손이 선반 위로 올라와 이쪽 손목을 잡았다. 자면서.<br><br>눈은 감았다. 손만 깨어 있다. 손가락이 하나씩 조여 온다.<br>꾸러미를 놓자 손도 놓았다. 손목에 손가락 자국이 남았다. 가방 주인 얼굴이 아까와 조금 다르다. 아까는 수염이 있었다.`,
      win:{ exp:16, item:'말린 고기' }, lose:{ hp:-20, spirit:-14 } },
    { l:'② 배고픔을 접어 두고 자리에서 버틴다.', k:'steady', dc:20,
      ok:`손을 거두고 자리에 앉았다. 배고픔은 물결 같다. 오고, 가장 높이 오르고, 빠진다.<br><br>가장 높을 때 숨을 길게 쉬었다. 빠질 때를 기다렸다. 세 번 오고 세 번 빠졌다.<br>네 번째는 오지 않았다. 배가 조용하다. 그 사이 선반 가방 주인이 깨어 가방을 끌어안고 다른 칸으로 갔다. 손을 댔으면 들켰을 것이다.`,
      ng:`버티는데 배가 너무 운다. 객차가 조용해서 소리가 크다.<br><br>자던 사람 몇이 고개를 들었다. 다 같은 쪽을 본다. 이쪽을.<br>고개들이 다시 창 쪽으로 기울 때까지 숨을 참았다. 배는 계속 울었다. 그 뒤로 내내 어지러웠다.`,
      win:{ exp:14, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] },

{ at:'B', t:'나눔 — 모르는 사람의 손',
  x:`골목 구석에 사람이 웅크려 있다. 젖었다. 떨고 있다. 손을 내민다.<br><br>
    가진 물은 반 병이다. 말린 고기 두 줄. 일행 몫까지 합쳐서.<br>
    이 밤에 만나는 사람은 셋 중 하나가 쫓는 쪽이 보낸 사람이다. 나머지 둘은 그냥 쫓기는 사람이다.<br><br>
    내민 손에 굳은살이 있다. 일하던 손이다. 손톱 밑이 깨끗하다.`,
  o:[
    { l:'① 물과 고기를 다 준다.', k:'bond', dc:20,
      ok:`반 병과 고기 두 줄을 다 쥐여 줬다. 그 사람이 울었다. 울면서 먹었다.<br><br>다 먹고 나서 골목 끝을 가리켰다. 저쪽으로 가면 비옷들이 없다고. 자기는 거기서 도망쳐 왔다고.<br>그쪽으로 갔다. 비옷이 없었다. 대신 배가 고팠다. 일행 몫까지 줬다. 아무도 탓하지 않았다. 다들 배를 쥐고 걸었다.`,
      ng:`다 줬다. 그 사람이 받아서 품에 넣고 일어섰다. 떨지 않는다.<br><br>골목 끝으로 걸어가며 휘파람을 불었다. 짧게 두 번.<br>골목 양 끝에서 손전등이 켜졌다. 뛰었다. 빈 주머니가 가볍다. 그래서 더 화가 났다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 아무것도 주지 않고 지나간다.', k:'steady', dc:20,
      ok:`지나갔다. 내민 손을 안 봤다. 살아남는 데에는 모진 데가 있다.<br><br>등 뒤에서 그 사람이 일어서는 소리가 났다. 떨던 사람이 일어서는 소리치고는 가볍다.<br>모퉁이에서 돌아봤다. 그 사람이 골목 반대편 손전등 쪽으로 걸어가고 있었다. 우산을 받아 쓰고.`,
      ng:`지나갔는데 그 사람이 따라온다. 떨면서. 손을 내민 채.<br><br>쫓아 보내도 따라온다. 발소리가 크다. 우는 소리도.<br>결국 손전등이 그 소리를 따라왔다. 그 사람을 떼어 놓느라 골목 둘을 더 돌았다. 마지막에 돌아봤을 때 그 사람은 손전등 빛 속에 서서 이쪽을 가리키고 있었다. 우는지 웃는지 모르겠다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-18 } },
    { l:'③ 물 한 모금만 따라 주고 얼굴을 본다.', k:'gaze', dc:21, wake:1,
      ok:`병뚜껑에 물을 한 번 따라 줬다. 한 모금이다. 그 사람이 마시는 동안 얼굴을 봤다.<br><br>목마른 사람은 한 모금을 아껴 마신다. 입안에서 굴린다. 이 사람은 한 번에 넘겼다. 그리고 병을 봤다. 병 속에 남은 양을.<br>뚜껑을 받아 들고 일어섰다. 그 사람은 따라오지 않았다. 대신 반대쪽으로 뛰어갔다. 알리러.<br><br>주는 법이 하나 늘었다. 한 모금만 주고 마시는 법을 본다. 목마른 사람과 목마른 척하는 사람은 한 모금에서 갈린다.`,
      ng:`한 모금을 따라 줬는데 그 사람이 뚜껑째 손을 잡았다. 놓지 않는다.<br><br>손이 차다. 젖어서가 아니다. 원래 차다. 얼굴을 볼 새가 없었다.<br>뿌리치는 사이 병이 떨어져 나머지 물이 쏟아졌다. 그 사람은 쏟아진 물을 보고 웃었다. 그리고 갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'선착장 — 경비 초소의 난로',
  x:`정문 옆 경비 초소 유리창에 김이 서렸다. 안에서 난로가 붉다.<br><br>
    경비원은 의자에서 졸고 있다. 고개가 가슴에 닿았다. 책상 위에 도시락 뚜껑이 열려 있다. 반쯤 먹었다.<br>
    밤새 젖은 몸이 난로 쪽으로 기운다. 저 불 앞 열 숨이면 손가락이 돌아올 것이다.<br><br>
    무전기가 지직거린다. 정문, 다섯 확인했나.`,
  o:[
    { l:'① 초소 뒷벽에 붙어 난로 연통 열만 쬔다.', k:'steady', dc:20,
      ok:`초소 안으로 들어가지 않았다. 뒷벽으로 돌아갔다. 연통이 벽을 뚫고 나와 있다. 뜨겁다.<br><br>연통 옆 벽에 손바닥과 등을 댔다. 벽돌이 데워졌다. 열 숨, 스무 숨. 손가락이 하나씩 돌아왔다.<br>안에서 경비원이 무전기에 대답하는 소리가 났다. 다섯 아직이라고. 그 소리를 벽 너머로 들으며 손을 녹였다.`,
      ng:`연통에 손을 댔는데 너무 뜨거웠다. 언 손이라 몰랐다.<br><br>손바닥에 물집이 섰다. 언 데와 덴 데가 한 손에 같이 있다.<br>소리를 삼켰다. 초소 안에서 의자가 끌리는 소리가 났다. 경비원이 깼다. 벽에서 떨어져 어둠으로 들어갔다. 손이 화끈거리며 얼었다.`,
      win:{ exp:16, dream:1, hp:8 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 졸고 있는 사이 도시락을 집어 온다.', k:'hide', dc:21,
      ok:`초소 문을 소리 없이 밀었다. 난로 열이 얼굴을 덮친다. 도시락을 들었다. 뚜껑을 닫았다.<br><br>경비원은 졸고 있다. 숨이 고르다. 무전기가 또 지직거린다. 경비원 손가락이 움찔했다.<br>나왔다. 도시락에는 밥 반과 짐승 고기 조림 몇 점. 아직 따뜻하다. 일행과 나눴다. 한 사람에 한 점.`,
      ng:`들었는데 도시락 밑에 젓가락이 끼어 있었다. 떨어졌다. 딱.<br><br>경비원이 고개를 들었다. 눈을 뜨지는 않았다. 고개만 이쪽으로 돌렸다.<br>그대로 서 있었다. 도시락을 든 채. 경비원이 다시 고개를 떨어뜨릴 때까지. 그 사이 다리가 떨려 쥐가 났다. 도시락은 두고 나왔다.`,
      win:{ exp:18, item:'짐승 고기' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'원무과 — 번호표',
  x:`대기실 의자마다 번호표가 한 장씩 놓였다. 일행이 들어서자 기계가 한 장씩 더 뱉었다.<br><br>
    전광판 숫자가 바뀐다. 띵동. 창구는 비었다. 그래도 숫자는 바뀐다.<br>
    이쪽 번호는 한참 뒤다. 번호가 불리면 퇴원 확인서 창구로 갈 수 있다. 불리기 전에 가면 세어지지 않은 사람이 된다.<br><br>
    기다리는 것도 일이다. 살아남는 일의 반은 기다리는 일이다.`,
  o:[
    { l:'① 번호표를 쥐고 불릴 때까지 꼼짝 않고 기다린다.', k:'steady', dc:21,
      ok:`의자에 앉아 번호표를 쥐었다. 일행에게도 앉으라고 했다. 아무도 일어서지 말라고.<br><br>띵동. 띵동. 숫자가 하나씩 올라간다. 빈 의자 번호표들이 불린다. 아무도 안 일어선다. 빈 번호는 그냥 지나간다.<br>오래 걸렸다. 다리가 저렸다. 이쪽 번호가 떴다. 일어섰다. 창구 유리 너머 직원이 처음으로 이쪽을 봤다. 기다린 사람을 보는 얼굴이다.`,
      ng:`기다리는데 숫자가 이쪽 번호 바로 앞에서 멈췄다. 한참.<br><br>전광판이 깜빡인다. 그 숫자가 계속 불린다. 띵동. 띵동. 앞 번호의 주인을 찾는다.<br>앞 번호표는 이쪽 옆 빈 의자 위에 있다. 아무도 안 일어선다. 결국 이쪽이 그 번호표를 들고 일어섰다. 다른 사람 번호로 불려 갔다.`,
      win:{ exp:18, dream:2, mind:6 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 빈 의자의 앞 번호표를 몰래 바꿔 쥔다.', k:'luck', dc:21,
      ok:`빈 의자에서 한참 앞 번호 한 장을 집어 이쪽 것과 바꿨다. 아무도 안 봤다. 볼 사람이 없다.<br><br>띵동. 그 번호가 금방 떴다. 일어섰다. 창구로 갔다.<br>직원이 번호표를 받아 들고 오래 봤다. 그리고 웃었다. 마스크 없는 입이 안 움직이며 웃는다. 확인서에 직인이 찍혔다. 이름 칸이 비어 있다.`,
      ng:`바꿔 쥐었는데 그 번호가 뜨자 대기실의 빈 의자들이 일제히 삐걱거렸다.<br><br>앉은 사람은 없다. 의자만 운다. 창구 직원이 이쪽을 본다.<br>번호표를 도로 갖다 놓으려는데 손바닥에 붙어 안 떨어진다. 물에 젖은 종이처럼. 다음 번호가 뜰 때까지 손을 털었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B3', t:'8호차 — 마른 신발 한 켤레',
  x:`침대칸 통로 바닥에 신발이 침대 수만큼 가지런하다. 다 젖었다.<br><br>
    이 열차 사람들은 다 비를 맞고 탔다. 우산 끝에서 물이 떨어졌고 외투에서 김이 났다.<br>
    한 켤레만 말랐다. 밑창까지. 비 오는 밤에 마른 신발로 탄 사람은 비를 안 맞고 탄 사람이다.<br><br>
    살아남는 사람은 젖은 것과 마른 것을 먼저 본다. 그 차이에서 사람이 죽고 산다.`,
  o:[
    { l:'① 마른 신발 앞 침대 커튼을 가만히 지켜본다.', k:'gaze', dc:21,
      ok:`마른 신발 앞 커튼을 봤다. 숨소리가 안 난다. 다른 커튼 너머는 다 숨을 쉰다.<br><br>그 칸은 비었다. 신발만 두고 주인은 다른 데 있다. 마른 발로.<br>일행에게 낮게 말했다. 맨발인 사람을 찾으라고. 통로 끝에서 양말만 신은 남자가 이쪽을 보고 돌아섰다. 발바닥이 말라 있었다.`,
      ng:`보는데 커튼이 안쪽에서 열렸다. 손가락 하나 너비.<br><br>그 틈에 눈이 있다. 이쪽 눈과 같은 높이. 깜빡이지 않는다.<br>먼저 눈을 돌린 쪽은 이쪽이었다. 다시 봤을 때 커튼은 닫혀 있고 신발이 없어졌다. 통로 어딘가에서 마른 발소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 마른 신발을 신어 젖은 발을 바꾼다.', k:'steady', dc:21,
      ok:`발이 젖어 불었다. 이대로 걸으면 발바닥이 벗겨진다. 마른 신발을 신었다. 꼭 맞는다.<br><br>너무 꼭 맞는다. 이쪽 발에 맞춰 지은 것처럼.<br>신발 끈을 다시 맸다. 발이 따뜻하다. 그 대신 통로 끝에서 맨발 하나가 이쪽을 계속 따라왔다. 자기 신발을 신은 사람을. 기관실까지 그랬다.`,
      ng:`신었는데 꼭 맞는다. 너무. 벗으려니 안 벗겨진다.<br><br>끈을 풀었다. 그래도 발이 안 빠진다. 신발 안이 따뜻하다. 발이 아니라 신발이 따뜻하다.<br>칼로 신발 옆구리를 갈라 겨우 뺐다. 발에 신발 안쪽 무늬가 찍혔다. 이쪽 발 모양 그대로 남은 신발을 두고 왔다.`,
      win:{ exp:16, dream:1, hp:6 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B', t:'시계 — 배로 재는 시간',
  x:`시계가 멈췄다. 비가 들어갔다. 바늘이 세 시 언저리에서 떨고 있다.<br><br>
    언제까지 나가야 하는지는 안다. 지금이 몇 시인지를 모른다.<br>
    배가 고프다. 목이 마르다. 손끝이 차다. 몸은 시계를 안 차고도 시간을 센다.<br><br>
    남은 먹을 것은 하나. 지금 먹으면 가는 내내 힘이 된다. 아끼면 마지막 계단에서 힘이 된다.`,
  o:[
    { l:'① 배고픔이 몇 번 왔다 갔는지로 시각을 짚는다.', k:'steady', dc:21,
      ok:`마지막으로 먹은 때를 떠올렸다. 그 뒤로 배고픔이 세 번 왔다. 한 번에 한 시간쯤. 목마름은 두 번.<br><br>들어온 게 자정이니 지금은 세 시 반 언저리다. 멈춘 시계와 반 시간이 다르다.<br>그 반 시간으로 길을 바꿨다. 돌아가는 길 대신 질러가는 길. 나중에 큰 시계를 봤다. 세 시 사십 분. 몸이 시계보다 맞았다.`,
      ng:`셌는데 배고픔이 몇 번 왔는지 헷갈린다. 넷인지 다섯인지.<br><br>무서워서 계속 배가 고팠다. 무서운 것도 배고픔으로 셌다.<br>시각을 한 시간 늦게 짚었다. 서두르지 않았다. 문에 닿았을 때 문이 닫히고 있었다. 마지막 사람 옷자락이 문에 물렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 남은 것을 지금 일행과 나눠 먹는다.', k:'bond', dc:20,
      ok:`마지막 고기를 꺼내 일행 수대로 찢었다. 손가락 한 마디씩.<br><br>작다. 그래도 씹는 동안 다들 말이 없었다. 씹는 것도 쉬는 것이다.<br>다 먹고 일어서자 걸음이 빨라졌다. 배가 아니라 마음이 찬 것이다. 문 앞에서는 아무것도 안 남았다. 문까지 아무도 쓰러지지 않았다.`,
      ng:`나누는데 한 사람이 자기 몫을 거절했다. 아끼겠다고.<br><br>그 사람 몫이 남았다. 남은 것을 두고 다들 눈치를 봤다.<br>결국 이쪽이 먹었다. 먹고 나서 후회했다. 그 사람이 끝에서 쓰러졌다. 남긴 것이 없었다.`,
      win:{ exp:15, hp:8 }, lose:{ hp:-20, mind:-14 } },
    { l:'③ 아껴 두고 물만 조금씩 마신다.', k:'fix', dc:20,
      ok:`고기는 품에 넣었다. 물을 병뚜껑으로 한 번씩만. 한 시간에 한 번.<br><br>힘이 떨어지는 게 느껴졌다. 그래도 걸었다. 끝이 보일 때 고기를 꺼내 물었다.<br>마지막 계단에서 다리에 힘이 돌았다. 아껴 둔 것은 끝에서 쓰라고 아낀 것이다. 정확히 끝에서 썼다.`,
      ng:`아꼈는데 아끼는 동안 다리가 먼저 갔다. 계단 중간에서 주저앉았다.<br><br>고기를 꺼내 씹었다. 힘이 돌아오기까지 한참 걸렸다. 그 한참 동안 일행이 기다렸다.<br>너무 오래 아꼈다. 끝은 생각보다 일찍 오고, 몸은 생각보다 일찍 간다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B', t:'다친 손 — 찢어진 손바닥',
  x:`손바닥이 찢어졌다. 녹슨 쇠에 걸렸다. 피가 손목으로 흘러 소매를 적신다.<br><br>
    약은 없다. 깨끗한 천도 없다. 있는 것은 젖은 소매와 빗물과 시간이 조금.<br>
    다친 손으로도 쥐어야 한다. 사다리를, 문고리를, 일행의 손을.<br><br>
    피는 금방 멎지 않는다. 쫓는 쪽은 피 냄새를 따라올 줄 안다.`,
  o:[
    { l:'① 빗물로 씻고 소매를 찢어 감으며 걷는다.', k:'heal', dc:20, wake:1,
      ok:`손을 빗물에 대고 씻었다. 걸으면서. 멈추지 않았다.<br><br>소매를 이로 찢어 손바닥에 감았다. 엄지와 검지 사이로 한 번 돌려 감아야 쥘 때 안 풀린다. 매듭은 손등에. 손바닥에 두면 쥘 때 박힌다.<br>감는 동안 스무 걸음을 걸었다. 다 감고 나서 사다리를 쥐었다. 쥐어진다.<br><br>멈춰서 치료하는 법은 누구나 안다. 걸으면서 감는 법은 오늘 손이 찾아냈다. 다치는 일과 걷는 일이 이제 같이 간다.`,
      ng:`씻고 감는데 손이 떨려 천이 자꾸 풀린다. 이로 물고 당기는 사이 피가 입에 들어왔다.<br><br>매듭을 손바닥 쪽에 지었다. 사다리를 쥐는 순간 매듭이 상처에 박혔다.<br>소리를 삼켰다. 사다리 칸마다 피 자국이 하나씩 남았다. 뒤따라오는 것이 칸을 셀 수 있게.`,
      win:{ exp:22, dream:2, hp:8 }, lose:{ hp:-22, spirit:-12 } },
    { l:'② 상처를 꽉 쥐고 그냥 버틴다.', k:'steady', dc:20,
      ok:`주먹을 꽉 쥐었다. 상처가 주먹 안에서 닫힌다. 피가 손톱 사이로만 조금 샌다.<br><br>쥔 채로 걸었다. 다른 손으로 다 했다. 문을 열고 일행을 끌었다.<br>한 시간 뒤 주먹을 폈다. 피가 멎었다. 손가락이 쥔 모양으로 굳어 펴는 데 한참 걸렸다.`,
      ng:`쥐었는데 쥔 손이 자꾸 풀린다. 힘이 빠진다. 피가 빠져서다.<br><br>어지럽다. 걸음이 비틀린다. 벽에 피 묻은 손자국이 줄을 선다.<br>일행 하나가 허리띠로 팔을 묶어 줬다. 늦었다. 손이 차다. 손가락 끝이 하얗다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'숨는 자리 — 나무 상자',
  x:`손전등 줄이 사방에서 좁혀 온다. 숨을 데가 하나 남았다.<br><br>
    짐 더미 사이에 나무 상자가 있다. 뚜껑이 반쯤 열렸다. 사람 하나가 접혀 들어갈 크기다. 안에 짚이 깔렸다.<br>
    살아남는 사람은 숨는 데 익다. 오래, 작게, 움직이지 않고.<br><br>
    상자 옆구리에 분필로 무언가 적혀 있다. 빗물에 반쯤 지워졌다. 『05:10 적재.』`,
  o:[
    { l:'① 상자 안에 몸을 접어 넣고 뚜껑을 덮는다.', k:'steady', dc:21,
      doom:{ title:'적재된 상자', what:'상자째 실려 갑니다', dc:17, sec:50,
        text:`상자에 들어가 몸을 접었다. 무릎이 턱에 닿는다. 뚜껑을 덮었다. 짚 냄새.<br><br>손전등이 지나갔다. 한 번, 두 번. 숨을 줄여 아주 작게 쉬었다. 오래 버텼다. 버티는 것은 이쪽 일이다.<br>그러다 상자가 들렸다.<br><br>흔들린다. 누가 상자를 메고 걷는다. 경사를 오른다. 쇠판을 밟는 소리. 뱃전이다. 뚜껑 위로 못 박는 소리가 난다. 하나, 둘.`,
        dieText:`오래, 작게, 움직이지 않고. 숨는 데 익은 사람은 그렇게 숨는다.<br><br>그날 상자 하나가 제시간에 적재됐다.<br>다섯 시 십 분, 배가 고동을 두 번 울리고 떠났다. 짐 목록에 다섯이 다 찼다는 표시가 붙었다.` },
      ok:`들어가 뚜껑을 덮었다. 손전등이 지나갔다. 숨을 아주 작게.<br><br>그러다 상자가 들렸다. 흔들린다. 들려 가는 중이다. 뚜껑을 머리로 밀었다. 위에 아무것도 없다. 아직 못이 안 박혔다.<br>뚜껑을 밀치고 굴러 떨어졌다. 상자를 메던 비옷이 넘어졌다. 빈 상자만 비옷 위로 쏟아졌다. 숨는 데 익은 사람은 나오는 때도 안다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 상자 말고 짐 더미 위 방수포 밑에 납작 엎드린다.', k:'hide', dc:21,
      ok:`상자는 사람 크기다. 찾는 눈이 사람 크기를 본다. 상자를 두고 짐 더미 꼭대기로 올라갔다.<br><br>방수포를 들고 그 밑에 엎드렸다. 납작하게. 빗물이 방수포 위에 고인다. 고인 물이 이쪽 모양을 지운다.<br>손전등이 상자를 비췄다. 뚜껑을 열었다. 비었다. 다른 데로 갔다. 방수포 위 물웅덩이가 이쪽 등을 눌렀다.`,
      ng:`엎드렸는데 방수포가 짧다. 발이 나왔다.<br><br>손전등이 발을 비추고 멈췄다. 비옷 하나가 장대로 방수포를 쿡 찔렀다. 허벅지에 들어갔다.<br>소리를 안 냈다. 장대가 빠졌다. 비옷이 고개를 갸웃하며 갔다. 허벅지에서 피가 방수포 밑으로 번진다. 따뜻하다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B', t:'새벽 전 — 말 안 듣는 다리',
  x:`밤이 끝나 간다. 하늘 끝은 아직 검다. 다리가 먼저 끝났다.<br><br>
    무릎이 떨린다. 발을 내디디면 발목이 꺾인다. 일행도 다 그렇다.<br>
    쉬면 못 일어난다. 걸으면 넘어진다.<br><br>
    살아남는 일의 마지막은 늘 이렇다. 남은 것이 없을 때 남은 것으로 간다.`,
  o:[
    { l:'① 다음 기둥까지만, 그다음 기둥까지만 간다.', k:'steady', dc:21, wake:1,
      ok:`문까지 가자고 하지 않았다. 다음 기둥까지만 가자고 했다. 열 걸음.<br><br>열 걸음은 간다. 닿으면 기둥을 짚고 숨을 한 번. 다음 기둥까지 또 열 걸음. 문까지 몇 걸음인지는 아무도 안 셌다.<br>기둥 스물두 개째에 문이 있었다.<br><br>먼 데는 못 간다. 가까운 데는 간다. 가까운 데를 이어 붙이면 먼 데가 된다. 몸이 다 떨어진 뒤에 쓰는 셈법을 하나 얻었다.`,
      ng:`다음 기둥까지 가자고 했는데 기둥이 생각보다 멀다. 열 걸음이 아니라 스무 걸음.<br><br>중간에 한 사람이 주저앉았다. 일으켰다. 이쪽도 주저앉았다.<br>둘이 서로 끌며 기둥에 닿았다. 그다음 기둥은 보이지 않았다. 한참 앉아 있다가 기어서 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 둘씩 어깨를 걸고 서로를 기둥 삼는다.', k:'bond', dc:20,
      ok:`둘씩 짝을 지었다. 어깨를 걸었다. 하나가 무릎이 꺾이면 다른 하나가 받친다.<br><br>둘이 동시에 꺾이지만 않으면 된다. 박자를 엇갈리게 걸었다. 왼발, 오른발.<br>느리다. 그래도 넘어지지 않는다. 사람 둘이 다리 셋으로 걷는 것 같다. 문까지 그렇게 갔다.`,
      ng:`어깨를 걸었는데 짝이 이쪽보다 무겁다. 이쪽이 받치는 일이 더 많다.<br><br>무릎이 먼저 갔다. 둘이 같이 넘어졌다. 바닥에 턱을 찧었다.<br>일어나 다시 걸었다. 다시 넘어졌다. 세 번째에 짝이 이쪽을 업겠다고 했다. 거절할 힘이 없었다.`,
      win:{ exp:16, mind:6 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 주머니 속 마지막 단 것을 혀에 올린다.', k:'luck', dc:20,
      ok:`주머니 맨 밑을 뒤졌다. 기름종이에 싼 꿀 덩이가 하나 있다. 언제 넣었는지 모른다.<br><br>쪼개서 일행 혀에 하나씩 올려 줬다. 녹는다. 단 것이 피에 돈다. 다리가 잠깐 돌아왔다.<br>잠깐이면 된다. 그 잠깐에 문까지 갔다. 주머니 밑에는 늘 무언가 하나 남겨 두는 버릇이 있다.`,
      ng:`뒤졌는데 꿀 덩이가 녹아 주머니 안감에 다 배었다.<br><br>안감을 뜯어 씹었다. 단맛보다 실 맛이 났다.<br>다리는 돌아오지 않았다. 일행이 이쪽을 끌었다. 끌려가며 안감 실을 계속 씹었다.`,
      win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-20, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 결계술사 · 마력
// ------------------------------------------
kJob('warder', 'B', [

{ at:'B', t:'빗속 — 흘러가는 금',
  x:`바닥에 그은 금이 빗물에 번진다. 번진 금은 금이 아니다.<br><br>
    이 밤은 비가 그치지 않는다. 바닥은 다 흐른다. 흐르는 것은 나누지 못한다.<br>
    금을 긋는 사람은 그래도 긋는다. 긋지 않으면 안과 밖이 없다.<br><br>
    골목 저편에서 장화 소리가 물웅덩이를 하나씩 밟고 온다.`,
  o:[
    { l:'① 마력을 써서 빗물이 흐르는 쪽으로 금을 긋는다.', k:'steady', dc:21, cost:{ mana:22 }, wake:1,
      ok:`물을 가로질러 긋지 않았다. 물이 흐르는 쪽을 따라 길게 그었다. 물줄기 하나하나를 금의 한 획으로 삼았다.<br><br>빗물이 금을 지우지 않는다. 금을 따라 흐른다. 흐르는 물이 금을 덧그어 준다.<br>장화 소리가 금 앞에서 멈췄다. 웅덩이 하나를 못 건너고 한참 서 있다가 돌아갔다.<br><br>물에 맞서 그은 금은 지워진다. 물을 따라 그은 금은 물이 지킨다. 손끝이 물 흐르는 쪽을 먼저 찾는다. 이제 비는 지우개가 아니다.`,
      ng:`따라 긋는데 물줄기가 갈라졌다. 금도 갈라졌다. 반은 이쪽으로, 반은 하수구로.<br><br>마력이 하수구로 빨려 내려간다. 손끝이 저리다. 멈추지 못했다.<br>장화 소리가 갈라진 틈으로 들어왔다. 코앞까지. 몸을 던져 벽 뒤로 굴렀다. 손끝이 한참 하얬다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-14, mana:-6 } },
    { l:'② 처마 밑 마른 바닥을 찾아 금을 긋는다.', k:'sense', dc:20,
      ok:`처마가 깊은 데를 찾았다. 셔터 내린 가게 앞. 바닥이 손바닥 넓이만큼 말랐다.<br><br>그 마른 데에만 작게 그었다. 일행이 웅크려 들어앉았다. 장화 소리가 지나간다. 처마 밑을 들여다보지 않는다.<br>금은 작을수록 단단하다. 처마가 반을 해 줬다.`,
      ng:`찾았는데 그 처마 밑에 이미 누가 있다. 담배 끝이 붉다.<br><br>얼굴은 어둠 속이다. 그 사람이 담배를 바닥에 비벼 끈다. 그 자리에 둥근 자국이 생겼다. 금처럼.<br>뒷걸음질로 나왔다. 빗속으로. 처마 밑 사람은 따라오지 않았다. 대신 뒤에서 휘파람이 한 번 울렸다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B1', t:'3번 창고 — 닦인 바닥의 테두리',
  x:`벽을 보고 앉은 사람의 의자 둘레만 바닥이 깨끗하다. 먼지도 기름 자국도 없다.<br><br>
    표백제 냄새가 코를 찌른다. 깨끗한 데와 더러운 데 사이에 선이 있다. 대걸레가 멈춘 자리다.<br>
    금을 긋는 사람은 남이 그은 선을 먼저 본다. 이건 마력으로 그은 것이 아니다. 그래도 선이다.<br><br>
    그 선 안에 들어가는 것은 닦인다.`,
  o:[
    { l:'① 닦인 자리의 테두리를 읽는다.', k:'gaze', dc:21, wake:1,
      ok:`테두리를 따라 걸었다. 안으로는 한 발도 안 들였다.<br><br>둥글지 않다. 의자를 중심으로 한 바퀴, 쪽문 쪽으로 한 줄. 쪽문 앞에서 끝이 열려 있다. 닦는 사람이 나간 길이다. 다시 들어올 길이다.<br>대걸레 자국은 금과 같다. 안과 밖을 나누고, 문을 하나 남긴다.<br><br>나누는 것은 다 금이다. 마력이든, 대걸레든, 분필이든, 피든. 그걸 알고 나니 이 창고 바닥이 금투성이로 보인다. 누가 어디를 나눠 놨는지 다 보인다.`,
      ng:`읽는데 테두리가 한 군데 젖어 있다. 방금 닦은 자리다. 지금도 젖어 있다.<br><br>그 자리를 밟았다. 미끄러졌다. 몸이 선 안으로 넘어졌다.<br>표백제가 손바닥을 태운다. 일어나 나왔다. 손바닥 살갗이 하얗게 일었다. 의자에 앉은 사람의 고개가 조금 이쪽으로 기울어 있었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 테두리를 밟지 않고 크게 돌아간다.', k:'steady', dc:20,
      ok:`테두리에서 두 걸음 떨어져 크게 돌았다. 일행에게도 그렇게 하라고 했다. 아무도 묻지 않았다.<br><br>쪽문까지 갔다. 돌아보니 의자 둘레 깨끗한 자리가 아까보다 한 뼘 넓다. 그 사이에 넓어졌다.<br>닦인 자리는 넓어진다. 밤이 갈수록.`,
      ng:`돌았는데 일행 하나가 테두리를 밟았다. 신발 끝만.<br><br>그 사람 신발 끝이 하얗게 탈색됐다. 그 사람이 신발을 봤다. 그리고 의자를 봤다.<br>의자에 앉은 사람의 고무장갑 낀 손이 무릎 위에서 손가락 하나를 폈다. 하나. 세는 것이다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-15, spirit:-15 } },
    { l:'③ 마력을 써서 테두리 바깥에 금을 하나 더 두른다.', k:'fix', dc:21, cost:{ mana:20 },
      ok:`닦인 자리 바깥에 마력으로 금을 둘렀다. 쪽문 쪽 열린 데까지 막았다.<br><br>금 두 겹이다. 안은 닦는 사람의 것, 밖은 이쪽 것. 닦는 사람이 돌아와도 자기 자리에 못 들어간다.<br>쪽문 밖에서 장화 소리가 멈췄다. 한참. 그리고 다른 문으로 돌아가는 소리가 났다.`,
      ng:`두르는데 마력이 닦인 바닥에 닿자 거품이 일었다. 표백제가 금을 먹는다.<br><br>금이 녹아 사라졌다. 마력만 빠졌다.<br>의자에 앉은 사람이 처음으로 몸을 움직였다. 고개를 숙여 바닥의 거품 자국을 본다. 그리고 주머니에서 수첩을 꺼냈다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16, mana:-5 } }
  ] },

{ at:'B2', t:'폐쇄 병동 — 문턱의 금',
  x:`정각이 다가온다. 복도에서 딸깍 소리가 한 칸씩 가까워진다.<br><br>
    간호사는 병실 문 앞에 서서 센다. 들어오지 않고. 침대 위를 한 번 훑고 계수기를 누른다.<br>
    일행 중 하나가 침대에 없다. 다쳐서 바닥에 누웠다. 침대 하나가 빈다.<br><br>
    숫자가 맞지 않으면 맞을 때까지 센다. 맞을 때까지는 들어와서 센다.`,
  o:[
    { l:'① 마력을 써서 병실 문턱에 금을 긋는다.', k:'steady', dc:21, cost:{ mana:24 },
      ok:`문턱을 따라 금을 한 줄 그었다. 둥글게 두를 시간이 없다. 한 줄이면 문 하나를 막는다.<br><br>간호사가 문 앞에 섰다. 계수기를 들고 침대를 훑는다. 빈 침대에서 눈이 멎는다. 한 발이 문턱으로 온다.<br>멈췄다. 발끝이 금 위에서 떨린다. 들어오지 못한다. 간호사가 한참 서 있다가 계수기를 눌렀다. 문 밖에서 센 숫자로.<br><br>딸깍. 다음 방으로 갔다. 문턱의 금이 아직 따뜻하다.`,
      ng:`그었는데 간호사가 문턱을 보지 않았다. 침대만 본다.<br><br>빈 침대에서 눈이 멎었다. 발이 문턱에 닿았다. 금이 깨지는 소리가 이쪽 머릿속에서 났다.<br>간호사가 들어와 바닥의 동료를 내려다봤다. 계수기를 눌렀다. 그리고 보호사를 불렀다. 동료를 침대에 묶어 눕히는 동안 머릿속 깨진 소리가 계속 울렸다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-14, mana:-5 } },
    { l:'② 빈 침대에 베개를 넣어 사람 모양을 만든다.', k:'hide', dc:20,
      ok:`빈 침대 이불 밑에 베개 둘과 외투를 넣었다. 머리 쪽은 둥글게, 다리 쪽은 길게.<br><br>간호사가 문 앞에서 훑었다. 침대마다 사람 모양이 있다. 딸깍. 숫자가 맞았다.<br>간호사가 지나간 뒤 이불을 들춰 봤다. 베개 위에 머리카락이 한 올 있다. 이쪽 것이 아니다.`,
      ng:`넣었는데 다리 쪽이 너무 짧다. 아이 모양이 됐다.<br><br>간호사가 그 침대에서 오래 멈췄다. 고개를 갸웃했다. 들어왔다. 이불을 들췄다.<br>베개를 보고 계수기를 눌렀다. 하나 뺐다. 빠진 숫자를 채우러 간호사가 복도 끝으로 갔다. 무엇으로 채울지는 묻지 않았다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B3', t:'9호차 — 두드리는 끝 문',
  x:`객차 맨 뒤 문이다. 문 너머는 선로뿐이다. 빨간 꼬리등이 젖은 침목을 비춘다.<br><br>
    누가 두드린다. 밖에서. 똑, 똑, 똑.<br>
    이 열차 뒤에는 칸이 없다. 그런데 두드린다. 두드리는 것은 들어오고 싶은 것이다.<br><br>
    문손잡이가 천천히 돈다. 안쪽에서 아무도 안 잡았는데.`,
  o:[
    { l:'① 문짝과 문틀 사이에 금을 긋고 손바닥으로 누른다.', k:'steady', dc:22,
      doom:{ title:'끝 문', what:'끝 문 밖으로 끌려 나갑니다', dc:18, sec:45,
        text:`문틈을 따라 손끝으로 금을 그었다. 위에서 아래로. 손바닥을 금 위에 대고 눌렀다.<br><br>손잡이가 멈췄다. 두드림도. 조용하다.<br>그리고 문이 안쪽으로 밀렸다. 한 번에. 금을 누르던 손바닥이 문짝에 붙었다. 떨어지지 않는다. 금이 이쪽 손을 문에 묶었다.<br><br>문이 열린다. 바깥으로. 바람이 객차 안의 것을 다 빨아낸다. 손바닥이 문을 따라 나간다. 팔이, 어깨가.`,
        dieText:`두드리는 것은 들어오고 싶은 것이다. 들어오지 못하면 데려간다.<br><br>9호차 끝 문이 다시 닫혔다. 안에서 아무도 안 닫았는데.<br>문 유리창 김 위에 손바닥 자국 하나가 바깥쪽에서 찍혀 있다. 다음 역 불빛이 지나갈 때 잠깐 보였다.` },
      ok:`문틈을 따라 금을 긋고 손바닥으로 눌렀다. 손잡이가 멈췄다.<br><br>문이 밀려 온다. 손바닥이 붙으려 한다. 손을 떼고 금 끝만 손톱으로 눌렀다. 손 전체를 맡기지 않았다.<br>문이 덜컹 하고 제자리로 돌아갔다. 두드림이 멀어진다. 선로를 따라 뒤로. 꼬리등 빛 밖으로.<br><br>문틈의 금은 아침까지 빛났다. 그 뒤로 9호차 끝 문은 아무도 두드리지 않았다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 문 유리창의 김을 닦아 밖을 본다.', k:'gaze', dc:21,
      ok:`김을 소매로 닦았다. 손바닥만 하게.<br><br>밖에는 아무도 없다. 선로와 비. 그런데 유리창 바깥쪽에 손가락 자국이 남아 있다. 두드리던 자리다. 손가락이 넷이다. 엄지 자리가 없다.<br>그 자국 둘레에 손끝으로 작은 금을 그어 가뒀다. 두드림이 멈췄다. 손잡이도.`,
      ng:`닦았는데 유리창 바로 너머에 얼굴이 있다. 코가 유리에 닿을 만큼 가까이.<br><br>이쪽 얼굴이다. 비에 젖었다. 웃고 있다. 이쪽은 안 웃는데.<br>뒷걸음질 쳤다. 좌석에 걸려 넘어졌다. 다시 봤을 때 유리창에 김이 서려 있었다. 바깥에서 입김을 분 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-20 } }
  ] },

{ at:'B', t:'쫓기는 길 — 따라오는 금',
  x:`금은 한자리에 긋는다. 긋고 나면 그 자리를 지킨다. 그 자리를 떠나면 금은 남고 사람은 간다.<br><br>
    오늘 밤은 한자리에 머물 수가 없다. 쫓기는 밤이다.<br>
    쉴 때마다 금을 긋고, 떠날 때마다 버린다. 마력이 한 줄씩 빗속에 남는다.<br><br>
    뒤의 것들이 그 버린 금을 하나씩 밟고 온다. 밟을 때마다 금 꺼지는 소리가 이쪽 귀에 들린다.`,
  o:[
    { l:'① 마력을 써서 일행 발뒤꿈치를 잇는 금을 긋는다.', k:'steady', dc:22, cost:{ mana:25 }, wake:1,
      ok:`바닥에 긋지 않았다. 맨 앞사람 발뒤꿈치에서 맨 뒷사람 발뒤꿈치까지, 일행을 한 줄로 이었다. 둥글게 감았다.<br><br>일행이 걸으면 금도 걷는다. 다섯 사람이 금의 기둥이다. 기둥이 움직이면 금이 따라 휜다.<br>뒤에서 오던 손 하나가 맨 뒷사람 어깨에 닿으려다 튕겨 나갔다. 걷는 중에.<br><br>금은 땅에 긋는 것이라고 배웠다. 사람에게 걸면 사람과 같이 간다. 손끝이 그 감는 법을 기억한다. 머물 데가 없는 밤에도 안과 밖이 생긴다.`,
      ng:`잇는데 일행 하나가 걸음이 늦어 금이 늘어났다. 늘어난 금은 얇다.<br><br>얇은 데가 끊어졌다. 툭. 이쪽 손목에서 무언가 끊기는 느낌.<br>끊긴 틈으로 뒤의 것이 들어와 늦은 사람의 발목을 잡았다. 끌어당겨 겨우 뺐다. 손목이 끊긴 금 자리처럼 한동안 저렸다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14, mana:-6 } },
    { l:'② 모퉁이를 돌 때마다 짧은 금을 하나씩 남긴다.', k:'fix', dc:21,
      ok:`둥글게 긋지 않았다. 모퉁이마다 벽에서 벽으로 한 획씩. 손가락 길이만큼 짧게.<br><br>짧은 금은 막지 못한다. 대신 걸린다. 뒤의 것이 금을 밟을 때마다 머뭇거린다. 숨 한 번만큼.<br>모퉁이가 열둘이다. 숨 열두 번을 벌었다. 그만큼 앞섰다.`,
      ng:`남기는데 뒤의 것이 금을 밟지 않는다. 넘는다. 한 번 보고 넘는다.<br><br>금을 아는 것이다. 버린 금이 뒤의 것에게 이쪽 길을 알려 줬다. 모퉁이마다 표시를 남긴 셈이다.<br>모퉁이 셋째에서 따라잡혔다. 손이 어깨를 스쳤다. 어깨에 찬 손가락 자국이 남았다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 성에 위의 금',
  x:`냉동 창고 안이다. 문이 닫혔다. 온도계가 영하 이십 도.<br><br>
    입김이 하얗다. 손끝에 마력을 모으려는데 손끝이 굳는다. 추위는 마력도 굳힌다.<br>
    문 안쪽에 성에가 두껍게 꼈다. 하얗고 고르다. 손가락이 닿으면 자국이 난다.<br><br>
    한 시간이다. 한 시간을 이 안에서 지켜야 한다.`,
  o:[
    { l:'① 성에에 손가락으로 금을 긋는다.', k:'steady', dc:21,
      ok:`문 안쪽 성에에 손가락을 대고 둥글게 그었다. 마력은 거의 안 묻혔다. 성에가 손자국을 그대로 붙잡는다.<br><br>성에 위의 금은 녹지 않는다. 이 안에서는. 금 안쪽에 일행을 모았다.<br>매달린 고기 사이에서 무언가 움직이다가 금 앞에서 멈췄다. 성에가 뽀득 소리를 냈다. 다시 고기 사이로 들어갔다.`,
      ng:`그었는데 손가락 끝이 성에에 붙었다. 떼는 순간 살갗이 성에에 남았다.<br><br>금 한 귀퉁이에 이쪽 피가 묻었다. 피가 금을 따라 번진다. 얼면서.<br>피 묻은 금은 무겁다. 마력이 쑥 빠져나갔다. 손가락에서 시작해 팔꿈치까지 저렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } },
    { l:'② 마력을 써서 숨의 열을 가두는 금을 친다.', k:'fix', dc:21, cost:{ mana:22 },
      ok:`일행을 바싹 모으고 그 둘레에 금을 쳤다. 바닥에 둥글게, 머리 위에 한 겹.<br><br>소리를 가두는 금이 있다. 열이라고 못 가둘 이유는 없다. 다섯 사람 숨이 금 안에서 돈다. 입김이 금 밖으로 안 나간다.<br>한 시간이 지났다. 금 안이 조금 따뜻하다. 금 밖 고기에는 성에가 피었다.`,
      ng:`쳤는데 열보다 냉기가 먼저 갇혔다. 금 안이 금 밖보다 차다.<br><br>입김이 금 안에서 얼어 눈처럼 떨어진다. 다들 이가 부딪힌다.<br>금을 풀었다. 풀리는 순간 몸에서 마력이 같이 빠졌다. 반 시간을 덜덜 떨며 났다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-12, mana:-5 } },
    { l:'③ 고기 갈고리에 걸린 짐승을 하나 끊어 온다.', k:'luck', dc:20,
      ok:`매달린 고기 줄에서 제일 작은 것을 골라 갈고리에서 뺐다. 짐승 다리 하나다. 얼었다.<br><br>얼어도 고기다. 나가면 녹여 먹으면 된다.<br>고기를 빼낸 갈고리가 레일을 따라 한 칸 움직였다. 빈 갈고리가 다음 칸으로. 그 칸에 걸 것을 찾으러.`,
      ng:`빼내는데 갈고리가 안 놓는다. 고기가 갈고리에 얼어붙었다.<br><br>세게 당겼다. 레일 전체가 울렸다. 끼익.<br>창고 안쪽 어둠에서 사슬 당기는 소리가 멎었다. 그리고 다시 시작됐다. 이번엔 이쪽으로. 빈손으로 금 안에 들어가 숨을 죽였다.`,
      win:{ exp:15, item:'짐승 고기' }, lose:{ hp:-20, spirit:-14 } }
  ] },

{ at:'B2', t:'세단실 — 표지 사진',
  x:`세단기가 서류철을 통째로 문다. 직원 하나가 기록철을 한 권씩 넣는다. 넣을 때마다 계수기를 누른다.<br><br>
    다음 철 표지에 사진이 붙어 있다. 7층 휴게실에서 달력에 금을 긋던 여자다.<br>
    철이 세단기에 들어가면 그 사람은 장부에서 빠진다. 빠진 사람은 찾으러 온다. 찾지 못하면 아무나 데려간다.<br><br>
    직원이 그 철을 집어 든다. 표지를 입술로만 읽는다.`,
  o:[
    { l:'① 세단기 입에 금을 걸어 철을 막는다.', k:'steady', dc:21,
      doom:{ title:'세단기의 입', what:'세단기에 손이 빨려 들어갑니다', dc:17, sec:50,
        text:`세단기 입구에 손끝으로 금을 그었다. 철이 금에 닿아 멈췄다. 칼날이 헛돈다.<br><br>직원이 철을 더 밀었다. 금이 운다. 이쪽 손끝에서 운다. 손끝을 금에서 뗄 수가 없다.<br>철이 밀리는 만큼 금이 밀리고, 금이 밀리는 만큼 손끝이 끌려간다.<br><br>칼날 소리가 손톱 끝에 닿았다. 세단기는 종이를 먹는다. 금도 먹는다. 금을 쥔 손도.`,
        dieText:`빠진 사람은 찾으러 온다. 찾지 못하면 아무나 데려간다.<br><br>세단실 바닥에 종이 가루가 쌓였다. 하얀 가루 사이에 빨간 것이 조금 섞였다.<br>다음 정각 장부의 들어옴과 나감은 같았다. 한 사람이 빠지고 한 사람이 들어갔다. 직원이 계수기를 한 번 눌렀다.` },
      ok:`세단기 입구에 금을 그었다. 철이 멈췄다. 칼날이 헛돈다. 직원이 철을 밀었다.<br><br>금을 끊었다. 스스로. 손끝을 빼고 금 끝을 직원 손등에 붙였다. 직원 손이 금에 묶여 멈췄다.<br>그 사이 철을 빼냈다. 표지 사진 속 여자가 웃고 있다. 7층에서는 안 웃었다. 철을 품에 넣었다. 직원은 묶인 손을 내려다볼 뿐 소리를 내지 않았다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 직원이 계수기를 누르는 틈에 철을 빼낸다.', k:'hide', dc:21,
      ok:`직원은 넣기 전에 계수기를 누른다. 누르는 순간 눈이 계수기로 간다.<br><br>그 순간에 철을 바꿔 쥐었다. 여자 철을 빼고 옆의 빈 철을 끼웠다.<br>빈 철이 세단기로 들어갔다. 직원이 표지를 입술로 읽는다. 아무 이름도 안 적힌 표지를. 입술이 오래 움직였다.`,
      ng:`바꿔 쥐었는데 직원이 계수기를 안 보고 눌렀다. 눈이 이쪽 손에 있었다.<br><br>직원이 이쪽 손목을 잡았다. 철을 놓지 않자 손목째 세단기 쪽으로 끈다.<br>철을 놓았다. 철이 들어갔다. 칼날 소리가 났다. 손목에 직원 손가락 자국이 남았다. 엄지 자리가 둥글게 파였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-18 } }
  ] },

{ at:'B3', t:'7호차 — 손바닥의 금',
  x:`이 열차에는 얼굴을 바꾸는 것이 탔다. 검표원이었다가, 면도하던 남자였다가.<br><br>
    앞 좌석 등받이에 손톱으로 긁은 글씨가 있었다. 옆에 선 얼굴을 믿지 마.<br>
    일행 얼굴을 하나씩 봤다. 다 아는 얼굴이다. 그게 문제다. 그것은 아는 얼굴이 된다.<br><br>
    금은 안과 밖을 나눈다. 사람 안에도 그을 수 있다면.`,
  o:[
    { l:'① 일행 손바닥마다 작은 금을 하나씩 그어 둔다.', k:'gaze', dc:21, wake:1,
      ok:`일행 손을 하나씩 잡고 손바닥에 손끝으로 작은 금을 그었다. 동그라미 하나. 보이지 않는다. 이쪽 손끝만 안다.<br><br>나중에 손을 잡으면 금이 손끝에 걸린다. 걸리면 일행이다. 안 걸리면.<br>식당칸 앞에서 한 사람이 이쪽 손을 잡고 끌었다. 서두르자고. 손바닥이 매끈했다. 손을 빼고 뒤로 물러섰다. 그 얼굴이 웃으며 흘러내렸다.<br><br>금은 문과 바닥에 긋는 것인 줄 알았다. 사람 손에 그으면 그 사람이 이쪽 금 안에 든다. 얼굴은 바꿔도 손바닥 속 금은 못 바꾼다.`,
      ng:`그어 두는데 한 사람 손바닥에서 금이 안 그어진다. 손끝이 미끄러진다.<br><br>다시 그었다. 또 미끄러진다. 그 사람이 이쪽을 본다. 아무 표정 없이.<br>손을 놓았다. 그 사람이 손을 거두며 말했다. 손이 차서 그런가 보다고. 일행 수를 셌다. 맞다. 그래서 더 무서웠다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 마력을 써서 일행 둘레에 금을 두르고 들어오는 것을 본다.', k:'steady', dc:21, cost:{ mana:24 },
      ok:`좌석 둘을 마주 놓고 일행을 앉힌 뒤 둘레에 금을 둘렀다. 열차 바닥에 둥글게.<br><br>그리고 기다렸다. 금 안의 사람은 금 안에 있다. 새로 들어오려는 것은 금에 걸린다.<br>통로 저편에서 일행 중 한 사람 얼굴이 걸어왔다. 진짜는 금 안에 앉아 있다. 걸어온 얼굴이 금 앞에서 멈추고 고개를 갸웃했다. 그리고 다른 칸으로 갔다.`,
      ng:`둘렀는데 일행 하나가 화장실에 간다며 금 밖으로 나갔다. 말릴 새가 없었다.<br><br>돌아왔다. 금 앞에 섰다. 들어오지 못한다.<br>그 사람이 금 밖에서 이쪽 이름을 부른다. 목소리가 맞다. 얼굴도 맞다. 금을 열어 줘야 할지 모르겠다. 정각이 지날 때까지 둘 다 움직이지 않았다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-16, mana:-5 } }
  ] },

{ at:'B', t:'쉬는 자리 — 귓속말',
  x:`다음에 어디로 갈지 정해야 한다. 말을 해야 정한다.<br><br>
    벽이 얇다. 문 너머에서 숨소리가 난다. 이쪽이 말하면 저쪽이 듣는다.<br>
    금은 밖의 것이 들어오지 못하게 한다. 안의 것이 나가지 못하게도 할 수 있다. 소리도 안의 것이다.<br><br>
    일행이 이쪽 입만 본다.`,
  o:[
    { l:'① 마력을 써서 소리를 가두는 금을 친다.', k:'steady', dc:21, cost:{ mana:20 },
      ok:`일행을 바싹 붙여 앉히고 둘레에 금을 쳤다. 바닥에 한 바퀴, 머리 위에 한 바퀴.<br><br>금 안에서 말했다. 보통 목소리로. 문 너머 숨소리가 바뀌지 않는다. 못 듣는 것이다.<br>길을 정했다. 금을 풀자 바깥 빗소리가 한꺼번에 들어왔다. 금 안이 얼마나 조용했는지 그제야 알았다.`,
      ng:`쳤는데 머리 위 금이 덜 닫혔다. 손바닥만 한 틈.<br><br>말소리가 그 틈으로 나갔다. 위로. 천장으로. 천장 너머 누군가의 발밑으로.<br>위층에서 무언가 바닥에 귀를 대는 소리가 났다. 일어나 다른 데로 옮겼다. 정한 길은 버렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-12, mana:-5 } },
    { l:'② 손가락으로 바닥에 길을 그려 보인다.', k:'fix', dc:20,
      ok:`말하지 않았다. 바닥 먼지에 손가락으로 길을 그렸다. 지금 자리에 점 하나, 나갈 문에 동그라미.<br><br>일행이 고개를 끄덕였다. 다 그리고 나서 손바닥으로 지웠다. 지우는 것까지가 금이다.<br>문 너머 숨소리는 한 번도 안 바뀌었다.`,
      ng:`그렸는데 일행 하나가 못 알아봤다. 어디냐고 물었다. 소리 내어.<br><br>문 너머 숨소리가 멎었다. 멎은 채로 오래 있다.<br>바닥 그림을 지우고 일어섰다. 문 쪽 반대로 갔다. 정하지 못한 채로.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-14 } },
    { l:'③ 문 너머 숨소리를 금 안에 가둔다.', k:'gaze', dc:22,
      ok:`이쪽을 가두지 않았다. 문 너머를 가뒀다. 문 아래 틈으로 손을 넣어 저쪽 바닥에 금을 둘렀다. 숨소리 둘레에.<br><br>숨소리가 갇혔다. 저쪽 것이 무슨 소리를 내도 이쪽에 안 온다. 이쪽 소리도 저쪽에 안 간다. 금 안에 든 귀는 금 밖을 못 듣는다.<br>보통 목소리로 길을 정했다. 나가면서 금은 그대로 뒀다. 저쪽 것은 아침까지 그 안에 있을 것이다.`,
      ng:`손을 넣는데 저쪽에서 손이 마주 왔다. 손바닥과 손바닥이 문 밑에서 닿았다.<br><br>차다. 금을 그으려던 손끝을 저쪽 손이 쥐었다. 놓지 않는다.<br>일행이 이쪽 허리를 잡아당겼다. 손이 빠졌다. 손등이 문 밑단에 긁혔다. 저쪽에서 낮게 웃는 소리가 났다. 다 들었다는 뜻이다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B1', t:'방파제 — 넘어오는 파도',
  x:`방파제는 외길이다. 바람이 세다. 파도가 방파제를 넘을 때마다 발목까지 쓸어 간다.<br><br>
    항구 쪽 끝에서 손전등 줄이 다가온다. 바깥쪽에는 콘크리트 블록 사이로 검은 물이 드나든다.<br>
    멀리 바다 쪽에서 큰 것이 온다. 파도다. 방파제 높이보다 크다.<br><br>
    물은 금의 적이다. 흐르는 것은 나누지 못한다. 그런데 이 물은 흐르지 않는다. 덮친다.`,
  o:[
    { l:'① 방파제를 가로질러 금을 긋고 파도를 받는다.', k:'steady', dc:22,
      doom:{ title:'넘어오는 파도', what:'파도에 쓸려 갑니다', dc:18, sec:45,
        text:`방파제를 가로질러 금을 그었다. 바다 쪽으로 휘게. 일행을 금 뒤에 앉혔다.<br><br>파도가 왔다. 금에 부딪혔다. 금이 운다. 물보라가 금 위로 넘어간다. 금 안쪽은 젖지 않는다.<br>두 번째 파도. 금에 금이 갔다. 손끝에서 피가 났다.<br><br>세 번째가 금을 넘었다. 물이 이쪽 다리를 감고 바깥쪽으로 끈다. 블록 사이 검은 틈으로.`,
        dieText:`물은 금의 적이다. 덮치는 물은 더 그렇다.<br><br>방파제 위에 젖은 금 자국이 한 줄 남았다. 바다 쪽으로 휜.<br>블록 사이로 검은 물이 드나든다. 들어갈 때 하나, 나올 때 하나. 숫자는 맞다.` },
      ok:`금을 긋고 일행을 뒤에 앉혔다. 파도가 왔다. 금이 받아 물보라를 위로 넘겼다.<br><br>두 번째에 금이 갈라지기 전에 금을 바꿨다. 막는 금에서 흘리는 금으로. 휜 쪽을 더 휘게. 물이 금을 타고 양옆으로 갈라졌다.<br>세 번째 파도가 금 양쪽으로 흘러 블록 사이로 빠졌다. 금 안쪽 발목은 마른 채다. 손끝에서 피가 조금 났다. 그것뿐이다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 등대 쇠문 안으로 일행을 밀어 넣는다.', k:'evade', dc:21,
      ok:`등대 쇠문을 밀었다. 녹이 슬어 무겁다. 어깨로 밀자 열렸다.<br><br>일행을 밀어 넣고 마지막으로 들어가 문을 당겼다. 닫히는 순간 파도가 쇠문을 쳤다. 문이 종처럼 울렸다.<br>계단 위 꼭대기에 큰 유리 렌즈가 있다. 불은 꺼졌다. 문틈에 금을 하나 그었다. 손전등 줄이 지나갈 때까지.`,
      ng:`밀었는데 쇠문이 안 열린다. 안에서 잠겼다.<br><br>파도가 왔다. 문에 등을 붙이고 버텼다. 물이 가슴까지 덮쳤다가 빠졌다. 빠질 때 다리를 끈다.<br>문고리를 잡고 버텼다. 손가락 하나가 꺾였다. 일행 하나의 외투 자락을 끝까지 쥐고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'B2', t:'이중문 — 하나를 닫아야 열리는 문',
  x:`병동 끝에 문이 둘 겹쳐 있다. 첫 문을 닫아야 둘째 문이 열린다. 둘을 같이 열 수 없다.<br><br>
    그 사이 공간은 사람 둘이 겨우 선다. 한 번에 둘씩.<br>
    일행은 다섯이다. 세 번을 오가야 한다. 문이 열리고 닫힐 때마다 문 위 초록 등이 깜빡인다.<br><br>
    다음 정각까지 십오 분이다. 한 번 오가는 데 오 분.`,
  o:[
    { l:'① 마력을 써서 첫 문 문틈에 닫힘의 금을 긋는다.', k:'fix', dc:21, cost:{ mana:24 }, wake:1,
      ok:`첫 문을 연 채로 문틈을 따라 금을 한 줄 그었다. 문짝과 문틀이 만나는 자리에. 닫혔을 때 생길 선을 미리.<br><br>둘째 문 자물쇠가 딸깍 했다. 첫 문이 열려 있는데. 문은 금을 읽었다. 금이 닫혔다고 하니 닫힌 것이다.<br>다섯이 한꺼번에 지났다. 금을 지우자 둘째 문이 저절로 잠겼다.<br><br>문은 문짝으로 닫히는 게 아니다. 선 하나로 닫힌다. 그 선을 손으로 그을 수 있다. 이제 문을 보면 문짝보다 닫히는 선이 먼저 보인다.`,
      ng:`그었는데 문이 금을 안 읽는다. 둘째 문이 꿈쩍 않는다.<br><br>마력만 문틈으로 샜다. 그 사이 오 분이 갔다.<br>결국 둘씩 나눠 오갔다. 마지막 둘이 지날 때 정각이 됐다. 복도 끝에서 딸깍 소리가 시작됐다. 마지막 문이 닫히는 소리와 섞였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-14, mana:-5 } },
    { l:'② 둘씩 나눠 서두르지 않고 세 번 오간다.', k:'steady', dc:20,
      ok:`둘씩 보냈다. 이쪽은 첫 번에도 가고, 돌아와서 두 번째에도 가고, 세 번째에도 갔다. 문을 여닫는 사람이 하나는 있어야 한다.<br><br>문 사이 좁은 데서 세 번 숨을 골랐다. 문 위 초록 등이 깜빡일 때마다 그림 속 사람이 문 반대쪽으로 달린다.<br>정각 이 분 전에 끝났다. 이쪽이 마지막으로 둘째 문을 닫았다.`,
      ng:`둘씩 보내는데 두 번째에 첫 문이 안 닫힌다. 무언가 끼었다. 슬리퍼 한 짝.<br><br>빼냈다. 누구 것인지 모른다. 일행 것은 아니다.<br>시간이 갔다. 세 번째 둘이 지날 때 정각이 됐다. 딸깍. 문 사이 좁은 데서 계수기 소리를 들었다. 셀 데가 모자라 둘 사이가 한 사람으로 세어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 문 위 비상구 등의 그림을 읽는다.', k:'gaze', dc:21,
      ok:`초록 등 그림 속 사람이 문 반대쪽으로 달린다. 처음엔 장난인 줄 알았다.<br><br>그림 속 사람이 달리는 쪽 벽을 더듬었다. 판자 하나가 들뜬다. 그 뒤에 배관 통로가 있다. 한 사람씩 기어 들어갈 너비.<br>이중문은 그대로 두고 그리로 갔다. 문을 여닫는 소리도, 초록 등 깜빡임도 없이.`,
      ng:`읽으려는데 그림 속 사람이 멈췄다. 고개를 돌린다. 이쪽을 본다.<br><br>그림이다. 초록 칠 위의 하얀 선이다. 그런데 본다.<br>눈을 뗄 수가 없었다. 일행이 팔을 흔들어 깨웠다. 정각까지 남은 시간이 반으로 줄어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-18 } }
  ] },

{ at:'B3', t:'특실 복도 — 번호 없는 문',
  x:`특실 칸 4호실과 5호실 사이에 문이 하나 더 있다. 숫자가 없다. 놋쇠 못 자국만 둘.<br><br>
    손잡이가 반질반질하다. 많이 열린 문이다.<br>
    문틀 둘레 나무에 무언가 새겨져 있다. 칼끝으로 그은 가는 선. 문을 한 바퀴 둘렀다.<br><br>
    누가 이 문을 금으로 막았다. 막은 지 오래됐다. 선 한 군데가 닳았다.`,
  o:[
    { l:'① 문틀에 새긴 오래된 금을 손끝으로 읽는다.', k:'gaze', dc:21,
      ok:`선을 손끝으로 따라갔다. 깊게 새겼다. 마력이 아니라 칼로. 마력이 없는 사람이 그었다.<br><br>마력 없이 그은 금은 그은 사람의 마음으로 선다. 한 군데 닳은 데는 손잡이 쪽이다. 열고 싶은 손이 자꾸 닿은 자리다.<br>문을 열지 않았다. 열고 싶은 마음이 금을 닳게 한다. 그 마음을 접고 지나갔다. 등 뒤 문 안에서 한숨 소리가 났다.`,
      ng:`따라가는데 닳은 데에서 손끝이 문 안쪽으로 빨려 들었다. 손톱 하나만큼.<br><br>문 너머가 차다. 무언가 손톱 끝을 핥았다.<br>손을 뺐다. 손톱이 하얗게 셌다. 문틀의 닳은 데가 조금 더 닳아 있었다. 이쪽 손이 닳게 했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-18 } },
    { l:'② 마력을 써서 닳은 자리를 덧긋는다.', k:'steady', dc:21, cost:{ mana:22 },
      ok:`닳은 자리에 손끝을 대고 마력으로 덧그었다. 칼로 그은 홈에 마력이 고였다.<br><br>문 전체의 선이 한 번 빛났다가 가라앉았다. 손잡이가 조금 빛을 잃었다. 덜 반질반질하다.<br>먼저 금을 그은 사람이 누군지는 모른다. 그 사람 금을 이쪽 마력이 이었다. 둘이 같이 막는다.`,
      ng:`덧긋는데 칼로 그은 금이 마력을 안 받는다. 튕겨 낸다.<br><br>마력이 손끝으로 되돌아왔다. 손가락 마디가 꺾이는 것처럼 아프다.<br>문손잡이가 저절로 반 바퀴 돌았다. 금이 흔들린 틈에. 다시 돌아갔다. 다음번에는 다 돌 것이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, mind:-14, mana:-5 } }
  ] },

{ at:'B', t:'금 안의 사람 — 늦게 들어온 손님',
  x:`쉬는 자리에 금을 둘렀다. 일행 다섯과, 오는 길에 만난 사람 하나. 여섯이 금 안에 앉았다.<br><br>
    여섯째는 비를 맞았다고 했다. 외투가 젖었다. 그런데 금 안에 들어온 뒤로 외투에서 김이 안 난다. 다른 사람 외투에서는 다 난다.<br>
    금은 밖의 것을 막는다. 이미 안에 든 것은 못 막는다.<br><br>
    여섯째가 웃으며 손을 비빈다. 따뜻하다고.`,
  o:[
    { l:'① 금을 지우고 여섯째만 남도록 다시 긋는다.', k:'steady', dc:22, wake:1,
      ok:`일어나 말했다. 금이 흐려졌으니 다시 긋겠다고. 금을 지웠다.<br><br>새로 그었다. 일행 다섯 둘레를 감고, 여섯째 앞에서 꺾어 그 사람을 밖으로 냈다. 금이 사람 사이를 지났다. 한 획이 두 쪽을 갈랐다.<br>여섯째가 금 밖에서 웃음을 멈췄다. 일어서지 않았다. 그대로 앉아 이쪽만 봤다. 아침까지.<br><br>금은 땅을 나누는 줄 알았다. 사람과 사람 사이도 나눈다. 누구를 안에 둘지 고르는 것도 금 긋는 일이다. 고르는 손이 오늘 생겼다.`,
      ng:`지우는 순간 여섯째가 일어섰다. 금이 없는 그 짧은 틈에.<br><br>새로 긋기 전에 여섯째가 일행 하나 뒤로 돌아갔다. 사람 사이를 금이 지나갈 데가 없다.<br>그대로 다시 그었다. 여섯이 다 안에 들었다. 아까와 같다. 아까보다 여섯째가 가깝다. 아침까지 아무도 눈을 감지 못했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 여섯째에게 외투를 벗어 말리라고 한다.', k:'gaze', dc:21,
      ok:`외투를 벗어 말리라고 했다. 다들 그렇게 하고 있다고.<br><br>여섯째가 머뭇거리다 외투를 벗었다. 안이 말랐다. 셔츠도 말랐다. 비를 한 방울도 안 맞은 몸이다.<br>일행이 다 봤다. 여섯째는 외투를 다시 입고 일어섰다. 금을 넘어 나갔다. 넘을 때 금이 아무 소리도 내지 않았다. 안에서 밖으로 나가는 것은 막지 않는다.`,
      ng:`말리라고 했더니 여섯째가 순순히 벗었다. 셔츠까지 젖어 있다. 김도 난다. 이번에는.<br><br>의심한 게 미안했다. 여섯째가 웃으며 이쪽 외투를 받아 같이 널어 주었다.<br>아침에 보니 이쪽 외투 주머니가 비어 있었다. 여섯째도 없었다. 금은 멀쩡했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-14, spirit:-16 } },
    { l:'③ 금 안에 금을 하나 더 그어 일행만 들인다.', k:'fix', dc:21,
      ok:`큰 금은 두고, 그 안에 작은 금을 하나 더 그었다. 일행 다섯만 들어갈 크기.<br><br>여섯째에게 자리가 모자라 그런다고 했다. 여섯째는 큰 금 안, 작은 금 밖에 남았다.<br>밤새 여섯째가 작은 금 테두리를 손가락으로 쓰다듬었다. 끊긴 데가 있나 찾는 손이다. 없었다.`,
      ng:`작은 금을 긋는데 여섯째가 먼저 안쪽으로 다리를 뻗었다. 금이 그 다리 위를 지나갔다.<br><br>금이 다리에 걸려 끊겼다. 작은 금이 열린 채로 남았다.<br>여섯째가 사과하며 다리를 거뒀다. 다시 그었다. 이번엔 일행 하나가 끊긴 데로 손을 넣는 것을 여섯째가 웃으며 봤다. 무엇을 본 건지 모르겠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B1', t:'야적장 — 대걸레 폭의 길',
  x:`노인이 사라졌다. 골목 바닥에 노인의 모자가 떨어져 있다. 모자 둘레가 깨끗하다.<br><br>
    깨끗한 자국이 한 줄, 컨테이너 사이로 이어진다. 대걸레 폭만큼. 표백제 냄새.<br>
    일부러 보라는 것처럼 나 있다. 따라오라는 것처럼.<br><br>
    금을 긋는 사람에게는 보인다. 이 줄은 길이 아니다. 테두리다. 무언가를 둘러치는 중이다.`,
  o:[
    { l:'① 깨끗한 줄을 가로질러 금으로 끊는다.', k:'break', dc:21, cost:{ mana:20 },
      ok:`깨끗한 줄 한가운데를 마력으로 가로질러 그었다. 줄이 둘로 끊겼다.<br><br>둘러치던 것은 다 둘러야 테두리가 된다. 끊긴 테두리는 테두리가 아니다.<br>멀리서 대걸레 소리가 멈췄다. 한참 있다가 다시 시작됐다. 이번엔 끊긴 데로 오는 소리다. 고치러. 그동안 일행은 반대쪽으로 빠졌다.`,
      ng:`끊었는데 표백제가 금을 먹었다. 거품이 일며 금이 녹는다.<br><br>마력만 빠졌다. 깨끗한 줄은 그대로 이어진다.<br>줄 끝에서 고무장화 소리가 났다. 뽀득. 이쪽 금이 녹은 자리를 보러 온다. 컨테이너 틈에 몸을 넣고 숨을 죽였다. 표백제 냄새가 코앞을 지나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-14, mana:-5 } },
    { l:'② 줄을 따라가지 않고 줄 바깥으로 돈다.', k:'steady', dc:21,
      ok:`줄이 휘는 쪽을 봤다. 둥글게 휜다. 무엇을 두르려는지 알면 그 바깥이 보인다.<br><br>줄 바깥으로만 걸었다. 줄을 한 번도 안 밟았다. 컨테이너 셋을 돌아 야적장 끝에 닿았다.<br>돌아보니 줄이 이쪽이 지나온 데를 빙 둘러 닫혀 있었다. 조금만 늦었으면 안에 있었다.`,
      ng:`돌았는데 줄이 계속 바깥으로 넓어진다. 이쪽이 도는 만큼.<br><br>줄을 밟지 않으려 하다 보니 줄 쪽으로만 몰렸다. 막다른 골목이다.<br>결국 줄을 밟고 넘었다. 밟는 순간 신발 밑창이 하얗게 탔다. 저 멀리서 누가 수첩에 무언가 적는 소리가 났다. 빗소리 속에서 그 소리가 들렸다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'계단참 — 백까지 세는 보호사들',
  x:`4층 계단참에 보호사 둘이 벽을 보고 섰다. 코가 벽에 닿을 만큼.<br><br>
    둘이 같이 숨을 쉰다. 입속으로 숫자를 센다. 지금 예순여덟.<br>
    백이 되면 돌아설 것이다. 계단을 내려가려면 그 등 뒤를 지나야 한다.<br><br>
    등 뒤를 지나는 데 숫자 스물이 든다. 일행 다섯이 다 지나려면 더 든다.`,
  o:[
    { l:'① 둘의 발뒤꿈치 뒤로 금을 한 줄 긋는다.', k:'steady', dc:21,
      ok:`보호사 둘의 발뒤꿈치 바로 뒤에 금을 한 줄 그었다. 벽과 나란히. 둘을 벽과 금 사이에 넣었다.<br><br>일흔다섯. 일행이 하나씩 등 뒤를 지났다. 아흔. 마지막이 이쪽이다. 아흔아홉. 계단 아래로 내려섰다.<br>백. 둘이 돌아섰다. 금 앞에서 멈췄다. 한 발도 못 뗐다. 둘이 같이 고개를 숙여 발밑을 봤다. 같은 박자로. 다시 하나부터 세기 시작했다.`,
      ng:`그었는데 숫자가 빨라졌다. 일흔, 여든, 아흔. 금을 느낀 것이다.<br><br>일행 셋이 지났을 때 백이 됐다. 둘이 돌아섰다. 금에 걸려 멈췄다. 그런데 팔은 금을 넘는다. 길다.<br>넷째의 어깨가 잡혔다. 끌어당겨 뺐다. 어깨에 손가락 자국 다섯. 정수리에 초록 물이 든 보호사가 그 손을 오래 내려다봤다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 숫자를 같이 세며 박자에 맞춰 지난다.', k:'hide', dc:21,
      ok:`입속으로 같이 셌다. 일흔. 일흔하나. 둘이 숨 쉬는 박자에 이쪽 숨을 맞췄다.<br><br>숨이 같은 박자면 등 뒤 발소리가 숨소리에 묻힌다. 일행 하나씩, 숫자 넷에 한 사람.<br>아흔여섯에 다 지났다. 백. 둘이 돌아섰을 때 계단참은 비어 있었다. 둘이 같이 고개를 갸웃했다.`,
      ng:`같이 세는데 이쪽이 하나를 앞서 셌다. 여든셋에 여든넷.<br><br>둘의 숫자가 멈췄다. 같이. 벽을 보던 고개가 천천히 돈다.<br>뛰었다. 계단 셋을 한 번에. 등 뒤에서 둘이 다시 세기 시작했다. 하나부터. 이번엔 이쪽을 보고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B3', t:'기관실 문 — 같은 얼굴 둘',
  x:`기관실 문 작은 창 너머에 기관사가 둘이다. 같은 모자, 같은 얼굴, 같은 기름때.<br><br>
    둘이 동시에 이쪽을 본다. 동시에 말한다. 저놈이 가짜요.<br>
    시계는 04:38. 종착 불빛이 창 가득 다가온다. 하나를 골라야 한다. 고를 시간이 없다.<br><br>
    금은 안과 밖을 나눈다. 나눌 때 걸리는 것이 있다. 금을 아는 것은 금 앞에서 머뭇거린다.`,
  o:[
    { l:'① 문턱에 금을 긋고 둘에게 이쪽으로 오라고 한다.', k:'gaze', dc:22,
      ok:`문을 반만 열고 문턱에 금을 한 줄 그었다. 보이지 않는다. 그리고 둘에게 말했다. 이쪽으로 와서 손을 달라고.<br><br>둘이 같이 온다. 하나는 그대로 금을 밟고 손을 내밀었다. 다른 하나는 금 앞에서 반 박자 멈췄다. 발끝이 금 위에서 떨렸다.<br>금을 모르는 사람은 금을 밟는다. 금을 아는 것만 멈춘다. 반 박자 멈춘 쪽을 가리켰다. 일행이 그쪽을 잡아 눌렀다.`,
      ng:`그었는데 둘이 같이 멈췄다. 같은 박자로. 둘 다 금 앞에서.<br><br>하나는 진짜라서 멈췄다. 이쪽이 이상한 짓을 한다고. 다른 하나는 금을 알아서 멈췄다. 겉으로는 같다.<br>골라야 할 때가 지났다. 열차가 갈림길 신호를 지났다. 붉은 신호가 창밖으로 날아갔다. 손끝에 남은 마력이 다 식었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 마력을 써서 둘을 각각 따로 금에 가둔다.', k:'steady', dc:21, cost:{ mana:26 },
      ok:`들어가 둘 둘레에 금을 하나씩 둘렀다. 빠르게. 둥글게 둘.<br><br>둘이 각자 금 안에 갇혔다. 하나는 금 안에서 레버를 향해 손을 뻗었다. 금 밖이라 안 닿는다. 다른 하나는 금 안에서 가만히 이쪽을 봤다.<br>가만히 있는 쪽은 금을 처음 겪는 사람이다. 뻗는 쪽은 금이 무엇인지 아는 것이다. 뻗는 쪽 금을 하나 더 감았다.`,
      ng:`두르는데 하나를 다 두르기 전에 다른 하나가 움직였다. 레버로.<br><br>레버가 내려갔다. 열차가 크게 기울었다. 이쪽은 바닥에 굴렀다. 금 하나가 반쯤 그어진 채 남았다.<br>일어났을 때 둘 다 바닥에 쓰러져 있었다. 둘 다 같은 얼굴로 신음한다. 레버를 누가 내렸는지 모른다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14, mana:-6 } }
  ] },

{ at:'B', t:'시계 — 금이 버티는 시간',
  x:`문이 열릴 때까지 삼 분. 일행이 기계실에서 사슬을 풀고 있다.<br><br>
    복도 저편에서 장화 소리들이 온다. 여럿이다. 이쪽은 복도 한가운데에 금을 그어야 한다.<br>
    금은 마력만큼 버틴다. 큰 금은 마력을 빨리 먹는다. 삼 분을 버틸 큰 금을 그을 마력이 남았는지 모르겠다.<br><br>
    손끝을 비볐다. 따뜻하다. 반쯤 남았다.`,
  o:[
    { l:'① 마력을 써서 복도를 꽉 채우는 금 하나로 버틴다.', k:'steady', dc:22, cost:{ mana:28 },
      ok:`복도 벽에서 벽까지 굵게 그었다. 남은 마력을 다 실었다.<br><br>장화들이 금 앞에서 멈췄다. 민다. 금이 운다. 손끝에서 운다. 일 분. 이 분.<br>삼 분째에 금이 얇아졌다. 손끝이 차다. 등 뒤에서 사슬 풀리는 소리가 났다. 금을 놓고 뛰었다. 금이 꺼지는 소리를 뒤에 두고 문을 지났다.`,
      ng:`그었는데 이 분째에 마력이 바닥났다. 금이 가늘어지다 끊겼다.<br><br>장화들이 넘어왔다. 손전등이 얼굴을 쳤다. 뒤로 물러서며 손끝으로 한 줄을 더 그었다. 마력 없이. 아무것도 안 막는다.<br>등 뒤에서 사슬이 풀렸다. 뛰었다. 누군가 외투 자락을 잡아 찢었다. 찢긴 자락을 두고 문을 지났다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14, mana:-8 } },
    { l:'② 짧은 금 여러 개를 엇갈려 긋는다.', k:'fix', dc:21, wake:1,
      ok:`복도를 다 막지 않았다. 벽에서 반만 나온 짧은 금을 왼쪽, 오른쪽, 왼쪽. 엇갈려 다섯 줄.<br><br>장화들이 첫 금에 걸려 오른쪽으로 비킨다. 둘째에 걸려 왼쪽으로. 막히지 않는다. 대신 갈지자로 걷는다. 곧장 오면 열 걸음, 갈지자로 오면 서른 걸음.<br>마력은 큰 금 하나의 반만 들었다. 삼 분이 지나도 금들이 남았다.<br><br>막지 않아도 된다. 늦추면 된다. 짧은 금 여러 개가 큰 금 하나보다 오래간다. 마력을 셈하는 손이 하나 늘었다.`,
      ng:`엇갈려 그었는데 장화들이 금을 따라 걷지 않는다. 금 위를 넘는다. 짧은 금은 넘기 쉽다.<br><br>다섯 줄이 숨 다섯 번을 벌었다. 그것뿐이다.<br>마지막 줄 앞에서 손전등이 얼굴을 비췄다. 눈을 감고 뒤로 뛰었다. 문을 지날 때 등 뒤에서 무언가 날아와 어깨를 쳤다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 금을 긋지 않고 일행을 도와 사슬을 푼다.', k:'bond', dc:21,
      ok:`금을 포기했다. 기계실로 들어가 사슬 고리를 같이 잡았다. 손이 하나 늘면 삼 분이 이 분이 된다.<br><br>사슬이 풀렸다. 이 분 십 초. 장화들이 복도 끝에 닿았을 때 문은 이미 열려 있었다.<br>문을 지나며 문틈에 금 한 획을 그었다. 남은 마력으로. 그 한 획이 문 닫히는 시간을 벌었다.`,
      ng:`도우러 들어갔는데 사슬 고리가 손이 하나 더 들어갈 자리가 없다. 오히려 방해가 됐다.<br><br>복도로 다시 나왔을 때 장화들이 코앞이다. 금을 그을 틈이 없다.<br>손을 들어 막았다. 손바닥에 무언가 내리쳐졌다. 장대 끝이다. 손바닥이 퍼렇게 부었다. 그래도 사슬은 풀렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'네온 — 물웅덩이의 빛줄기',
  x:`붉은 네온 간판이 젖은 바닥에 길게 비친다. 글자 하나가 나가 깜빡인다.<br><br>
    물웅덩이마다 빛줄기가 한 줄씩 누웠다. 곧고 붉다.<br>
    금은 손끝으로 긋는다. 빛도 선이다. 남이 그어 놓은 선을 빌릴 수 있다.<br><br>
    마력이 바닥에 가깝다. 쫓는 것들은 네온 밑을 지나야 이쪽에 닿는다.`,
  o:[
    { l:'① 웅덩이에 비친 빛줄기를 금으로 삼는다.', k:'luck', dc:21,
      ok:`웅덩이 셋에 누운 빛줄기를 손끝으로 이었다. 마력은 잇는 데만 조금.<br><br>빛줄기가 금이 됐다. 붉은 금이다. 간판이 켜져 있는 동안은.<br>쫓는 것들이 웅덩이 앞에서 멈췄다. 간판이 깜빡일 때마다 한 걸음씩 들어오다 다시 멈춘다. 꺼진 글자가 하필 이쪽 앞이었다.`,
      ng:`이었는데 간판이 통째로 꺼졌다. 정전이다.<br><br>빛줄기가 사라지자 금도 사라졌다. 잇는 데 쓴 마력만 웅덩이에 빠졌다.<br>어둠 속에서 쫓는 것들이 웅덩이를 밟고 왔다. 첨벙, 첨벙. 그 소리를 등지고 뛰었다. 간판은 이쪽이 골목을 빠진 뒤에 다시 켜졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 간판 밑을 피해 어두운 쪽으로 돈다.', k:'steady', dc:20,
      ok:`빛 아래로 안 갔다. 빛이 닿지 않는 담벼락 밑으로 돌았다.<br><br>쫓는 것들은 네온 아래 붉은 바닥을 훑는다. 붉은 데만 본다. 붉은 데에 아무것도 없으니 지나간다.<br>담벼락은 젖고 차다. 등을 대고 그들이 다 지나갈 때까지 섰다. 빛이 이쪽 신발 끝 한 치 앞에서 멈춰 있었다.`,
      ng:`돌았는데 어두운 쪽에도 누가 서 있다. 빛을 피하는 것은 이쪽만이 아니다.<br><br>그 사람과 어깨가 닿았다. 서로 놀랐다. 그 사람이 먼저 빛 쪽으로 튀어 나갔다.<br>쫓는 것들이 그 사람을 봤다. 그리고 그 사람이 나온 어두운 쪽을 봤다. 이쪽을. 다시 뛰었다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-15, spirit:-14 } }
  ] },

{ at:'B', t:'문 — 밖에서 그어 놓은 금',
  x:`숨어든 방에서 나가려는데 발이 문턱에서 안 넘어간다.<br><br>
    문턱 바깥에 금이 있다. 이쪽이 그은 것이 아니다. 분필로. 반듯하게. 방을 한 바퀴 둘렀다.<br>
    누가 밖에서 이 방을 금 안에 넣었다. 금을 그을 줄 아는 누군가가 쫓는 쪽에 있다.<br><br>
    금 안은 이쪽이다. 남의 금 안에 갇히는 것은 처음이다.`,
  o:[
    { l:'① 마력으로 남의 금을 안에서 끊는다.', k:'break', dc:22,
      doom:{ title:'남의 금', what:'남이 그은 금에 묶여 끌려갑니다', dc:18, sec:50,
        text:`문턱 금에 손끝을 대고 마력을 밀어 넣었다. 끊으려고.<br><br>금이 마력을 받았다. 먹었다. 끊기지 않고 오히려 굵어진다. 이쪽 마력으로.<br>손끝이 금에 붙었다. 금이 당긴다. 바깥 어딘가 금을 그은 사람 쪽으로.<br><br>몸이 문턱 위로 끌려 넘어간다. 금은 넘기지 못하게 하는 줄 알았다. 넘기는 데도 쓴다.`,
        dieText:`금 긋는 사람은 남의 금 안에 갇혀 본 적이 없었다.<br><br>그날 방문 앞 분필 금이 한 군데 끊겼다. 안에서가 아니라 밖에서.<br>복도에 분필 가루가 길게 끌린 자국이 남았다. 모퉁이까지. 모퉁이 너머에는 분필 한 토막이 반듯하게 놓여 있었다.` },
      ok:`손끝을 대고 마력을 밀어 넣으려다 멈췄다. 금이 마력을 먹으려 한다. 남의 금은 남의 것이다.<br><br>마력을 거두고 손톱으로 분필 금을 긁었다. 그냥 긁었다. 분필은 분필이다. 한 손가락 너비가 지워졌다.<br>지워진 틈으로 나갔다. 마력으로 그은 금이 아니었다. 마력으로 맞서면 먹힌다. 손톱이면 된다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 금의 시작과 끝이 만나는 자리를 찾는다.', k:'gaze', dc:21,
      ok:`금을 따라 방 안을 한 바퀴 돌았다. 벽 너머로 이어진다. 창 밑에서 만난다. 시작과 끝이 겹친 자리.<br><br>겹친 자리는 두껍다. 그 옆 한 치는 얇다. 긋는 손이 마지막에 힘을 뺀 자리다.<br>거기를 손바닥으로 문질렀다. 지워졌다. 창으로 나갔다. 금을 그은 사람도 사람이다. 끝에서는 지친다.`,
      ng:`찾는데 시작과 끝이 안 만난다. 금이 두 바퀴 돈다. 세 바퀴.<br><br>도는 동안 어지럽다. 금을 따라 걷는 동안 금 안에서 몇 바퀴 돌았는지 모르겠다.<br>주저앉았다. 일행이 창을 깨서 끌어냈다. 깨진 창으로 나오는 데 금은 아무것도 안 했다. 창 밑에는 금이 없었다. 처음부터.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'B', t:'새벽 — 다 쓴 손끝',
  x:`밤이 끝나 간다. 손끝을 비볐다. 차다. 마력이 바닥났다.<br><br>
    문 하나만 더 지나면 된다. 문 앞 복도에 무언가 기다린다. 금 하나면 지날 수 있다.<br>
    금은 마력으로 긋는 것이라고 배웠다. 마력이 없으면 금도 없다고.<br><br>
    주머니에 분필 한 토막이 있다. 아까 남의 금을 지우고 주운 것이다.`,
  o:[
    { l:'① 분필로 금을 긋는다. 마력 없이.', k:'steady', dc:22, wake:1,
      ok:`쪼그려 앉아 분필로 복도를 가로질러 그었다. 반듯하게. 천천히. 마력은 한 방울도 없다.<br><br>그은 선 앞에서 숨을 골랐다. 이 선은 안과 밖을 나눈다. 이쪽이 그렇게 정했다. 정한 마음이 선 위에 앉는다.<br>복도의 것이 선 앞에서 멈췄다. 머뭇거린다. 마력이 없는 선인데. 일행이 그 옆을 지났다.<br><br>금은 마력이 아니었다. 마력은 금을 굵게 할 뿐이다. 금은 나누겠다고 정하는 손이다. 손끝이 비어도 손은 남는다.`,
      ng:`그었는데 분필이 젖어 선이 끊긴다. 점점이.<br><br>점선이다. 점과 점 사이로 복도의 것이 손을 넣어 본다. 들어온다.<br>일행을 밀어 문으로 보내고 이쪽이 점선 앞에 섰다. 몸이 금이 됐다. 차가운 손이 가슴을 밀었다. 숨이 멎었다가 돌아왔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-24, spirit:-18 } },
    { l:'② 일행 손을 잡아 사람으로 금을 만든다.', k:'bond', dc:21,
      ok:`일행에게 손을 잡자고 했다. 다섯이 손을 잡고 둥글게 섰다. 그 가운데에 섰다.<br><br>사람이 이어지면 선이다. 둥글게 이어지면 금이다. 마력 대신 손 다섯.<br>둥근 채로 복도를 지났다. 복도의 것이 원 바깥을 돌며 따라왔다. 손 하나가 떨어지기를 기다리며. 아무도 안 놓았다.`,
      ng:`잡았는데 일행 하나 손이 땀으로 미끄럽다. 걷는 동안 손이 자꾸 빠진다.<br><br>빠질 때마다 원이 열린다. 열린 틈으로 찬 것이 들어왔다가 나간다.<br>문까지 원을 지켰다. 세 번 열렸다. 세 번 다 이쪽 등이 찼다. 문을 지난 뒤에도 등이 한참 시렸다.`,
      win:{ exp:18, mind:6 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 문 앞까지 숨을 멈추고 걷는다.', k:'hide', dc:21,
      ok:`금을 포기했다. 숨을 멈추고 벽을 따라 걸었다. 일행도.<br><br>복도의 것은 숨소리를 듣는다. 숨이 없는 것은 벽이다.<br>문까지 스물한 걸음. 열여덟째에 가슴이 터질 것 같았다. 스물하나. 문을 넘고 나서 숨을 토했다. 복도의 것이 그 소리에 돌아봤다. 문은 이미 닫혔다.`,
      ng:`멈추고 걷는데 열둘째 걸음에 숨이 터졌다.<br><br>복도의 것이 곧장 이쪽을 봤다. 일행은 앞에 있다. 이쪽만 들켰다.<br>뛰었다. 등 뒤에서 찬 손이 어깨를 스쳤다. 문을 넘고 나서도 어깨가 얼음 같았다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 외공 수련생 · 내공
// ------------------------------------------
kJob('ironbody', 'B', [

{ at:'B', t:'빗속 — 걸으며 하는 단련',
  x:`몸을 단련하는 사람은 하루를 몸을 치는 걸로 시작한다. 오늘은 그럴 틈이 없다.<br><br>
    들어오자마자 쫓겼다. 벽 앞에 설 시간도, 숨을 고를 시간도 없다.<br>
    단련을 하루 거르면 몸이 안다. 이틀 거르면 남이 안다.<br><br>
    빗속을 걷는다. 팔이 근질근질하다. 칠 데가 없으면 칠 데를 만든다.`,
  o:[
    { l:'① 걸으며 팔뚝과 팔뚝을 맞부딪친다.', k:'steady', dc:20, wake:1,
      ok:`걸음마다 팔뚝을 맞부딪쳤다. 왼 팔뚝 바깥으로 오른 팔뚝 안쪽을. 툭, 툭. 빗소리에 묻힐 만큼만.<br><br>백 걸음에 백 번. 팔이 데워졌다. 이백 걸음에 손목까지. 걷는 일과 치는 일이 한 박자가 됐다.<br>뛸 일이 생겼을 때 팔이 먼저 풀려 있었다.<br><br>단련은 벽 앞에서 하는 것인 줄 알았다. 걸음이 벽이다. 숨이 북이다. 이제 걷는 동안에도 몸이 맞는다. 하루를 거를 날이 없어졌다.`,
      ng:`부딪치는데 팔뚝 뼈끼리 맞았다. 살이 아니라.<br><br>찌릿한 것이 팔꿈치까지 올라갔다. 손가락이 저려 한동안 안 쥐어졌다.<br>앞서 가던 일행이 돌아봤다. 무슨 소리냐고. 대답 대신 팔을 털었다. 털 때마다 저린 데가 울었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 내공을 써서 젖은 몸을 안에서 데운다.', k:'fix', dc:20, cost:{ qi:20 },
      ok:`걸으면서 숨을 아랫배로 내렸다. 내공이 배꼽 밑에서 돌기 시작한다.<br><br>한 바퀴 돌 때마다 손끝이 따뜻해진다. 젖은 옷에서 김이 오른다. 빗속에서 이쪽만 연기를 피운다.<br>일행 하나가 옆에 붙어 걸었다. 손을 이쪽 등에 댔다. 사람 등이 난로가 됐다.`,
      ng:`돌리는데 걸음과 숨이 안 맞는다. 내공이 가슴에서 걸렸다.<br><br>기침이 났다. 쇳맛이 올라왔다. 걸으면서 돌리는 건 앉아서 돌리는 것과 다르다.<br>억지로 멈췄다. 가슴이 한참 묵직했다. 몸은 그대로 찼다.`,
      win:{ exp:16, dream:1, hp:8 }, lose:{ hp:-20, mind:-14, qi:-5 } }
  ] },

{ at:'B1', t:'경매장 — 찌르는 장대',
  x:`노란 비옷 셋이 장대로 얼음 더미를 찌른다. 한 뼘 간격으로. 빠짐없이.<br><br>
    숨을 데가 생선 상자 밑밖에 없었다. 상자 위에 얼음이 덮였다. 등이 위를 향했다.<br>
    장대 끝은 쇠갈고리다. 찌르면 서걱거린다. 얼음이면 서걱, 생선이면 푹.<br><br>
    사람이면 소리가 난다. 찔린 사람이 내는 소리가.`,
  o:[
    { l:'① 등에 숨을 모으고 찔려도 소리를 내지 않는다.', k:'steady', dc:21, wake:1,
      ok:`숨을 등으로 보냈다. 견갑골 사이에. 거기를 돌처럼 굳혔다.<br><br>장대가 왔다. 상자를 뚫고 등에 닿았다. 갈고리 끝이 살갗을 눌렀다. 들어오지 않았다. 굳힌 등이 받았다.<br>소리를 안 냈다. 숨도 안 바꿨다. 장대가 한 번 더 눌렀다가 빠졌다. 얼음 소리였다고 여긴 모양이다.<br><br>맞으면 소리를 내는 것은 몸의 버릇이다. 그 버릇을 오늘 끊었다. 아픈 것은 아픈 대로 두고 몸이 대답하지 않는다. 이제 맞는 순간에 숨이 흐트러지지 않는다.`,
      ng:`모았는데 장대가 등 말고 허벅지로 왔다. 굳힐 틈이 없었다.<br><br>갈고리가 들어왔다. 이를 악물었다. 소리는 참았다. 숨이 참지 못했다. 헉.<br>장대가 멈췄다. 비옷이 고개를 숙여 상자를 봤다. 노인이 저쪽에서 생선 상자를 엎었다. 비옷들이 그쪽으로 갔다. 허벅지에서 따뜻한 것이 얼음을 녹인다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-12 } },
    { l:'② 장대가 오는 박자를 세어 몸을 옮긴다.', k:'sense', dc:21,
      ok:`장대가 찌르는 소리를 셌다. 한 뼘에 하나. 일정하다. 다음 자리를 알 수 있다.<br><br>다음 자리가 이쪽 등이다. 찌르기 직전에 몸을 반 뼘 옮겼다. 얼음이 서걱거렸다.<br>장대가 이쪽 옆구리 옆 얼음을 찔렀다. 지나갔다. 반 뼘이 사람 하나를 살렸다.`,
      ng:`셌는데 비옷 하나가 박자를 바꿨다. 두 번 찌르고 건너뛰고.<br><br>옮긴 자리가 하필 건너뛴 다음 자리다. 장대가 어깨를 찍었다.<br>소리를 삼켰다. 장대가 빠지며 외투 천을 찢어 갔다. 갈고리 끝에 천 조각이 걸려 올라갔다. 비옷이 그 천 조각을 오래 봤다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'7층 — 손목의 가죽 띠',
  x:`눈을 뜨니 손목이 침대 난간에 묶여 있다. 가죽 띠다. 버클이 손 닿지 않는 쪽에 있다.<br><br>
    띠는 오래 썼다. 많은 사람이 이렇게 당겼다. 당기면 조이게 만들었다.<br>
    복도 시계가 정각 오 분 전이다. 정각이면 점검이 돈다.<br><br>
    몸을 단련하는 사람은 몸을 크게 쓰는 법만 안다. 작게 쓰는 법은 배운 적이 없다.`,
  o:[
    { l:'① 내공으로 손목을 부풀렸다가 한 번에 숨을 뺀다.', k:'steady', dc:21, wake:1,
      ok:`숨을 손목으로 몰았다. 손목이 굵어졌다. 띠가 조인다. 조일 만큼 조이게 뒀다.<br><br>그리고 숨을 한 번에 뺐다. 손목이 줄었다. 띠는 조였던 데서 안 돌아온다. 그 사이 손가락 하나 들어갈 틈이 생겼다.<br>손을 접어 빼냈다. 다른 손은 쉬웠다. 정각 일 분 전이었다.<br><br>굳히는 것만 단련인 줄 알았다. 풀 줄도 알아야 굳힌 게 쓸모가 있다. 몸을 크게 했다가 작게 하는 숨을 오늘 몸이 찾았다. 어떤 띠도 이제 처음 조인 만큼만 조인다.`,
      ng:`부풀렸는데 띠가 생각보다 더 조였다. 피가 손끝으로 안 간다.<br><br>숨을 빼려는데 숨이 안 빠진다. 손목이 부은 채로 굳었다. 손끝이 하얘진다.<br>딸깍. 문이 열렸다. 간호사가 부은 손목을 보고 띠를 한 칸 풀어 줬다. 친절하게. 그리고 다른 띠를 하나 더 가져왔다.`,
      win:{ exp:24, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 난간 이음매를 손날로 쳐서 띠째 뺀다.', k:'break', dc:21,
      ok:`띠는 질기다. 난간은 쇠다. 쇠도 이음매가 있다. 난간이 침대 틀에 꽂힌 자리.<br><br>묶인 손을 쥐고 손날로 이음매를 쳤다. 한 번, 두 번. 손날이 아프지 않다. 이런 데 쓰려고 단련했다.<br>세 번째에 난간이 빠졌다. 띠가 난간 끝으로 미끄러져 나왔다. 손목에 띠를 감은 채 일어났다.`,
      ng:`쳤는데 소리가 컸다. 쇠 울리는 소리가 복도로 나갔다.<br><br>딸깍 소리가 멈췄다. 빨라졌다. 이쪽으로.<br>네 번째에 난간이 빠졌다. 그때 문이 열렸다. 보호사 둘이 빠진 난간을 보고 이쪽 손목을 다른 침대에 다시 묶었다. 손날이 그제야 아프기 시작했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B3', t:'4호차 지붕 — 바람',
  x:`3호차로 가려면 지붕을 넘어야 한다. 사다리를 올라 뚜껑을 밀었다.<br><br>
    바람이 몸을 들어 올리려 한다. 비가 옆으로 친다. 열차가 굽이를 돌 때마다 지붕이 기운다.<br>
    엎드리면 바람이 등 밑으로 들어온다. 서면 날아간다.<br><br>
    3호차 뚜껑까지 열다섯 걸음. 앞에서 기적이 운다. 터널이 온다.`,
  o:[
    { l:'① 숨을 발바닥까지 내려 몸을 무겁게 한다.', k:'steady', dc:22, wake:1,
      ok:`숨을 아랫배에서 더 아래로 내렸다. 허벅지, 무릎, 발바닥. 내공이 발바닥에서 지붕 철판을 눌렀다.<br><br>몸이 무거워졌다. 무게가 늘어난 것이 아니다. 무게가 다 아래에 모였다. 바람이 등을 밀어도 발이 안 뜬다.<br>허리를 숙이고 걸었다. 한 걸음씩 철판을 밟아 박듯이. 열다섯 걸음. 뚜껑을 열고 내려섰을 때 터널이 머리 위를 지났다.<br><br>맞는 것을 버티는 법만 익혔다. 미는 것을 버티는 법은 다르다. 무게를 어디에 둘지 정하는 숨이 생겼다. 서 있는 자리가 이제 쉽게 안 뽑힌다.`,
      ng:`내렸는데 반만 내려갔다. 무릎에서 멈췄다. 발바닥이 가볍다.<br><br>바람이 들었다. 몸이 옆으로 밀린다. 지붕 가장자리로. 환기구 테를 잡았다. 손가락 넷으로.<br>터널이 왔다. 엎드렸다. 등 위로 천장이 스쳤다. 테를 잡은 손가락이 찢어졌다. 놓지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-14 } },
    { l:'② 엎드려 환기구 테를 하나씩 잡으며 긴다.', k:'evade', dc:21,
      ok:`엎드려 지붕에 배를 붙였다. 환기구 테가 서너 걸음마다 있다. 하나를 잡고, 다음 것을 잡고.<br><br>바람이 등 밑으로 들어와도 손이 붙들고 있다. 열다섯 걸음이 테 넷이다.<br>넷째 테를 잡았을 때 터널이 왔다. 납작 엎드렸다. 천장이 머리카락을 쓸었다. 3호차 뚜껑이 손 끝에 닿았다.`,
      ng:`기는데 둘째 테가 녹슬어 떨어져 나갔다. 손에 테만 쥐어졌다.<br><br>몸이 가장자리로 미끄러진다. 다리가 지붕 밖으로 나갔다. 발끝에 빗물과 바람뿐이다.<br>손톱을 철판 이음매에 박았다. 손톱 셋이 들렸다. 거기서 멈췄다. 터널 지나는 동안 그렇게 매달려 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'쫓기는 길 — 뛰어내리기',
  x:`계단이 막혔다. 위에서 발소리가 온다. 창 밖은 이 층 높이다. 아래는 젖은 시멘트 바닥.<br><br>
    일행은 창틀에 매달렸다가 떨어질 생각이다. 이 층이면 다리 하나는 각오해야 한다.<br>
    몸을 단련하는 사람은 맞는 법을 안다. 땅에 맞는 것도 맞는 것이다.<br><br>
    먼저 뛰어내려 보여 줘야 한다. 어떻게 떨어지는지.`,
  o:[
    { l:'① 떨어지는 동안 몸을 풀었다가 닿는 순간 굳힌다.', k:'steady', dc:21, wake:1,
      ok:`창틀에서 손을 놓았다. 떨어지는 동안 몸에서 힘을 다 뺐다. 물주머니처럼.<br><br>발이 닿는 순간 무릎을 접고 옆으로 굴렀다. 구르는 순간 등과 어깨를 굳혔다. 시멘트가 등을 쳤다. 받았다. 일어났다.<br>위를 보고 일행에게 말했다. 굳어 있다가 닿으면 부러진다고. 풀어 있다가 닿는 순간만 굳히라고.<br><br>단련한 몸은 늘 굳어 있었다. 오늘 처음 풀어 봤다. 풀린 몸이 닿는 순간 굳으면 땅도 주먹 한 번이다. 떨어지는 일이 이제 겁나지 않는다.`,
      ng:`놓았는데 몸이 먼저 굳었다. 버릇이다.<br><br>굳은 다리가 시멘트를 받았다. 발목에서 소리가 났다. 굴렀지만 늦었다.<br>일어났다. 발목이 디뎌지기는 한다. 그 뒤로 디딜 때마다 소리가 났다. 일행은 이쪽을 보고 떨어지는 법을 바꿨다. 이쪽이 틀린 걸 보고.`,
      win:{ exp:24, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 먼저 내려가 아래에서 일행을 받는다.', k:'bond', dc:21,
      ok:`먼저 뛰어내려 굴렀다. 일어나 창 밑에 섰다. 팔을 벌렸다.<br><br>하나씩 떨어졌다. 받는다기보다 같이 넘어져 준다. 이쪽 몸이 바닥 노릇을 했다. 다섯 번.<br>다섯 번째에 갈비뼈가 울었다. 그래도 아무도 다리를 다치지 않았다. 일어났을 때 등이 젖은 시멘트 모양으로 차다.`,
      ng:`받는데 둘째가 생각보다 빨리 떨어졌다. 팔이 다 안 벌어졌다.<br><br>그 사람 무릎이 이쪽 가슴에 박혔다. 숨이 터졌다. 둘이 같이 쓰러졌다.<br>나머지는 알아서 떨어졌다. 한 사람이 발목을 접질렸다. 이쪽은 한참 숨을 못 쉬었다. 위층 창에서 손전등이 아래를 비췄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-12 } }
  ] },

{ at:'B1', t:'냉동 창고 — 얼음 활송로',
  x:`창고 바닥 구석에 쇠 홈통이 뚫려 있다. 얼음을 아래층 경매장으로 내려보내는 길이다.<br><br>
    홈통 안은 반들반들하다. 얼음물이 얇게 흐른다. 손을 대면 그대로 미끄러진다.<br>
    아래에서 돌 가는 소리가 올라온다. 일정하게. 얼음 분쇄기다.<br><br>
    홈통 입구에 장갑이 한 짝 걸려 있다. 손가락 끝이 아래를 가리킨다.`,
  o:[
    { l:'① 팔다리로 홈통 벽을 버티며 천천히 내려간다.', k:'steady', dc:22,
      doom:{ title:'얼음 활송로', what:'분쇄기 쪽으로 빨려 들어갑니다', dc:18, sec:45,
        text:`홈통에 들어가 등과 발로 양쪽 벽을 눌렀다. 버텼다. 천천히 미끄러진다.<br><br>쇠벽이 차다. 손바닥이 얼음물에 젖어 미끄럽다. 내공을 손바닥에 모았다. 붙는다.<br>홈통이 꺾이는 데서 벽이 넓어졌다. 발이 벽에서 떨어졌다.<br><br>미끄러진다. 빨라진다. 돌 가는 소리가 발밑에 왔다. 얼음 조각이 같이 쏟아진다. 버틸 벽이 없다.`,
        dieText:`맞는 것은 버틸 수 있다. 미끄러지는 것은 버틸 데가 있어야 버틴다.<br><br>그날 새벽 경매장 얼음 더미가 조금 붉었다. 노란 비옷들이 그 얼음을 생선 상자에 퍼 담았다.<br>홈통 입구의 장갑은 그대로 아래를 가리킨다.` },
      ok:`등과 발로 벽을 누르고 천천히 내려갔다. 꺾이는 데서 벽이 넓어졌다.<br><br>발이 떨어지려는 순간 다리를 쭉 뻗어 무릎을 굳혔다. 다리가 홈통을 가로지르는 빗장이 됐다. 멈췄다.<br>발밑에서 분쇄기가 돈다. 그 옆으로 점검 덮개가 있다. 발뒤꿈치로 차 열었다. 경매장 얼음 더미 위로 굴러떨어졌다. 차다. 살았다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 홈통을 두고 창고 문 경첩을 친다.', k:'break', dc:21,
      ok:`문 안쪽 손잡이는 없다. 경첩은 있다. 문짝을 문틀에 붙든 쇠 셋.<br><br>가운데 경첩에 손바닥을 대고 숨을 실어 쳤다. 얼어 있던 쇠가 찡 울렸다. 둘째, 셋째. 경첩 핀이 한 치 빠졌다.<br>손가락으로 핀을 뽑았다. 문이 한쪽으로 기울었다. 그 틈으로 나갔다. 손바닥이 얼어서 아픈 줄 몰랐다.`,
      ng:`쳤는데 언 쇠가 안 울린다. 손바닥이 쇠에 붙었다.<br><br>떼었다. 살갗이 쇠에 남았다. 다시 쳤다. 피가 쇠 위에서 얼었다.<br>경첩은 그대로다. 손바닥은 그대로가 아니다. 결국 한 시간을 다 채우고 밖에서 문이 열릴 때까지 기다렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B2', t:'한방 처치실 — 점과 선의 인형',
  x:`처치실 가운데에 침술 인형이 여럿 서 있다. 사람 키만 하다. 몸에 점과 선이 그려져 있다.<br><br>
    몸을 단련하는 사람은 그 점들을 안다. 맞으면 안 되는 자리다. 단련으로도 못 막는 자리.<br>
    인형을 세어 봤다. 일곱. 다시 셌다. 여덟.<br><br>
    여덟째 인형의 그려진 점 하나가 깜빡인다. 숨 쉬는 박자로.`,
  o:[
    { l:'① 내공을 실어 깜빡이는 점을 손끝으로 찌른다.', k:'gaze', dc:21, cost:{ qi:24 },
      ok:`여덟째 인형 앞에 섰다. 깜빡이는 점은 명치 밑이다. 숨이 모이는 자리.<br><br>손끝에 내공을 모아 거기를 찔렀다. 인형이 멈췄다. 숨 쉬던 박자가 끊겼다.<br>인형 몸의 점과 선이 하나씩 꺼졌다. 다시 셌다. 일곱. 인형 발치 바닥에 처음 보는 슬리퍼 한 켤레가 남았다. 아직 따뜻하다.`,
      ng:`찔렀는데 점이 옮겨 갔다. 손끝이 닿기 직전에 한 치 옆으로.<br><br>인형이 이쪽 손목을 잡았다. 손가락이 손목 안쪽 점을 정확히 눌렀다. 맞으면 안 되는 자리다.<br>팔 전체가 풀렸다. 손가락 하나 못 움직인다. 일행이 인형 손을 비틀어 뗐다. 팔은 정각이 지나서야 돌아왔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, spirit:-16, qi:-5 } },
    { l:'② 점 없는 자리로만 인형들 사이를 지난다.', k:'steady', dc:21,
      ok:`인형들 사이를 지나며 몸을 비틀었다. 인형의 손이 닿을 수 있는 높이마다 이쪽 몸의 점을 감췄다. 명치, 관자놀이, 목.<br><br>맞아도 되는 데만 내밀었다. 어깨, 등, 팔뚝. 인형 하나가 팔을 뻗었다. 어깨에 닿았다. 굳힌 어깨다. 미끄러졌다.<br>지나왔다. 다시 셌다. 여덟. 아까 그대로다. 그대로인 게 더 낫다.`,
      ng:`지나는데 인형들이 이쪽 몸의 점을 안다. 다 같은 그림이다. 사람 몸이다.<br><br>여덟째 손이 등 뒤에서 왔다. 견갑골 사이를 눌렀다. 단련으로 못 막는 자리 하나.<br>숨이 멎었다. 무릎이 꺾였다. 일행이 끌어냈다. 숨이 돌아오는 데 백까지 셌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B3', t:'2호차 — 열린 우리',
  x:`화물칸 쇠 우리 여섯. 우리마다 큰 개가 엎드렸다. 입마개를 했다. 얼굴 냄새를 맡는 코다.<br><br>
    우리 하나는 문이 열려 있다. 안이 비었다.<br>
    상자 사이 어둠에서 숨소리가 난다. 낮고 빠르다. 입마개 안에서 나는 숨이 아니다. 입마개가 벗겨진 숨이다.<br><br>
    몸을 단련하는 사람은 이빨을 받아 본 적이 있다. 개 이빨은 처음이다.`,
  o:[
    { l:'① 팔뚝을 굳혀 내밀고 물게 한다.', k:'steady', dc:22,
      ok:`왼 팔뚝을 앞으로 내밀었다. 숨을 거기 모아 굳혔다. 오른손은 허리에.<br><br>어둠에서 개가 튀어나왔다. 팔뚝을 물었다. 이빨이 살갗을 눌렀다. 단련한 살갗이 이빨을 받았다. 들어오지 않았다. 아프다. 들어오지는 않았다.<br>개가 머리를 흔들었다. 흔드는 대로 팔을 내줬다가 멈추는 순간 오른손으로 입마개 끈을 다시 채웠다. 개가 낑 하고 우리로 돌아갔다.`,
      ng:`굳혔는데 개가 팔뚝을 안 물었다. 다리를 물었다. 굳히지 않은 쪽을.<br><br>이빨이 종아리에 들어왔다. 흔든다. 쓰러졌다.<br>일행이 상자를 던져 떼어 냈다. 개는 열린 우리로 돌아가 엎드렸다. 입가에 붉은 것이 묻었다. 종아리에 이빨 자국이 둥글게 두 줄이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-32, spirit:-12 } },
    { l:'② 얼굴을 가리고 우리 앞을 천천히 지난다.', k:'hide', dc:21,
      ok:`외투 깃을 세워 얼굴을 묻었다. 개들은 얼굴 냄새를 맡는다. 얼굴을 주지 않았다.<br><br>천천히 걸었다. 뛰면 쫓는다. 우리 다섯을 지날 때 코들이 이쪽을 따라 움직였다. 아무도 일어서지 않았다.<br>열린 우리의 개는 어둠 속에서 다른 것을 쫓는 중이었다. 이쪽 말고. 이 열차에서 얼굴을 바꾸는 것을.`,
      ng:`가리고 지나는데 열린 우리의 개가 길을 막았다. 깃 사이 얼굴을 맡는다. 코가 뺨에 닿았다.<br><br>개가 고개를 갸웃했다. 이쪽 냄새가 아니라 누군가의 냄새가 났다는 얼굴이다. 아까 손을 잡았던 누군가.<br>개가 이빨을 드러냈다. 뒷걸음질 쳤다. 등이 우리 창살에 닿았다. 창살 안의 개가 등 뒤에서 깼다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'골목 — 둘러싼 몽둥이',
  x:`골목 양 끝이 막혔다. 우비 넷이 몽둥이를 들었다. 쇠파이프다.<br><br>
    일행은 뒤에 있다. 담을 넘으려면 시간이 든다.<br>
    몸을 단련하는 사람은 맞는다. 맞으면서 버틴다. 그게 이 몸이 하는 일이다.<br><br>
    넷이 한꺼번에 온다. 서두르지 않는다. 시간이 저쪽 편이라는 걸 안다.`,
  o:[
    { l:'① 골목 한가운데 서서 넷을 다 받는다.', k:'steady', dc:22,
      doom:{ title:'둘러싼 몽둥이', what:'차 트렁크에 실려 갑니다', dc:18, sec:50,
        text:`한가운데 섰다. 숨을 온몸에 돌렸다. 첫째 파이프가 어깨에 왔다. 받았다. 둘째가 등에. 받았다.<br><br>셋째는 정강이에. 넷째는 뒤통수에.<br>단련으로도 못 막는 자리가 있다. 정수리, 뒤통수. 눈앞이 하얘졌다.<br><br>무릎이 꺾였다. 팔을 잡혔다. 끌린다. 골목 끝에 차가 서 있다. 트렁크가 열려 있다. 빗물이 고였다.`,
        dieText:`맞으면서 버티는 몸이었다. 넷까지는 버텼다.<br><br>골목 끝에서 트렁크 닫히는 소리가 났다. 차가 빗속으로 미끄러져 나갔다. 전조등을 켜지 않고.<br>골목 바닥에 쇠파이프 하나가 휜 채 남았다. 휜 모양이 사람 어깨 모양이다.` },
      ok:`한가운데 섰다. 첫째가 어깨에, 둘째가 등에. 받았다. 굳힌 데로만 받았다.<br><br>셋째가 머리로 올 때 고개를 숙여 어깨 위로 흘렸다. 넷째가 정강이로 올 때 정강이로 마주 찼다. 파이프가 휘었다.<br>넷이 물러섰다. 휜 파이프를 내려다본다. 그 사이 일행이 담을 다 넘었다. 마지막으로 이쪽이 넘었다. 등에 파이프 자국이 세 줄 부었다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 담 밑에 등을 붙이고 일행을 하나씩 올린다.', k:'bond', dc:21,
      ok:`담에 등을 붙이고 손바닥을 깍지 꼈다. 일행 발을 하나씩 올려 담 위로 던졌다.<br><br>파이프가 왔다. 팔뚝으로 받으며 다음 사람을 올렸다. 셋째 사람을 올릴 때 옆구리를 맞았다. 숨을 굳혔다. 넷째.<br>마지막으로 담 위의 손이 이쪽 손목을 잡아 끌었다. 담 너머로 떨어지며 파이프 하나가 발뒤꿈치를 스쳤다.`,
      ng:`올리는데 셋째 사람이 담 위에서 미끄러져 다시 떨어졌다. 이쪽 위로.<br><br>둘이 엉켰다. 그 위로 파이프가 내려왔다. 그 사람 머리 위에 팔을 댔다. 팔뚝이 받았다. 금이 간 소리가 났다. 뼈인지 파이프인지.<br>다시 올렸다. 다 넘었다. 이쪽 팔이 반만 굽는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, mind:-12 } },
    { l:'③ 먼저 달려들어 첫째 파이프를 빼앗는다.', k:'break', dc:22,
      ok:`기다리지 않았다. 첫째에게 뛰어들었다. 파이프가 휘둘러지기 전에 팔꿈치 안쪽을 손날로 쳤다.<br><br>파이프가 손에서 빠졌다. 받아 쥐었다. 나머지 셋이 멈칫했다. 맞으러 오던 사람이 치러 왔다.<br>셋이 서로 눈치를 보는 사이 일행이 담을 넘었다. 파이프를 골목 끝으로 던지고 따라 넘었다.`,
      ng:`뛰어들었는데 첫째가 물러서고 둘째가 옆에서 쳤다. 처음부터 그렇게 서 있었다.<br><br>옆구리에 들어왔다. 굳힐 틈이 없었다. 숨이 끊겼다.<br>무릎을 꿇고 숨을 다시 잡는 동안 등에 두 번 더 왔다. 일행이 위에서 손을 내밀었다. 그 손을 잡고 기어올랐다. 다리에 힘이 안 들어왔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-34, spirit:-14 } }
  ] },

{ at:'B1', t:'야적장 — 젖은 크레인 사다리',
  x:`가장 높은 크레인에 사다리가 곧게 올라간다. 칸마다 빗물이 맺혔다. 꼭대기는 비구름에 반쯤 잠겼다.<br><br>
    저 위에서는 방파제가 보일 것이다. 장부 도면에 그어진 수로 입구도.<br>
    바람에 크레인이 아주 조금씩 흔들린다. 사다리 칸이 손바닥 밑에서 떤다.<br><br>
    젖은 쇠는 손바닥을 밀어낸다. 쥔 만큼 미끄러진다.`,
  o:[
    { l:'① 손바닥 말고 손가락 끝으로 칸을 건다.', k:'steady', dc:21, wake:1,
      ok:`손바닥으로 쥐지 않았다. 손가락 네 마디를 갈고리처럼 구부려 칸에 걸었다. 쥐지 않고 걸었다.<br><br>젖은 쇠가 손바닥을 밀어도 손가락 끝은 안 민다. 단련한 손끝이 쇠를 문다.<br>칸마다 걸고 올렸다. 꼭대기에서 방파제를 봤다. 수로 입구가 등대 아래 있다. 내려올 때도 손끝으로 걸었다. 손바닥은 한 번도 칸에 안 닿았다.<br><br>손끝은 찌르는 데 쓰라고 단련한 줄 알았다. 거는 데도 쓴다. 이제 매달릴 데가 있으면 어디든 손끝이 먼저 간다.`,
      ng:`걸었는데 손끝이 빗물에 불었다. 살갗이 물러 칸에서 미끄러진다.<br><br>중간쯤에서 손 하나가 빠졌다. 다른 손 손끝 넷에 몸이 매달렸다. 바람이 몸을 돌린다.<br>다리로 칸을 감고 겨우 붙었다. 손끝 살갗이 벗겨졌다. 꼭대기까지 갔다. 내려올 때 손끝이 칸마다 피를 남겼다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 내공을 써서 손바닥을 데워 젖은 쇠에 붙인다.', k:'fix', dc:21, cost:{ qi:22 },
      ok:`손바닥에 내공을 모았다. 데워진 손바닥이 칸에 닿자 김이 오른다. 빗물이 마른다. 마른 쇠는 손을 안 밀어낸다.<br><br>칸 하나마다 김 한 줄. 사다리에 김이 줄을 섰다.<br>꼭대기에서 방파제와 수로 입구를 봤다. 내려왔을 때 손바닥이 붉다. 사다리는 아래에서 위까지 한 줄로 김을 피우고 있었다. 누가 봤으면 다 봤을 것이다.`,
      ng:`데웠는데 꼭대기까지 갈 내공이 모자랐다. 중간에서 손바닥이 식었다.<br><br>식은 손바닥이 젖은 쇠에 미끄러졌다. 겨드랑이를 칸에 걸어 버텼다. 겨드랑이 살이 쓸렸다.<br>꼭대기는 못 갔다. 중간에서 본 방파제는 비에 가려 반만 보였다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-12, qi:-5 } }
  ] },

{ at:'B2', t:'세탁실 — 증기',
  x:`세탁실은 하얗다. 증기가 천장에서 바닥까지 찼다. 손을 뻗으면 손끝이 흐리다.<br><br>
    드럼이 줄지어 돈다. 쿵, 쿵. 증기가 피부를 덴다. 오래 있으면 살갗이 벌겋게 일어난다.<br>
    증기 사이로 그림자가 오간다. 바구니를 들었다. 걸음에 소리가 없다.<br><br>
    주방 쪽 문은 증기 한가운데를 지나야 한다. 증기가 제일 짙은 데로.`,
  o:[
    { l:'① 살갗을 굳혀 증기 한가운데를 곧장 지난다.', k:'steady', dc:21,
      ok:`숨을 살갗으로 돌렸다. 단련한 살갗은 맞는 것을 받는다. 뜨거운 것도 맞는 것이다.<br><br>증기 한가운데로 걸었다. 따갑다. 바늘 같다. 바늘을 맞는 셈 치고 걸었다. 일행은 이쪽 등 뒤에 붙었다. 이쪽 등이 증기를 갈랐다.<br>문에 닿았다. 등과 목덜미가 벌겋다. 일어나지는 않았다. 바구니 든 그림자는 끝내 이쪽을 못 봤다. 증기 속에서 증기처럼 걸었다.`,
      ng:`지나는데 드럼 하나가 문을 열며 증기를 뿜었다. 정면으로.<br><br>얼굴이 덴다. 눈을 감았다. 감은 채로 걸었다. 방향이 틀렸다. 드럼 쪽으로.<br>그림자 하나가 이쪽 팔을 잡아 돌려세웠다. 문 쪽으로. 문을 지나 돌아보니 아무도 없다. 팔에 잡힌 자국이 하얗다. 데지 않은 자리만.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 젖은 시트를 뒤집어쓰고 벽을 따라 돈다.', k:'fix', dc:20,
      ok:`바구니에서 젖은 시트를 꺼내 머리부터 뒤집어썼다. 일행에게도 한 장씩.<br><br>젖은 천은 증기를 받는다. 벽을 따라 돌았다. 증기가 덜한 쪽으로. 시트 다섯 장이 벽을 따라 줄지어 간다.<br>그림자들 사이에 섞였다. 그림자들도 시트를 들었다. 아무도 이쪽을 세지 않았다.`,
      ng:`뒤집어썼는데 시트가 뜨거운 물을 먹은 것이었다. 방금 드럼에서 나온 것.<br><br>머리부터 덴다. 벗어 던졌다. 던진 시트가 그림자 하나 앞에 떨어졌다.<br>그림자가 시트를 주워 들었다. 개어서 바구니에 넣었다. 그리고 이쪽을 향해 고개를 돌렸다. 증기 속이라 얼굴이 없다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 배수구 옆 버섯을 따며 바닥으로 엎드려 간다.', k:'luck', dc:20,
      ok:`증기는 위로 오른다. 바닥은 덜 뜨겁다. 엎드려 기었다.<br><br>배수구 둘레에 하얗고 통통한 버섯이 났다. 따뜻하고 젖은 데를 좋아하는 것이다. 한 줌 땄다. 냄새가 흙냄새다. 먹는 쪽이다.<br>바닥을 따라 문까지 기었다. 무릎이 다 젖었다. 데지는 않았다.`,
      ng:`엎드렸는데 바닥 배수구에서 뜨거운 물이 역류했다. 손바닥을 덮쳤다.<br><br>손을 들었다. 손바닥이 벌겋다. 버섯은 손에서 으깨졌다.<br>다시 일어서 증기 속을 뛰었다. 등이 덴다. 문에 닿았을 때 손바닥 껍질이 하얗게 일어나 있었다.`,
      win:{ exp:15, item:'야생 버섯' }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B3', t:'보일러 옆 — 묶인 안전판',
  x:`보일러 압력계 바늘이 빨간 칸에 들어갔다. 떨린다. 배관 이음새마다 김이 샌다. 쉭쉭.<br><br>
    안전판 밸브 손잡이가 사슬로 묶였다. 누가 일부러 묶었다. 열차가 더 빨리 가라고.<br>
    사슬은 손가락 굵기다. 자물쇠는 없다. 매듭으로 묶었다. 매듭이 김에 젖어 쇠처럼 굳었다.<br><br>
    바늘이 한 칸 더 간다. 이음새 하나가 하얘진다.`,
  o:[
    { l:'① 김을 맞으며 맨손으로 사슬 매듭을 비틀어 푼다.', k:'steady', dc:22,
      doom:{ title:'묶인 안전판', what:'터진 증기에 휩싸였습니다', dc:18, sec:45,
        text:`밸브 손잡이를 잡고 사슬 매듭에 손가락을 넣었다. 김이 손등을 덮는다. 살갗을 굳혔다.<br><br>비틀었다. 매듭이 반 바퀴 돈다. 또 반 바퀴. 김이 팔꿈치까지 덮는다.<br>매듭이 풀리기 직전에 머리 위 이음새가 터졌다.<br><br>하얀 것이 한꺼번에 쏟아졌다. 소리가 없다. 너무 커서 소리가 안 들린다. 굳힌 살갗 위로 뜨거운 것이 덮인다. 숨을 쉴 수가 없다. 숨 쉴 데에 김이 찼다.`,
        dieText:`맞는 것은 굳혀서 받는다. 숨 쉴 데에 찬 것은 굳힐 수가 없다.<br><br>안전판은 풀렸다. 매듭이 반쯤 풀린 채 사슬이 늘어졌다. 바늘이 빨간 칸에서 천천히 내려왔다.<br>기관차 뒤 바닥에 사람 손 모양으로 김이 서린 자리가 하나 있다. 금방 마른다.` },
      ok:`매듭에 손가락을 넣고 비틀었다. 김이 손등을 덮는다. 살갗을 굳혔다. 반 바퀴, 또 반 바퀴.<br><br>머리 위 이음새가 하얘졌다. 터지기 직전이다. 숨을 멈췄다. 숨 쉴 데를 닫았다. 매듭이 풀렸다.<br>밸브 손잡이를 당겼다. 안전판이 비명을 지르며 김을 하늘로 뿜었다. 바늘이 내려온다. 이음새는 터지지 않았다. 손등이 벌겋게 부었다. 숨은 그 뒤에 쉬었다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 내공을 실어 손날로 사슬을 끊는다.', k:'break', dc:22, cost:{ qi:26 },
      ok:`매듭을 풀 시간이 없다. 사슬 고리 하나를 골라 밸브 쇠에 걸었다. 손날에 내공을 모았다.<br><br>내리쳤다. 고리가 휘었다. 다시. 고리가 벌어졌다. 사슬이 풀려 떨어졌다.<br>밸브 손잡이를 당겼다. 김이 하늘로 솟았다. 손날이 저렸다. 손날 뼈가 한동안 웅웅 울렸다. 바늘이 빨간 칸에서 나왔다.`,
      ng:`내리쳤는데 고리가 휘기만 하고 안 벌어진다. 두 번째에 손날 살갗이 갈라졌다.<br><br>세 번째에 고리가 벌어졌다. 그 사이 이음새 하나가 터졌다. 옆에서.<br>김이 어깨를 덮었다. 굳힐 틈이 없었다. 밸브를 당기고 뒤로 굴렀다. 어깨 살갗이 하얗게 일었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-12, qi:-6 } }
  ] },

{ at:'B', t:'쉬는 자리 — 멍 세기',
  x:`쉬는 자리에서 웃옷을 걷었다. 멍을 셌다.<br><br>
    몸을 단련하는 사람은 멍을 센다. 어디를 맞았는지, 어디가 받았는지, 어디가 못 받았는지.<br>
    오늘 밤 멍이 스물셋이다. 대부분 받은 자리다. 셋은 못 받은 자리다. 그 셋이 문제다.<br><br>
    셋 중 하나가 옆구리다. 숨 쉴 때마다 결린다.`,
  o:[
    { l:'① 내공을 써서 결리는 옆구리에 숨을 돌린다.', k:'heal', dc:21, cost:{ qi:22 },
      ok:`앉아서 숨을 아랫배에 모으고 옆구리로 보냈다. 천천히. 결리는 자리를 숨으로 쓰다듬듯.<br><br>멍 밑의 굳은 피가 풀린다. 결림이 반으로 줄었다. 반은 남겼다. 다 풀면 다음에 그 자리를 또 못 받는다.<br>멍은 남기고 아픔만 덜었다. 일어서니 숨이 끝까지 들어간다.`,
      ng:`돌리는데 숨이 옆구리 앞에서 막혔다. 막힌 데가 멍이 아니라 금 간 갈비뼈다.<br><br>숨이 뼈를 건드렸다. 하얗게 아팠다. 소리를 삼켰다.<br>내공만 빠지고 결림은 그대로다. 숨을 반만 쉬기로 했다. 반 숨으로 남은 밤을 났다.`,
      win:{ exp:18, dream:1, hp:12 }, lose:{ hp:-24, mind:-12, qi:-5 } },
    { l:'② 못 받은 자리 셋을 골라 일부러 다시 친다.', k:'steady', dc:21,
      ok:`못 받은 자리 셋을 손바닥으로 쳤다. 작게, 여러 번. 아프다. 아픈 데를 아프게 했다.<br><br>멍이 든 자리는 다음에 또 맞는다. 쫓는 쪽도 멍을 본다. 그 자리를 오늘 밤 안에 받는 자리로 바꿔야 한다.<br>백 번씩 쳤다. 세 자리가 뜨거워졌다. 내일은 받을 것이다. 내일이 있다면.`,
      ng:`치는데 옆구리를 치는 순간 숨이 끊겼다. 눈앞이 깜깜했다.<br><br>쓰러졌다. 일행이 깨웠다. 무슨 짓이냐고 했다. 대답을 못 했다. 숨이 안 쉬어졌다.<br>단련도 때가 있다. 오늘 밤은 때가 아니었다. 옆구리가 두 배로 부었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, spirit:-12 } },
    { l:'③ 일행의 멍을 대신 봐 준다.', k:'gaze', dc:20,
      ok:`일행 웃옷을 걷게 하고 멍을 봤다. 맞은 자리를 보면 어떻게 맞았는지 안다.<br><br>한 사람은 늘 왼쪽을 맞았다. 왼쪽으로 돌아보는 버릇 때문이다. 다른 사람은 등만 맞았다. 늘 뛰다 맞았다.<br>하나씩 말해 줬다. 돌아보는 쪽을 바꾸라고, 뛰기 전에 한 걸음 옆으로 가라고. 다들 제 멍을 다시 봤다. 처음 보는 얼굴로.`,
      ng:`보는데 한 사람 멍이 이상하다. 맞은 자국이 아니다. 손가락 자국이다. 다섯. 목에.<br><br>그 사람은 기억이 없다고 했다. 언제 그랬는지.<br>말하지 말 걸 그랬다. 그 사람이 그 뒤로 내내 목을 만졌다. 이쪽도 자꾸 그 목을 봤다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B1', t:'선착장 — 선체와 부두 사이',
  x:`정문으로 가는 길은 부두 가장자리 하나뿐이다. 해무호 선체가 그 옆에 붙어 있다.<br><br>
    배가 너울에 흔들릴 때마다 틈이 벌어졌다 좁아진다. 좁아질 때 선체가 폐타이어를 짓누른다. 타이어가 납작해지며 운다.<br>
    일행이 그 가장자리를 한 줄로 지나야 한다. 선체가 좁혀 오면 사람이 타이어 노릇을 해야 한다.<br><br>
    너울이 한 번 왔다 간다. 숨 열 번에 한 번.`,
  o:[
    { l:'① 내공을 실어 등으로 선체를 받아 틈을 지킨다.', k:'steady', dc:22, cost:{ qi:26 },
      ok:`부두 가장자리에 서서 선체 쪽으로 등을 댔다. 숨을 등에 모아 굳혔다.<br><br>너울이 왔다. 선체가 등을 민다. 쇠의 무게다. 배 한 척의 무게가 아니라 너울의 무게다. 무릎을 반쯤 굽히고 받았다.<br>등 앞으로 일행이 지났다. 하나, 둘, 셋. 선체가 물러날 때 이쪽도 빠졌다. 등에 녹 자국이 판처럼 찍혔다.`,
      ng:`받았는데 너울이 생각보다 컸다. 등이 밀려 부두 쪽으로 붙었다.<br><br>앞뒤가 쇠와 시멘트다. 갈비뼈가 운다. 숨을 굳혔다. 그래도 운다.<br>선체가 물러났다. 무릎이 꺾였다. 일행이 겨드랑이를 잡아 끌었다. 숨 쉴 때마다 옆구리에서 쇳소리가 났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-12, qi:-6 } },
    { l:'② 너울 박자를 세어 한 사람씩 보낸다.', k:'sense', dc:21,
      ok:`타이어 우는 소리를 셌다. 숨 열 번에 한 번. 벌어지는 동안 숨 넷.<br><br>숨 넷에 한 사람씩. 등을 밀어 보냈다. 다 보냈다. 마지막에 이쪽이 갔다. 셋째 숨에 선체가 다가왔다. 넷째 숨에 다 지났다.<br>등 뒤에서 타이어가 짓눌려 울었다. 이쪽이 서 있던 자리에서.`,
      ng:`셌는데 너울 하나가 박자보다 일찍 왔다. 큰 배가 지나가며 만든 너울이다.<br><br>지나던 사람이 틈에 끼려 했다. 그 사람 앞에 몸을 넣었다. 선체가 이쪽 어깨를 짓눌렀다.<br>어깨가 빠졌다. 너울이 물러날 때 제자리에 들어갔다. 들어갈 때 이를 깨물었다. 그 사람은 무사했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 계류 밧줄을 타고 틈 위로 건너간다.', k:'evade', dc:22,
      ok:`머리 위로 계류 밧줄이 팽팽하다. 빗물이 밧줄을 타고 흐른다.<br><br>손끝을 걸고 매달렸다. 손을 하나씩 옮겼다. 발밑으로 선체와 부두가 닫혔다 열린다. 이쪽 발은 그 위에 있다.<br>건너편에서 내려 일행에게 손짓했다. 밧줄 타는 건 이쪽만 할 일이다. 일행은 박자를 세어 가장자리로 왔다. 이쪽이 위에서 세어 줬다.`,
      ng:`매달렸는데 너울에 배가 기울며 밧줄이 늘어졌다. 몸이 틈 쪽으로 내려간다.<br><br>발이 선체와 부두 사이에 닿았다. 닫히려 한다. 다리를 끌어올렸다. 장화 한 짝이 끼었다.<br>장화를 두고 다리만 뺐다. 선체가 장화를 짓눌렀다. 납작해지며 운다. 타이어처럼.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B2', t:'주방 — 음식 승강기',
  x:`주방 벽에 작은 승강기가 있다. 음식 승강기다. 쟁반 두 장이 들어갈 크기.<br><br>
    단추가 둘이다. 위, 아래. 이 건물에서 처음 보는 아래 단추다. 줄이 2층 원무과 식당까지 내려간다.<br>
    사람 하나가 접혀 들어가기에는 작다. 몸을 단련한 사람은 접히는 법도 안다. 무게가 문제다.<br><br>
    승강기 줄이 낡았다. 쟁반 둘이면 괜찮다. 사람 하나는.`,
  o:[
    { l:'① 몸을 접어 넣고 아래 단추를 누른다.', k:'steady', dc:21,
      doom:{ title:'음식 승강기', what:'승강기 통 아래로 떨어집니다', dc:17, sec:50,
        text:`어깨를 접고 무릎을 가슴에 붙여 승강기에 들어갔다. 일행이 아래 단추를 눌렀다.<br><br>덜컹. 내려간다. 줄이 운다. 위에서 줄 감기는 소리가 끊어졌다 이어졌다 한다.<br>3층과 2층 사이에서 덜컹 하고 멈췄다. 줄 하나가 끊어지는 소리.<br><br>승강기가 기울었다. 한쪽 줄만 남았다. 그 줄도 운다. 아래는 깜깜하다. 접힌 몸은 버틸 데를 못 찾는다.`,
        dieText:`접히는 법은 알았다. 무게를 줄이는 법은 몰랐다.<br><br>2층 원무과 식당 벽 안에서 무언가 떨어지는 소리가 났다. 아무도 보러 가지 않았다.<br>주방 승강기 단추 위에 아래 화살표가 있다. 그 위에 누가 테이프를 붙였다. 다음 사람을 위해.` },
      ok:`접어 넣었다. 일행이 아래 단추를 눌렀다. 덜컹. 내려간다. 줄이 운다.<br><br>3층과 2층 사이에서 줄 하나가 끊어졌다. 승강기가 기운다. 손바닥과 발바닥으로 승강기 통 벽을 밀었다. 굳혔다. 승강기와 통 벽 사이에 몸이 빗장처럼 걸렸다.<br>그대로 버티며 승강기 문을 발로 찼다. 2층 식당 쪽 문이 열렸다. 기어 나왔다. 뒤에서 승강기가 마지막 줄을 끊고 떨어졌다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 승강기 옆 배선 통로 문의 열쇠를 쓴다.', k:'sense', dc:21,
      ok:`승강기 옆 배선 통로 문에 열쇠가 꽂혀 있다. 꼬리표에 경비실.<br><br>돌렸다. 열렸다. 좁은 통로가 배관을 따라 내려간다. 사다리가 박혀 있다. 녹슬었지만 단단하다.<br>내려갔다. 2층에서 문이 하나 있다. 열자 원무과 뒤편 복도다. 열쇠는 도로 꽂아 뒀다. 경비실 열쇠를 가진 사람이 한 번 더 쓸 것이다.`,
      ng:`돌렸는데 열쇠가 안 돈다. 반대로 돌렸다. 돌았다. 잠기는 쪽으로.<br><br>통로 안쪽에서 철컥 소리가 났다. 안에 누가 있었다. 이쪽이 그 사람을 가뒀다.<br>문 안에서 두드리는 소리가 난다. 다시 열었다. 아무도 없다. 사다리 칸에 젖은 발자국이 아래로 이어진다. 따라 내려갔다. 발자국이 2층에서 끊겼다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'기관차 뒤 — 화부의 삽',
  x:`기관차 뒷문을 열자 열기가 덮친다. 화실 문이 열려 있다. 불이 하얗다.<br><br>
    화부가 등을 보이고 삽질을 한다. 쉬지 않는다. 돌아보지 않고 말한다. 삽 좀 잡아. 더 빨리 가야 돼.<br>
    화부 손등에 화상 자국이 겹겹이다. 일하는 손이다.<br><br>
    빨리 가면 종착에 빨리 닿는다. 종착에 닿기 전에 내려야 한다.`,
  o:[
    { l:'① 삽을 받아 쥐고 석탄을 화실 밖으로 퍼낸다.', k:'steady', dc:22,
      ok:`삽을 받았다. 화부가 비켜섰다. 석탄을 펐다. 화실 쪽이 아니라 바닥 쪽으로.<br><br>열기가 얼굴을 친다. 살갗을 굳혔다. 불 앞에서 몸이 버틴다. 퍼낸 석탄이 바닥에 쌓인다. 불이 조금 약해졌다.<br>화부가 이쪽을 봤다. 화상 자국 손이 떨린다. 그가 처음으로 웃었다. 그것도 괜찮다고. 그러고는 다른 삽을 들어 같이 퍼냈다. 그도 내리고 싶었던 사람이다.`,
      ng:`퍼내는데 화부가 이쪽 손목을 잡았다. 화상 자국 손이 뜨겁다. 불보다.<br><br>화부가 삽을 화실 쪽으로 돌려 놓는다. 힘이 세다. 일하는 손이다.<br>삽이 화실로 들어갔다. 불이 더 하얘졌다. 열차가 빨라졌다. 손목에 화부 손가락 자국이 벌겋게 데었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 내공을 써서 화실 열을 견디며 화실 문을 닫는다.', k:'break', dc:22, cost:{ qi:24 },
      ok:`화부 옆으로 들어가 화실 문 손잡이를 잡았다. 쇠가 달아올랐다. 손바닥에 내공을 모아 굳혔다.<br><br>문을 밀었다. 하얀 불이 문틈에서 혀를 내민다. 끝까지 밀었다. 닫혔다. 빗장을 걸었다.<br>열기가 줄었다. 화부가 삽을 든 채 멍하니 섰다. 손바닥에 손잡이 무늬가 하얗게 찍혔다. 굳힌 데라 데지는 않았다. 무늬만 남았다.`,
      ng:`밀었는데 내공이 모자라 손바닥이 먼저 데었다. 손을 뗐다.<br><br>다시 잡았다. 데인 데를 또 데었다. 문이 반만 닫혔다.<br>화부가 문을 도로 열었다. 화실 열기가 덮쳤다. 뒤로 물러섰다. 손바닥 살갗이 손잡이에 조금 남았다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, spirit:-12, qi:-6 } },
    { l:'③ 화부의 손등 화상을 본다.', k:'gaze', dc:21,
      ok:`화부 손등을 봤다. 화상 자국이 겹겹이다. 가장 새것이 가장 위에 있어야 한다. 가장 오래된 것이 위에 있다.<br><br>이 사람은 이 열차에서 오래 일했다. 오래전에 마지막 화상을 입었다. 그 뒤로는 데지 않았다. 데지 않는 손이 삽질을 한다.<br>삽을 받지 않았다. 일행을 데리고 화부 등 뒤를 지났다. 화부는 돌아보지 않았다. 삽질만 했다. 오래전부터 그렇게.`,
      ng:`보는데 화부가 손을 거뒀다. 장갑을 꼈다. 이쪽이 본 걸 안다.<br><br>삽을 이쪽으로 내밀었다. 받으라고. 받지 않자 삽 끝이 이쪽 가슴에 닿았다. 달군 쇠다.<br>뒤로 물러섰다. 외투에 삽 모양이 탔다. 가슴 살갗이 그 모양대로 벌겋다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B', t:'배신 — 등 뒤의 숨',
  x:`일행 하나가 이쪽 등 뒤에 붙어 걷는다. 오는 길에 구한 사람이다. 고맙다고 했다.<br><br>
    단련한 살갗은 맞는 것을 받는다. 맞기 전에 맞을 것을 느끼기도 한다. 바람이 바뀌는 것, 열이 다가오는 것.<br>
    등 뒤 사람의 숨이 아까부터 조금씩 느려진다. 걸음은 그대로인데.<br><br>
    숨이 느려지는 것은 무언가를 하기 직전이다. 무엇이든.`,
  o:[
    { l:'① 등 살갗에 숨을 모아 무엇이 오는지 기다린다.', k:'steady', dc:22, wake:1,
      ok:`돌아보지 않았다. 숨을 등으로 보냈다. 굳히지 않고 열어 두었다. 살갗이 귀가 됐다.<br><br>등 뒤 사람의 숨이 멎었다. 그 순간 등 살갗에 찬 바람 한 줄이 그어졌다. 쇠가 공기를 가르는 바람이다. 오른쪽 아래, 콩팥 자리.<br>거기만 굳혔다. 칼끝이 닿았다. 들어오지 않았다. 돌아서며 그 손목을 잡았다.<br><br>살갗은 막는 데라고만 알았다. 굳히기 전에 열어 두면 먼저 안다. 맞기 한 숨 전의 바람을 살갗이 읽는다. 등 뒤가 이제 비어 있지 않다.`,
      ng:`기다렸는데 바람을 못 읽었다. 칼이 먼저 왔다.<br><br>옆구리에 들어왔다. 얕다. 등이 반쯤은 굳어 있었다.<br>돌아서 그 사람을 밀쳤다. 그 사람이 빗속으로 뛰었다. 옆구리를 눌렀다. 손가락 사이로 따뜻한 것이 샌다. 단련한 살도 칼은 다 못 받는다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-34, spirit:-14 } },
    { l:'② 걸음을 멈추고 그 사람을 앞세운다.', k:'gaze', dc:21,
      ok:`멈춰 섰다. 길이 좁으니 앞서 가라고 했다.<br><br>그 사람이 머뭇거렸다. 숨이 다시 빨라졌다. 하려던 것을 접는 숨이다. 앞으로 나갔다.<br>그 뒤로 내내 그 사람 등을 보며 걸었다. 그 사람 손이 외투 안에서 한 번도 나오지 않았다. 갈림길에서 그 사람은 다른 길로 갔다. 인사도 없이.`,
      ng:`앞세웠는데 그 사람이 순순히 앞섰다. 숨이 고르다. 이쪽이 잘못 본 건가.<br><br>그때 등 뒤에서 숨이 느려지는 소리가 났다. 다른 사람이다. 일행 중 하나.<br>돌아봤다. 일행이 놀란 얼굴로 이쪽을 본다. 무엇이 느려졌는지 모르겠다. 그 뒤로 등 뒤의 숨소리를 다 세느라 지쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'③ 돌아서서 먼저 그 사람의 손목을 친다.', k:'break', dc:22,
      ok:`홱 돌아서며 그 사람 오른 손목을 손날로 쳤다. 외투 안에 들어 있던 손이다.<br><br>무언가 젖은 바닥에 떨어졌다. 짧은 칼이다. 그 사람이 손목을 쥐고 뒷걸음질 쳤다.<br>칼을 발로 밟았다. 그 사람은 비를 맞으며 서 있다가 갔다. 고맙다는 말을 했던 입이 끝까지 다물려 있었다.`,
      ng:`돌아서 쳤는데 그 사람 손에 아무것도 없었다. 빈손이다.<br><br>그 사람이 손목을 쥐고 이쪽을 봤다. 아파서 우는 얼굴이다. 일행이 이쪽을 본다.<br>사과했다. 그 사람은 받지 않았다. 다음 모퉁이에서 사라졌다. 사라진 자리 물웅덩이에 칼 하나가 잠겨 있었다. 언제 버렸는지 모른다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'B', t:'시계 — 꺾이는 철계단',
  x:`철계단이 벽에서 떨어지고 있다. 볼트가 하나씩 튕겨 나간다.<br><br>
    일행이 계단 위에 있다. 아래로 내려와야 한다. 계단이 다 떨어지기 전에.<br>
    계단 중간 받침대가 기울었다. 받침대 하나가 계단 반을 받친다.<br><br>
    남은 볼트는 넷. 하나가 빠질 때마다 숨 다섯.`,
  o:[
    { l:'① 내공을 써서 받침대 밑에 어깨를 넣고 버틴다.', k:'steady', dc:22, cost:{ qi:28 },
      ok:`받침대 밑으로 들어가 어깨를 댔다. 숨을 어깨와 허리와 무릎으로 나눠 굳혔다.<br><br>계단 무게가 내려앉았다. 볼트 하나가 빠졌다. 무게가 늘었다. 무릎이 내려간다. 반 치. 거기서 섰다.<br>일행이 머리 위를 지나 내려왔다. 다섯. 다 내려온 뒤 어깨를 뺐다. 계단이 벽에서 떨어져 그 자리에 쏟아졌다. 어깨에 받침대 모양 멍이 하나 늘었다. 받은 멍이다.`,
      ng:`어깨를 넣었는데 볼트 둘이 한꺼번에 빠졌다. 무게가 두 배가 됐다.<br><br>무릎이 꺾였다. 한쪽 무릎이 바닥을 찍었다. 그래도 어깨는 안 뺐다.<br>일행이 뛰어 내려왔다. 마지막 사람이 지나자 쓰러지듯 빠졌다. 계단이 떨어지며 발목을 스쳤다. 무릎에서 물 차는 소리가 났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-34, mind:-12, qi:-6 } },
    { l:'② 계단 밑에서 떨어지는 일행을 받는다.', k:'bond', dc:21,
      ok:`버틸 수 없다고 봤다. 계단 밑에 서서 소리쳤다. 뛰어내리라고.<br><br>하나씩 떨어졌다. 받았다. 몸을 풀었다가 닿는 순간 굳혔다. 다섯 번.<br>마지막 사람을 받고 비켜서자 계단이 떨어졌다. 다섯이 다 바닥에 앉아 숨을 쉰다. 이쪽 팔이 저렸다. 저린 것 말고는 다 괜찮았다.`,
      ng:`받는데 셋째가 받기 전에 떨어졌다. 계단이 기울어 미끄러지듯.<br><br>그 사람이 바닥에 먼저 닿았다. 발목이 꺾였다. 소리를 질렀다.<br>넷째와 다섯째를 받고 셋째를 업었다. 계단이 떨어지는 소리에 귀가 멍했다. 업은 사람의 숨이 목에 뜨겁다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-14 } }
  ] },

{ at:'B', t:'문 — 주먹 앞의 쇠문',
  x:`쇠문이 잠겼다. 자물쇠는 바깥에 있다. 안쪽은 매끈한 철판이다.<br><br>
    몸을 단련하는 사람은 단단한 것을 보면 친다. 버릇이다.<br>
    치면 둘 중 하나가 깨진다. 철판이거나 주먹이거나. 오늘은 철판이 두껍다.<br><br>
    등 뒤 복도 끝에서 손전등이 켜졌다. 문 앞까지 백 걸음.`,
  o:[
    { l:'① 문 한가운데를 주먹으로 계속 친다.', k:'break', dc:22,
      ok:`문 한가운데를 쳤다. 철판이 운다. 다시. 같은 자리. 열 번째에 철판이 움푹 들어갔다.<br><br>스무 번째에 문짝이 문틀에서 휘었다. 자물쇠 혀가 문틀 구멍에서 반쯤 빠졌다. 어깨로 밀었다. 열렸다.<br>손전등이 서른 걸음 뒤였다. 주먹 마디가 하얗다. 피는 안 났다. 문 한가운데에 주먹 자국 하나. 스무 번이 한 자리에 들어갔다.`,
      ng:`쳤는데 철판이 너무 두껍다. 울리기만 한다.<br><br>스무 번째에 주먹 마디가 터졌다. 피가 철판에 찍혔다. 손전등이 오십 걸음 뒤다.<br>멈추고 다른 손으로 쳤다. 열 번. 그 손도 터졌다. 문은 그대로다. 결국 일행이 찾은 환기구로 기어 나갔다. 두 손이 다 안 쥐어졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 경첩 쪽 문틀을 어깨로 받는다.', k:'steady', dc:21,
      ok:`문짝이 두꺼우면 문틀을 친다. 경첩이 박힌 벽. 시멘트다. 철판보다 무르다.<br><br>어깨를 굳혀 경첩 쪽 문틀에 부딪혔다. 시멘트 가루가 떨어진다. 둘째, 셋째. 경첩 하나가 벽째 들렸다.<br>문짝이 비뚤어졌다. 틈으로 몸을 비틀어 빠졌다. 일행도. 어깨에서 시멘트 가루가 털어도 털어도 나왔다.`,
      ng:`부딪혔는데 문틀 안에 쇠가 박혀 있다. 시멘트 밑에 철근.<br><br>어깨가 철근에 맞았다. 어깨가 빠졌다. 혼자 넣었다. 소리를 삼켰다.<br>다시 부딪힐 어깨가 없다. 일행이 환기구를 찾아 끌고 갔다. 빠졌다 들어간 어깨가 밤새 욱신거렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 문 밑 틈으로 손을 넣어 바깥 자물쇠를 더듬는다.', k:'fix', dc:21,
      ok:`문 밑에 손가락 두 마디 틈이 있다. 손을 펴서 넣었다. 손등이 긁힌다. 손목까지 들어갔다.<br><br>바깥쪽으로 손을 꺾어 위로 올렸다. 손가락이 자물쇠 바닥에 닿았다. 빗장식이다. 손끝으로 밀었다. 단련한 손끝이다.<br>빗장이 빠졌다. 손을 빼자 손등이 붉게 쓸려 있었다. 문이 열렸다. 손전등은 아직 칠십 걸음 뒤였다.`,
      ng:`손을 넣었는데 바깥에서 무언가 손을 밟았다. 장화다.<br><br>손가락이 바닥에 눌린다. 장화가 비빈다. 천천히.<br>손을 뺐다. 손가락 둘이 부었다. 장화는 문 앞에서 비켜서지 않았다. 손전등이 그쪽으로 모였다. 다른 길로 뛰었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B', t:'새벽 전 — 무거운 눈꺼풀',
  x:`밤새 맞았다. 밤새 버텼다. 이제 몸이 아니라 눈꺼풀이 무겁다.<br><br>
    마지막 문까지 남았다. 남은 길은 짧다. 짧은 길에서 잠드는 사람이 제일 많다.<br>
    몸을 단련하는 사람은 몸을 쓴다. 졸음은 몸이 아니다. 숨이다.<br><br>
    일행이 이쪽을 본다. 이쪽 걸음이 느려지면 다들 느려진다.`,
  o:[
    { l:'① 숨을 세 번에 나눠 쉬어 머리를 깨운다.', k:'steady', dc:21, wake:1,
      ok:`들이쉬기를 셋으로 나눴다. 짧게, 짧게, 길게. 내쉬기는 한 번에 길게.<br><br>세 번째 들숨이 정수리까지 올라간다. 머리가 차가워진다. 눈꺼풀이 가볍다. 몇 번 반복했다. 걸음이 돌아왔다.<br>일행에게도 가르쳐 줬다. 짧게, 짧게, 길게. 다들 따라 했다. 새벽 복도에서 다섯 사람 숨이 한 박자로 들렸다.<br><br>숨은 버티는 데 쓰는 것인 줄 알았다. 깨우는 데도 쓴다. 숨을 어디로 보내느냐에 따라 몸이 달라진다. 오늘 숨 하나가 더 늘었다.`,
      ng:`나눠 쉬는데 셋째 숨에서 하품이 나왔다. 숨이 하품을 따라 다 빠졌다.<br><br>눈꺼풀이 내려왔다. 서 있는 채로 잠깐 잠들었다. 무릎이 꺾여 깼다.<br>일행이 붙잡았다. 다시 걸었다. 걷는 동안 두 번 더 무릎이 꺾였다. 마지막 문까지 남의 어깨를 빌렸다.`,
      win:{ exp:22, dream:2, mind:8 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 허벅지를 꼬집으며 걷는다.', k:'break', dc:20,
      ok:`허벅지 안쪽을 꼬집었다. 단련 안 한 데다. 아프다. 아픈 게 깨운다.<br><br>열 걸음마다 한 번. 허벅지 안쪽이 멍투성이가 됐다. 대신 눈은 떠 있었다.<br>마지막 문에 닿았다. 문을 밀며 생각했다. 이 멍은 받은 멍이 아니다. 준 멍이다.`,
      ng:`꼬집었는데 아픈 줄을 모르겠다. 몸이 너무 지쳐서 아픔도 졸았다.<br><br>세게 꼬집었다. 살갗이 찢어졌다. 그래도 졸렸다.<br>문 앞에서 벽에 이마를 박았다. 그게 깨웠다. 이마에 혹이 섰다. 문은 열렸다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-22, mind:-12 } }
  ] }

]);

// ------------------------------------------
// 광부 · 자원 없음
// ------------------------------------------
kJob('miner', 'B', [

{ at:'B', t:'빗속 — 발밑의 빈 소리',
  x:`골목 바닥이 발밑에서 울린다. 텅, 텅. 비가 시멘트를 두드리는 소리 밑에 다른 소리가 있다.<br><br>
    땅 밑에서 일하던 사람은 이 소리를 안다. 밑이 비었다. 지하실이거나 배수관이거나 옛 굴이다.<br>
    앞뒤 골목 끝에서 손전등이 다가온다. 위로는 갈 데가 없다.<br><br>
    아래는 아무도 안 본다. 쫓는 사람도, 쫓기는 사람도.`,
  o:[
    { l:'① 엎드려 젖은 바닥에 귀를 댄다.', k:'sense', dc:20, wake:1,
      ok:`엎드려 귀를 댔다. 빗물이 귓바퀴로 흘러든다. 그 소리 너머로 물 흐르는 소리가 들린다. 땅 밑에서.<br><br>빗물이 모여서 간다. 한쪽으로. 그쪽 끝에서 소리가 커진다. 큰 관이다. 관은 어딘가로 나간다.<br>소리가 제일 큰 데까지 기어갔다. 쇠 격자 뚜껑이 있다. 들어 올렸다. 다 내려갔다. 손전등이 그 위를 지나갔다.<br><br>땅 밑 소리는 굴에서만 듣는 줄 알았다. 도시 밑에도 굴이 있다. 비가 오면 그 굴이 운다. 빗소리 밑의 소리가 이제 길로 들린다.`,
      ng:`귀를 댔는데 빗소리밖에 안 들린다. 비가 너무 세다.<br><br>오래 엎드려 있었다. 손전등이 골목 어귀에서 이쪽 등을 비췄다.<br>일어나 뛰었다. 바닥에 엎드렸던 자리만 젖지 않은 사람 모양이 남았다. 그 모양을 보고 손전등이 따라왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 곡괭이로 소리가 빈 데를 깬다.', k:'break', dc:21,
      ok:`텅 빈 소리가 제일 큰 데를 골라 곡괭이로 찍었다. 두 번. 시멘트가 얇다. 밑에 판자가 있다.<br><br>판자가 썩었다. 세 번째에 구멍이 났다. 밑이 까맣다. 물 냄새.<br>다 내려가고 구멍 위에 젖은 상자 하나를 끌어 덮었다. 손전등 빛이 상자 위를 핥고 지나갔다.`,
      ng:`찍었는데 소리가 골목을 울렸다. 곡괭이는 조용한 연장이 아니다.<br><br>손전등이 빨라졌다. 구멍은 반만 뚫렸다. 몸이 안 들어간다.<br>곡괭이를 뽑아 뛰었다. 반쯤 뚫린 구멍에 발 하나가 빠질 뻔했다. 쫓는 쪽 발이었다. 그 덕에 한 모퉁이를 벌었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 소금 자루 팔레트',
  x:`쪽문 앞을 팔레트가 막았다. 소금 자루가 사람 키만큼 쌓였다. 자루 하나가 쌀 한 가마 무게다.<br><br>
    옆에 지게차가 열쇠를 꽂은 채 서 있다. 열쇠고리 표에 적혔다. 시동 걸지 말 것 — 소리 남.<br>
    자루를 위에서부터 내리면 밤이 다 간다. 아래에서 빼면 위가 무너진다.<br><br>
    땅 밑에서 일하던 사람은 쌓인 것을 무너뜨리지 않고 빼내는 법을 안다. 기둥을 남기고 캐는 법이다.`,
  o:[
    { l:'① 무게가 안 실린 자루만 골라 아래에서 뺀다.', k:'steady', dc:21, wake:1,
      ok:`자루 더미를 봤다. 위 자루들의 무게가 어디로 내려가는지. 비스듬히 쌓인 자루 사이로 무게가 가는 길이 있다.<br><br>그 길에서 비켜난 자루만 골랐다. 아래 칸 하나, 그 옆 하나. 손으로 쥐어 보면 안다. 눌린 자루는 단단하고 안 눌린 자루는 무르다.<br>무른 것 셋을 빼냈다. 더미가 그대로 섰다. 가운데에 사람 하나 지나갈 굴이 났다. 쪽문이 그 끝에 있다.<br><br>쌓인 것은 다 무게의 길을 갖고 있다. 돌이든 자루든. 그 길을 손이 짚는다. 무너뜨리지 않고 뚫는 데가 이제 보인다.`,
      ng:`골라 뺐는데 하나를 잘못 짚었다. 단단한 놈이었다.<br><br>더미가 끙 하고 기울었다. 위 자루 둘이 미끄러져 내려와 어깨를 쳤다. 쌀 두 가마 무게다.<br>깔리지는 않았다. 어깨가 내려앉았다. 자루 하나가 터져 소금이 쏟아졌다. 쏟아지는 소리가 비 소리보다 컸다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 지게차에 시동을 걸어 팔레트째 든다.', k:'luck', dc:22,
      ok:`운전석에 앉았다. 축축하다. 열쇠를 돌렸다. 엔진이 걸렸다. 생각보다 조용하다. 비가 양철 지붕을 덮었다.<br><br>날을 팔레트에 넣고 들었다. 소금 더미가 통째로 뜬다. 옆으로 옮겼다. 쪽문이 드러났다.<br>엔진을 껐다. 창고 안쪽 어둠에서 대걸레 소리가 멈춰 있었다. 시동 걸 때 멈췄다. 다시 시작되지 않는다.`,
      ng:`돌렸는데 엔진이 기침을 했다. 크게. 세 번.<br><br>세 번째에 걸렸다. 창고 안쪽에서 대걸레 소리가 멈췄다. 그리고 장화 소리가 시작됐다. 이쪽으로.<br>팔레트를 반만 들었다. 반만 비켜 났다. 비집고 쪽문을 빠졌다. 소금 자루 모서리에 정강이가 쓸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'③ 자루 하나를 찢어 소금을 흘려 더미를 낮춘다.', k:'fix', dc:20,
      ok:`맨 위 자루 귀퉁이를 칼로 찢었다. 굵은 소금이 쏟아져 내린다. 쉬지 않고.<br><br>자루가 비면 가볍다. 셋을 그렇게 비웠다. 빈 자루는 손으로 끌어내렸다. 더미가 어깨 높이로 낮아졌다. 넘을 수 있다.<br>쏟아진 소금 더미에서 덩이 진 것을 하나 챙겼다. 짠 것은 오래간다.`,
      ng:`찢었는데 소금이 쏟아지는 소리가 쇳소리 같다. 양철 바닥을 친다.<br><br>소리를 막으려고 외투를 깔았다. 외투가 소금에 묻혔다.<br>더미는 낮아졌다. 넘어갔다. 외투는 소금 밑이다. 젖은 셔츠 바람으로 빗속으로 나갔다.`,
      win:{ exp:15, item:'소금 덩이' }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B2', t:'기록 보관실 — 환기 덕트',
  x:`보관실 끝 벽에 환기구가 있다. 철망이 나사 넷으로 박혔는데 하나는 빠졌다.<br><br>
    덕트 안에서 바람이 올라온다. 따뜻하고 축축하다. 세제 냄새가 섞였다. 아래로 꺾인다.<br>
    사람 하나가 엎드려 들어갈 너비다. 조금 모자란다.<br><br>
    안쪽 벽에 손톱으로 그은 금이 있다. 다섯 개씩 묶어서. 아래로 갈수록 성기다.`,
  o:[
    { l:'① 숨을 내쉬고 어깨를 비틀어 덕트로 기어 내려간다.', k:'steady', dc:21,
      doom:{ title:'환기 덕트', what:'덕트 아래로 끌려 내려갑니다', dc:17, sec:55,
        text:`철망을 떼고 머리부터 들어갔다. 숨을 내쉬고 어깨를 비스듬히. 굴은 늘 이렇게 들어갔다.<br><br>기었다. 꺾이는 데서 덕트가 한 치 좁아졌다. 어깨가 걸렸다. 숨을 더 내쉬었다. 안 빠진다.<br>뒤로 물러서려는데 발목을 무언가 잡았다. 아래쪽에서. 머리 쪽이 아래인데, 발목을 잡은 것도 아래쪽에서.<br><br>당긴다. 덕트 아래로. 어깨가 쇠벽을 긁으며 끌려간다. 손톱이 쇠를 긁는다. 다섯 개씩 묶어서.`,
        dieText:`굴은 늘 이렇게 들어갔다. 굴에서 사람을 잡아당기는 것은 없었다.<br><br>덕트 안쪽 벽의 금이 한 묶음 늘었다. 맨 아래 성긴 데에.<br>3층 세탁실 배기구에서 한동안 바람이 안 나왔다. 그다음엔 다시 나왔다. 세제 냄새가 섞였다.` },
      ok:`숨을 내쉬고 어깨를 비틀어 들어갔다. 꺾이는 데서 어깨가 걸렸다.<br><br>무리하지 않았다. 한 팔을 앞으로 뻗고 다른 팔은 몸에 붙였다. 굴에서 좁은 데를 지날 때 하는 자세다. 어깨 하나만 남으면 빠진다.<br>빠졌다. 발목에 무언가 스쳤다. 잡지는 않았다. 3층 세탁실 천장 점검구로 내려섰다. 덕트 안 금 맨 아래에 손톱으로 하나를 더 그었다. 가로로.`,
      win:{ exp:25, dream:3 } },
    { l:'② 덕트 대신 레일 서가 뒤 벽을 두드려 본다.', k:'sense', dc:21,
      ok:`덕트는 좁다. 좁은 굴은 마지막에 쓴다. 벽을 먼저 두드렸다. 곡괭이 머리로 한 뼘씩.<br><br>서가 뒤 벽 한 군데에서 텅 소리가 났다. 석고판이다. 뒤에 배관 통로가 있다.<br>석고판을 곡괭이로 긁어 구멍을 냈다. 사람 하나 서서 지나간다. 배관을 따라 내려가는 쇠사다리가 있었다.`,
      ng:`두드리는데 서가 레일이 움직였다. 이쪽 두드리는 소리에 맞춰. 끼릭.<br><br>서가가 벽 쪽으로 다가온다. 벽과 서가 사이가 좁아진다. 거기 이쪽이 있다.<br>덕트로 몸을 던졌다. 반쯤 들어갔을 때 서가가 벽에 붙었다. 발이 서가에 눌렸다. 신발을 버리고 발만 뺐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B3', t:'5호차 — 터널의 길이',
  x:`열차가 터널로 들어갔다. 창밖이 까매졌다. 객차 불이 깜빡이다 나갔다.<br><br>
    완전한 어둠이다. 바퀴 소리가 터널 벽에 부딪혀 두 배로 커진다.<br>
    이 열차에는 얼굴을 바꾸는 것이 탔다. 불이 꺼지면 얼굴은 안 보인다. 그것에게는 좋은 때다.<br><br>
    땅 밑에서 일하던 사람에게 어둠은 낯설지 않다. 굴 안은 늘 이랬다.`,
  o:[
    { l:'① 터널 벽 울림으로 남은 길이를 잰다.', k:'sense', dc:21, wake:1,
      ok:`눈을 감았다. 귀만 열었다. 바퀴 소리가 벽에 맞고 돌아온다. 돌아오는 소리 끝에 다른 소리가 섞인다. 터널 출구의 바람이다.<br><br>멀다. 아직 멀다. 점점 가깝다. 소리가 얇아지는 걸로 안다. 일행 손을 잡고 말했다. 숨 서른 번. 그때 불이 들어온다.<br>숨 스물여섯에 바람 소리가 커졌다. 서른에 터널을 빠졌다. 불이 들어왔을 때 일행 다섯이 손을 잡은 채 그대로 있었다. 통로 저편에 서 있던 얼굴 하나가 방금 돌아선 참이었다.<br><br>굴 길이는 걸어서 재는 줄 알았다. 소리로도 잰다. 어둠이 얼마나 남았는지 귀가 먼저 안다.`,
      ng:`귀를 열었는데 터널 소리가 이상하다. 끝이 안 들린다. 계속 같은 소리다.<br><br>숨 서른이 지나고 마흔이 지났다. 불이 안 들어온다. 터널이 안 끝난다.<br>어둠 속에서 누가 이쪽 손을 잡았다. 일행인 줄 알았다. 손이 너무 차다. 놓았다. 불이 들어왔을 때 손을 잡았던 쪽에 아무도 없었다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 어둠에 눈을 익히고 그대로 버틴다.', k:'steady', dc:20,
      ok:`눈을 뜬 채로 어둠을 봤다. 아무것도 없다. 그래도 봤다. 굴에서는 늘 그랬다.<br><br>한참 지나니 어둠에 결이 생긴다. 창은 조금 덜 까맣다. 통로는 더 까맣다. 그 통로에 무언가 서 있다. 사람 모양으로 조금 더 까맣게.<br>움직이지 않았다. 그것도 안 움직였다. 터널을 빠지자 그것은 없었다. 그것도 어둠에 눈이 익은 이쪽을 봤을 것이다.`,
      ng:`익히려는데 눈이 자꾸 무언가를 만든다. 없는 것을. 굴에서도 그랬다. 굴에서는 알았다.<br><br>여기서는 모르겠다. 만든 것인지 있는 것인지.<br>통로의 까만 것이 다가오는 것 같다. 뒤로 물러섰다. 좌석 팔걸이에 허리를 찧었다. 불이 들어왔다. 아무것도 없다. 허리가 아프다. 그것만 진짜였다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'쫓기는 길 — 불 없이',
  x:`손전등이 깨졌다. 성냥은 셋 남았다. 쫓는 쪽은 불빛을 따라온다.<br><br>
    불을 켜면 길이 보이고 이쪽도 보인다. 불을 끄면 둘 다 안 보인다.<br>
    지하 통로가 길다. 벽은 젖은 벽돌. 바닥에 물이 발목까지.<br><br>
    굴 안에서 등불이 꺼진 적이 여러 번 있다. 그때마다 나왔다. 손으로 나왔다.`,
  o:[
    { l:'① 손바닥을 벽에 대고 걸음을 세며 이끈다.', k:'steady', dc:21, wake:1,
      ok:`오른손을 벽에 댔다. 왼손은 뒷사람 손에. 뒷사람 손은 그 뒷사람에게. 줄이 됐다.<br><br>걸음을 셌다. 소리 없이 입속으로. 손바닥이 벽돌 줄눈을 하나씩 넘는다. 줄눈이 끊기면 모퉁이다. 바람이 손등에 닿으면 갈림길이다. 물이 발목에서 정강이로 오르면 내리막이다.<br>삼백 걸음. 손바닥이 철문 하나를 찾았다. 밀었다. 비 냄새가 들어왔다.<br><br>눈이 쉬는 동안 손바닥과 발과 피부가 길을 봤다. 불 없는 길이 이제 무섭지 않다. 이 길의 모양이 손바닥에 남았다.`,
      ng:`대고 걸었는데 백 걸음째에 벽이 끊겼다. 손바닥이 허공을 짚었다.<br><br>넘어졌다. 물에. 뒷사람 손을 놓쳤다. 어둠 속에서 이름을 불렀다. 대답이 셋. 하나가 모자란다.<br>한참 더듬어 찾았다. 그 사람은 반대쪽 벽에 붙어 떨고 있었다. 다시 줄을 섰다. 그사이 멀리서 불빛이 하나 켜졌다. 쫓는 쪽의 것이다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 성냥 하나로 길을 한 번 보고 외운다.', k:'luck', dc:21,
      ok:`성냥 하나를 긁었다. 불이 한 번 일었다. 다섯 숨 동안 통로를 봤다. 왼쪽 벽 셋째 기둥에서 갈림길, 오른쪽.<br><br>불을 껐다. 외운 대로 걸었다. 셋째 기둥에서 오른쪽.<br>뒤에서 쫓는 쪽 불빛이 갈림길에서 멈췄다. 왼쪽으로 갔다. 다섯 숨이 한 시간을 벌었다.`,
      ng:`긁었는데 성냥이 젖었다. 두 번째도. 세 번째에 불이 붙었다.<br><br>불빛이 통로를 비췄다. 갈림길이 보였다. 그리고 통로 저편의 얼굴들도 보였다. 저쪽도 이쪽을 봤다.<br>불을 끄고 뛰었다. 외운 길이 반만 맞았다. 벽에 이마를 찧었다. 쫓는 쪽은 성냥 냄새를 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 꺼진 불',
  x:`불이 나갔다. 한꺼번에. 냉각기 돌던 소리도 멎는다. 완전한 어둠이다.<br><br>
    얼음 녹는 소리만 똑, 똑. 어둠 저편에서 고무장화가 운다. 뽀득.<br>
    낮은 목소리가 센다. 하나. 한참 있다가. 둘.<br><br>
    한 사람씩 짚어 오는 소리다. 짚을 사람은 어둠 속에서도 안다. 어디 서 있는지.`,
  o:[
    { l:'① 어둠 속에서 매달린 고기 사이로 길을 더듬는다.', k:'steady', dc:21,
      ok:`굴에서 등불이 꺼지면 먼저 움직이지 않는다. 숨을 고른다. 그다음 손을 뻗는다.<br><br>손에 언 고기가 닿았다. 고기 줄은 레일을 따라 매달렸다. 레일은 문 쪽으로 이어진다. 고기를 하나씩 짚으며 갔다.<br>셋. 넷. 세는 소리가 이쪽이 있던 자리에 닿았다. 비어 있다. 이쪽은 고기 줄 끝 문 옆에 있다. 일행을 손으로 하나씩 당겨 모았다.`,
      ng:`더듬는데 고기가 아니라 사람 어깨가 손에 닿았다. 차다. 언 것처럼.<br><br>일행인 줄 알았다. 이름을 불렀다. 어깨가 대답하지 않는다.<br>세는 소리가 바로 귀 옆에서 났다. 다섯. 뒷걸음질 쳤다. 고기 줄에 등이 부딪혀 레일이 울었다. 그 소리를 따라 장화가 왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 생선 상자 더미 뒤에 웅크려 세는 소리를 보낸다.', k:'hide', dc:21,
      ok:`손으로 상자 더미를 찾아 그 뒤에 웅크렸다. 숨을 아주 작게.<br><br>세는 소리가 지나간다. 다섯, 여섯, 일곱. 셀 것이 일행보다 많다. 고기를 세는 걸까. 고기 사이의 무언가를 세는 걸까.<br>소리가 멀어졌다. 불이 다시 들어왔다. 상자 더미 위에 찬 손자국이 하나 찍혀 있었다. 이쪽 머리 바로 위에.`,
      ng:`웅크렸는데 상자가 빈 것이었다. 무릎이 닿자 무너졌다.<br><br>나무 부딪히는 소리. 세는 소리가 멈췄다. 그리고 이어졌다. 하나. 이번엔 가까이서. 이쪽을 처음부터 다시 센다.<br>기어서 반대편으로 갔다. 무릎이 언 바닥에 쓸렸다. 불이 들어올 때까지 세는 소리가 이쪽을 따라 돌았다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B2', t:'기록 보관실 — 서가의 레일',
  x:`서가가 바닥 레일 위에 올라앉았다. 손잡이를 돌리면 옆으로 밀려 붙는다.<br><br>
    레일은 쇠다. 바퀴가 그 위를 굴러간다. 굴 안 광차 레일과 다를 게 없다. 더 깨끗할 뿐.<br>
    일행이 서가 사이 통로로 들어가야 한다. 통로 끝 책상에 오늘 날짜 기록철이 있다.<br><br>
    어디선가 손잡이 도는 소리가 났다. 끼릭. 레일 위에 슬리퍼 한 짝이 반쯤 납작하게 끼어 있다.`,
  o:[
    { l:'① 곡괭이 끝을 레일 이음매에 박아 바퀴를 막는다.', k:'fix', dc:21,
      ok:`광차가 미끄러질 때 하는 일이 있다. 레일 이음매에 쐐기를 박는다. 곡괭이 끝을 서가 바퀴 앞 이음매에 박았다. 발로 밟았다.<br><br>끼릭. 서가가 왔다. 바퀴가 곡괭이에 걸렸다. 멈췄다. 손잡이가 헛도는 소리가 난다.<br>일행이 통로로 들어가 기록철을 들고 나왔다. 곡괭이를 뽑았다. 서가가 덜컹 붙었다. 슬리퍼 옆에 곡괭이 자국이 남았다.`,
      ng:`박았는데 이음매가 아니라 레일 한가운데에 박혔다. 미끄러졌다.<br><br>서가가 왔다. 곡괭이를 밀어내며. 곡괭이 자루가 이쪽 정강이를 쳤다.<br>통로 안 일행이 뛰어나왔다. 마지막 사람 등이 서가에 쓸렸다. 기록철은 못 가져왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 서가 사이에 몸을 넣어 버팀목이 된다.', k:'steady', dc:22,
      ok:`통로 입구에 섰다. 등을 한쪽 서가에, 발을 다른 쪽 서가에. 갱도 버팀목처럼.<br><br>서가가 왔다. 무릎이 접힌다. 버텼다. 서가에 꽂힌 기록철이 이쪽 등 뒤에서 우수수 떨어졌다.<br>일행이 이쪽 다리 밑으로 기어 들어갔다가 기어 나왔다. 기록철을 들고. 마지막에 다리를 뺐다. 서가가 붙으며 바지 자락을 물고 찢었다.`,
      ng:`버텼는데 서가가 생각보다 무겁다. 종이는 쌓이면 돌만큼 무겁다.<br><br>무릎이 꺾였다. 등이 서가 칸에 박혔다. 숨이 반만 쉬어진다.<br>일행이 이쪽 다리를 빼내고 서가를 둘이 밀었다. 겨우 빠졌다. 등에 서가 칸 모서리 자국이 가로로 줄을 섰다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'③ 손잡이 도는 소리를 따라가 손잡이를 찾는다.', k:'sense', dc:21,
      ok:`끼릭 소리가 나는 쪽을 따라갔다. 서가 줄 끝. 손잡이 앞에 흰 가운이 서 있다. 등을 보이고.<br><br>가운 발치 레일에 곡괭이 머리를 걸쳤다. 가운이 돌리는 서가는 곡괭이에 걸려 안 간다.<br>가운이 돌리기를 멈추고 돌아봤다. 얼굴이 없다. 마스크만. 그사이 통로 안 일행이 다 나왔다. 가운은 손잡이를 놓고 걸어갔다. 딸깍.`,
      ng:`따라갔는데 소리가 사방에서 난다. 서가 줄마다 손잡이가 혼자 돈다.<br><br>어느 것이 일행 쪽 서가인지 모르겠다. 하나를 붙잡았다. 다른 것이었다.<br>일행 쪽 서가가 붙는 소리가 났다. 뛰어갔다. 일행이 겨우 빠져나와 있었다. 마지막 사람 손에 피가 났다. 서가 사이에 끼었다 빠졌다고 한다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B3', t:'3호차 — 미끄러지는 등기 금고',
  x:`우편칸 끝에 무쇠 금고가 있다. 바닥에 볼트로 박았는데 볼트가 반쯤 풀렸다.<br><br>
    열차가 휠 때마다 금고가 한 치씩 미끄러진다. 우편칸 문 쪽으로. 문 앞에 일행이 서 있다.<br>
    금고 문틈에 운행 일지 표지가 삐죽 나왔다. 종착역 이름이 적혀 있을 것이다.<br><br>
    무거운 것은 밀어서 옮기는 것이 아니다. 땅 밑에서는 그렇게 배웠다.`,
  o:[
    { l:'① 곡괭이를 지렛대로 걸어 금고를 돌려세운다.', k:'steady', dc:21, wake:1,
      ok:`곡괭이 날을 금고 밑 귀퉁이에 걸었다. 자루 끝에 발을 걸고 체중을 실었다.<br><br>금고가 들리지 않는다. 들리지 않아도 된다. 한 귀퉁이만 들리면 돈다. 귀퉁이가 한 치 들렸다. 열차가 휘는 순간에 맞췄다. 금고가 휘는 쪽으로 반 바퀴 돌았다.<br>돌아선 금고가 벽에 등을 대고 멈췄다. 이제 미끄러지지 않는다. 문 쪽이 아니라 벽 쪽으로 기울었다.<br><br>무게와 싸우지 않았다. 무게가 가려는 쪽을 바꿨다. 곡괭이 한 자루와 열차의 흔들림이 일을 다 했다. 큰 것을 볼 때 이제 무게보다 돌릴 귀퉁이가 먼저 보인다.`,
      ng:`걸었는데 열차가 반대쪽으로 휘었다. 금고가 곡괭이를 깔고 미끄러졌다.<br><br>자루가 튕겨 올라 턱을 쳤다. 이가 흔들린다. 금고는 한 치 더 문 쪽으로.<br>일행이 문에서 비켰다. 금고가 문에 부딪혀 멈췄다. 문이 막혔다. 다른 길을 찾느라 시간이 들었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 풀린 볼트를 곡괭이 머리로 다시 박는다.', k:'fix', dc:21,
      ok:`볼트 머리를 곡괭이 머리로 내리쳤다. 쩡. 반 치 들어갔다. 다음 볼트.<br><br>넷을 다 박았다. 금고가 바닥에 붙었다. 열차가 휘어도 안 움직인다.<br>박는 소리가 컸다. 우편 자루 더미가 소리에 맞춰 부풀었다 꺼졌다. 숨 쉬듯. 다 박고 나니 자루도 조용해졌다.`,
      ng:`박는데 볼트 하나가 부러졌다. 녹이 속까지 슬었다.<br><br>셋만 박혔다. 금고가 부러진 볼트 쪽으로 돈다. 한 치씩.<br>박는 소리에 우편 자루 하나가 굴러 내려와 이쪽 발 앞에 섰다. 섰다. 자루가. 뒷걸음질 쳤다. 다시 보니 쓰러져 있었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, spirit:-16 } },
    { l:'③ 금고 문틈의 운행 일지를 빼낸다.', k:'luck', dc:22,
      ok:`금고가 미끄러지는 틈에 문틈의 표지를 손가락으로 집었다. 당겼다. 일지가 반쯤 나왔다.<br><br>열차가 휘었다. 금고 문틈이 벌어졌다. 일지가 다 빠졌다.<br>펼쳤다. 종착역 칸에 이름이 있다. 연필로 몇 번 지웠다가 다시 쓴 자국. 이쪽 일행 중 한 사람 이름이다. 덮어서 품에 넣었다. 그 사람에게는 말하지 않았다.`,
      ng:`집었는데 금고가 반대로 미끄러지며 문틈이 닫혔다. 손가락이 끼었다.<br><br>뺐다. 손톱 하나가 표지에 붙어 같이 빠졌다. 일지는 금고 안에 남았다.<br>피가 우편 자루에 떨어졌다. 자루가 부풀었다. 꺼질 때 숨소리 같은 것이 났다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'지하실 — 단 냄새의 공기',
  x:`숨어든 지하실이 깊다. 계단을 둘 내려왔다. 위에서 발소리가 지나간다.<br><br>
    공기가 이상하다. 달다. 아주 조금. 성냥불이 길게 늘어진다.<br>
    땅 밑에서 일하던 사람은 이 냄새를 안다. 나쁜 공기다. 냄새가 날 때는 이미 늦은 것이다.<br><br>
    일행은 아무것도 모른다. 숨이 차다고만 한다. 지하실 안쪽에 문이 하나 더 있다.`,
  o:[
    { l:'① 안쪽 문까지 숨을 참고 들어가 본다.', k:'steady', dc:21,
      doom:{ title:'단 냄새의 공기', what:'숨이 막혀 쓰러졌습니다', dc:17, sec:50,
        text:`숨을 크게 들이켜고 참았다. 안쪽 문까지 스무 걸음. 굴에서는 그 정도 참았다.<br><br>문에 닿았다. 잠겼다. 손잡이를 흔들었다. 숨이 모자라다. 흔드는 데 숨을 썼다.<br>숨을 쉬고 말았다. 단 냄새가 머리로 곧장 올라간다.<br><br>다리가 사라졌다. 바닥이 얼굴로 왔다. 바닥 공기가 더 달다. 나쁜 공기는 아래에 고인다. 그걸 알면서 아래에 누웠다.`,
        dieText:`냄새가 날 때는 이미 늦은 것이다. 땅 밑에서 일하던 사람은 그걸 안다.<br><br>알면서 들어갔다. 문 너머가 길일지도 몰라서.<br>지하실 안쪽 문은 아침까지 잠겨 있었다. 문 앞 바닥에 곡괭이 하나가 누워 있다. 성냥 하나가 그 옆에서 꺼져 있다.` },
      ok:`숨을 참고 스무 걸음을 갔다. 문이 잠겼다. 흔들지 않았다. 숨을 쓰지 않으려고.<br><br>곡괭이로 경첩을 한 번에 쳤다. 경첩이 튀었다. 문이 기울었다. 그 너머에서 찬 바람이 들어왔다. 바깥으로 이어지는 배수구다.<br>돌아와 일행을 그 바람 쪽으로 끌었다. 숨은 바람 앞에서 쉬었다. 머리가 깨질 것 같았다. 깨지지는 않았다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 성냥불 색을 보고 공기가 남은 쪽을 찾는다.', k:'gaze', dc:21,
      ok:`성냥을 들고 천천히 돌았다. 불꽃이 길어지는 쪽이 나쁘다. 짧고 노란 쪽이 낫다.<br><br>계단 쪽에서 불꽃이 짧아졌다. 위에서 들어오는 공기다. 위에는 발소리가 있다. 그래도 공기는 위에 있다.<br>일행을 계단 중간에 앉혔다. 발소리와 공기 사이. 발소리가 멀어질 때까지 거기서 숨을 쉬었다.`,
      ng:`돌다가 불꽃이 확 커졌다. 파랗게. 손가락을 데었다.<br><br>성냥을 떨어뜨렸다. 물바닥에 꺼졌다. 다행이다. 꺼지지 않았으면 지하실이 터졌다.<br>더듬어 계단으로 기어갔다. 머리가 깨질 것 같다. 위의 발소리가 지날 때까지 계단에 엎드려 토했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 일행을 당장 높은 데로 올린다.', k:'fix', dc:21,
      ok:`설명하지 않았다. 일어서라고, 계단 위로 가라고, 쌓인 상자 위로 올라가라고 했다.<br><br>나쁜 공기는 무겁다. 아래에 고인다. 머리가 높을수록 오래 산다.<br>다들 상자 위에 서서 천장에 머리를 댔다. 위에 발소리가 있다. 발소리 밑이 공기가 제일 좋다. 발소리가 지나갈 때까지 그렇게 섰다. 아무도 쓰러지지 않았다.`,
      ng:`올라가라고 했는데 한 사람이 못 알아들었다. 앉아서 쉬겠다고 한다. 숨이 차서.<br><br>억지로 일으켰다. 그 사람이 비틀거린다. 벌써 늦었다. 업고 계단을 올랐다.<br>위의 발소리가 아직 있다. 계단 꼭대기 문 바로 앞에서 둘이 숨을 몰아쉬었다. 문 너머로 들리지 않게.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'수로 — 물이 나가는 쪽',
  x:`배수 수로가 방파제 밑을 따라 바다로 나간다. 허리까지 물이 찼다. 밀물이다.<br><br>
    수로 중간을 쇠창살이 막았다. 창살 너머로 바닷바람이 들어온다.<br>
    물때표대로라면 네 시 반이면 천장까지 찬다.<br><br>
    굴 안에서 물이 차오를 때 하는 일이 있다. 물이 어디로 나가는지 본다. 물은 늘 나갈 데를 안다.`,
  o:[
    { l:'① 물 위에 손바닥을 대고 흐름을 읽는다.', k:'sense', dc:21, wake:1,
      ok:`물 위에 손바닥을 눕혔다. 들어오는 물살이 손등을 민다. 그 밑에 다른 물살이 손바닥을 끈다. 반대쪽으로. 옆으로.<br><br>밀물은 위로 들어오고 아래로 나간다. 아래 물살이 끄는 쪽에 무언가 있다. 손바닥을 따라 걸었다. 수로 벽에 반쯤 잠긴 옆 굴. 옛 배수관이다.<br>잠수해 들어갔다. 굴이 위로 꺾인다. 숨이 닿는 데가 있다. 일행을 하나씩 데려왔다.<br><br>물은 한 겹인 줄 알았다. 위와 아래가 다르게 흐른다. 손바닥 하나로 두 겹을 읽었다. 물이 차오르는 데서 이제 나가는 물부터 찾는다.`,
      ng:`손바닥을 댔는데 물살이 사방에서 친다. 파도가 수로까지 들어왔다.<br><br>흐름을 못 읽었다. 물이 가슴까지 올라왔다.<br>창살을 잡고 버텼다. 물이 목에 닿았을 때 창살 위 틈으로 기어올랐다. 외투가 창살에 걸려 찢어졌다. 짠물을 한 모금 마셨다. 목이 탄다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 곡괭이로 창살 밑 바닥 진흙을 판다.', k:'break', dc:21,
      ok:`창살은 바닥에 박혔다. 바닥은 진흙이다. 진흙은 판다.<br><br>물속에서 곡괭이를 휘둘렀다. 물이 무겁다. 짧게, 여러 번. 창살 두 대 밑에 굴이 났다. 몸 하나 들어갈.<br>잠수해 빠졌다. 그물에 걸려 퍼덕이던 붕어 몇 마리도 같이 빠져나갔다. 하나는 손에 걸렸다.`,
      ng:`파는데 판 자리로 진흙이 다시 흘러든다. 물살이 진흙을 메운다.<br><br>판 만큼 메워진다. 물은 가슴까지 왔다.<br>곡괭이를 창살에 걸고 몸을 올려 위쪽 틈으로 빠졌다. 곡괭이는 창살에 걸린 채 남았다. 손을 뻗어 겨우 뽑았다. 손바닥이 녹에 찢겼다.`,
      win:{ exp:18, item:'민물고기' }, lose:{ hp:-28, spirit:-12 } }
  ] },

{ at:'B2', t:'비상계단 — 다시 4층',
  x:`계단을 한 층 내려왔다. 벽에 4. 한 층 더. 4. 또 4. 페인트 번진 모양까지 같다.<br><br>
    난간 사이로 내려다보면 계단이 끝없이 감겨 내려간다. 올려다봐도 똑같다.<br>
    굴 안에서 길을 잃으면 같은 갱도를 돈다. 돌고 있다는 걸 알아야 나온다.<br><br>
    발밑 계단 모서리에 미끄럼 방지 고무가 붙었다. 한 칸만 새것이다.`,
  o:[
    { l:'① 곡괭이 머리로 난간을 두드려 소리가 끝나는 데를 듣는다.', k:'sense', dc:21,
      ok:`쇠 난간을 곡괭이 머리로 한 번 쳤다. 쩡. 소리가 난간을 타고 내려간다. 끝없이 내려가는 소리가 아니다. 어딘가에서 끊긴다.<br><br>세 층 아래쯤에서 끊긴다. 계단이 끝없어 보여도 쇠는 끝이 있다. 거기까지만 진짜다.<br>세 층을 셌다. 거기서 벽을 봤다. 3. 고무가 새것인 칸을 밟지 않고 내려왔다.`,
      ng:`쳤는데 소리가 위아래로 다 끝없이 퍼진다. 끊기는 데가 없다.<br><br>울림이 계속 돈다. 귀에서 안 빠진다. 위에서 누군가 난간을 똑같이 쳤다. 쩡. 대답처럼.<br>그 소리가 내려온다. 한 층씩. 같은 4층을 돌며. 뛰었다. 몇 번을 돌았는지 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 새것인 고무 칸을 곡괭이로 뜯어 밑을 본다.', k:'break', dc:21,
      ok:`새 고무를 곡괭이 끝으로 들췄다. 밑에 시멘트가 아니라 철판이 있다. 점검구 뚜껑이다.<br><br>들어 올렸다. 계단 밑 빈 공간에 사다리가 있다. 아래로 곧게. 숫자가 없는 사다리.<br>내려갔다. 사다리 끝에 문. 문을 여니 3층 세탁실 뒤편이다. 증기가 얼굴을 덮었다. 돌지 않는 데로 나왔다.`,
      ng:`들췄는데 고무 밑이 그냥 시멘트다. 곡괭이가 튕겼다.<br><br>그 칸이 새것인 이유는 다른 데 있었다. 누가 많이 밟은 칸이다. 밟고 빠진 칸이다.<br>고무를 뜯은 자리를 누가 밟았다. 이쪽 뒤에서. 돌아보니 아무도 없다. 계단 위 벽 숫자가 5로 바뀌어 있었다. 올라온 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B3', t:'탄수차 — 무너지는 석탄',
  x:`탄수차 위다. 지붕이 없다. 젖은 석탄이 산처럼 쌓였다. 검게 번들거린다.<br><br>
    땅 밑에서 일하던 사람은 석탄을 안다. 젖은 석탄은 무겁고 미끄럽다. 쌓인 석탄은 바닥부터 무너진다.<br>
    석탄 산 너머로 기관차 굴뚝이 보인다. 넘어가야 한다. 산 가장자리에 난간이 없다. 아래는 다리 밑 검은 강.<br><br>
    석탄 산 밑동에서 작은 덩이들이 굴러 나온다. 하나, 둘. 무너지기 직전의 소리다.`,
  o:[
    { l:'① 석탄 산을 가로질러 곧장 넘는다.', k:'steady', dc:22,
      doom:{ title:'무너지는 석탄', what:'석탄에 묻혔습니다', dc:18, sec:45,
        text:`곧장 올라갔다. 석탄에 무릎을 박으며. 산 꼭대기까지 열 걸음.<br><br>여섯째 걸음에 발밑이 꺼졌다. 밑동부터 무너진다. 아는 대로다. 아는 대로 무너진다.<br>석탄이 무릎까지, 허리까지. 열차가 휜다. 석탄이 그쪽으로 쏠린다. 몸이 같이 쏠린다.<br><br>가슴까지 덮였다. 숨을 쉴 때마다 석탄이 조금씩 더 눌러 온다. 굴 안 무너짐과 같다. 굴 안 무너짐에서는 동료가 팠다.`,
        dieText:`쌓인 석탄은 바닥부터 무너진다. 땅 밑에서 일하던 사람은 그걸 안다.<br><br>탄수차 석탄은 그날 밤 다 화실로 들어갔다. 화부가 삽질을 쉬지 않았다.<br>종착역에서 탄수차 바닥을 쓴 사람이 곡괭이 머리 하나를 주웠다. 자루는 타서 없었다.` },
      ok:`곧장 올라가다 여섯째 걸음에 발밑이 꺼지기 시작했다. 멈추지 않았다. 무너지는 쪽 반대로 몸을 던졌다.<br><br>곡괭이를 석탄 산 꼭대기에 박고 자루를 당겨 몸을 끌어올렸다. 등 뒤로 석탄 산 반쪽이 강으로 쏟아졌다.<br>꼭대기에서 일행에게 손짓했다. 무너진 쪽으로 오라고. 이미 무너진 데는 다시 안 무너진다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 밑동 쪽을 곡괭이로 먼저 허물어 길을 낸다.', k:'fix', dc:21,
      ok:`올라가지 않았다. 산 밑동을 곡괭이로 긁었다. 무너질 데를 먼저 무너뜨린다. 굴 안에서 위험한 천장을 일부러 떨어뜨리듯.<br><br>석탄이 쏟아졌다. 강 쪽으로. 한참 쏟아지다 멈췄다. 산이 낮아졌다. 넘을 만하다.<br>낮아진 데를 넘었다. 이번엔 발밑이 꺼지지 않았다. 무너질 것은 이미 다 무너졌다.`,
      ng:`긁었는데 무너지는 쪽이 생각과 달랐다. 이쪽으로 왔다.<br><br>정강이까지 묻혔다. 곡괭이를 꽂고 버텼다. 석탄이 계속 흘러온다.<br>일행이 손을 잡아 끌어냈다. 장화 한 짝이 석탄 밑에 남았다. 맨발로 젖은 석탄을 넘었다. 발바닥이 검게 갈라졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'배신 — 누가 판 굴',
  x:`같이 쫓기던 사람이 말한다. 저 벽 너머로 굴이 있다고. 자기가 지난번에 팠다고.<br><br>
    벽 밑에 구멍이 있다. 사람 하나 기어들 너비. 흙이 아직 축축하다.<br>
    땅 밑에서 일하던 사람은 굴을 보면 누가 팠는지 안다. 어느 쪽에서 팠는지도.<br><br>
    그 사람이 먼저 들어가라고 한다. 친절하게.`,
  o:[
    { l:'① 굴 벽의 연장 자국을 손끝으로 읽는다.', k:'gaze', dc:21, wake:1,
      ok:`쪼그려 앉아 굴 입구 벽을 손끝으로 쓸었다. 삽 자국이다. 자국 끝이 이쪽을 향해 뭉개졌다.<br><br>삽은 미는 쪽으로 흙을 뭉갠다. 이 굴은 이쪽에서 판 굴이 아니다. 저쪽에서 이쪽으로 팠다. 그 사람 말과 반대다. 그리고 흙이 젖어 있다. 오늘 팠다.<br>그 사람을 봤다. 손톱 밑이 깨끗하다. 판 사람의 손이 아니다. 굴로 들어가지 않고 돌아섰다. 굴 안 어둠에서 숨소리가 났다. 기다리던 숨이다.<br><br>굴은 길인 줄 알았다. 굴은 판 사람의 말을 한다. 연장 자국 하나로 누가 어느 쪽에서 왜 팠는지 읽는다. 땅이 사람보다 정직하다.`,
      ng:`읽는데 자국이 너무 고르다. 사람 손 같지 않다. 무엇으로 팠는지 모르겠다.<br><br>모르는 채로 들어가지 않았다. 그 사람이 등을 밀었다. 반쯤 들어갔다.<br>굴 안에서 무언가 손목을 잡았다. 흙 묻은 손이다. 뿌리치고 기어 나왔다. 그 사람은 이미 없었다. 손목에 흙 손자국이 남았다. 손가락이 여섯이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-18 } },
    { l:'② 그 사람을 먼저 들여보낸다.', k:'bond', dc:21,
      ok:`판 사람이 길을 잘 아니 먼저 가라고 했다. 뒤를 따르겠다고.<br><br>그 사람이 웃었다. 오래. 그리고 굴로 안 들어갔다. 손을 들어 휘파람을 불었다.<br>굴 안에서 무언가 나왔다. 셋. 이쪽은 이미 골목 끝을 돌고 있었다. 그 사람이 웃는 동안 뛰기 시작했다.`,
      ng:`먼저 가라고 했더니 그 사람이 순순히 들어갔다. 기어서 사라졌다.<br><br>이쪽이 의심한 게 부끄러웠다. 따라 들어갔다. 굴이 점점 좁아진다. 앞의 소리가 멎었다.<br>앞에 아무도 없다. 굴이 막혔다. 뒤에서 흙 떨어지는 소리. 입구가 메워진다. 곡괭이로 천장을 찍어 위로 팠다. 손톱이 다 들렸을 때 빗물이 얼굴에 떨어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'③ 굴 입구에 귀를 대고 안의 소리를 듣는다.', k:'sense', dc:21,
      ok:`굴 입구에 귀를 댔다. 흙은 소리를 잘 옮긴다. 안에서 흙 부스러지는 소리. 숨소리. 둘.<br><br>빈 굴이 아니다. 기다리는 굴이다.<br>일어서서 그 사람에게 말했다. 안에 둘 있다고. 그 사람 얼굴이 굳었다. 이쪽 손에 곡괭이가 있다. 그 사람이 먼저 뛰었다. 굴 안 숨소리도 같이 멀어졌다.`,
      ng:`귀를 댔는데 안에서 흙 소리 대신 목소리가 났다. 이쪽 이름이다. 낮게.<br><br>모르는 목소리가 이쪽 이름을 안다.<br>벌떡 일어났다. 그 사람이 이쪽 어깨를 잡았다. 놓으라고 했다. 안 놓는다. 곡괭이 자루로 그 손을 쳤다. 손이 풀렸다. 뛰었다. 굴 안 목소리가 계속 이름을 불렀다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B1', t:'야적장 — 좁아지는 골목',
  x:`컨테이너 골목 양 끝을 노란 비옷들이 막았다. 장대를 바닥에 끌며 온다.<br><br>
    골목 한가운데 컨테이너 사이에 좁은 틈이 있다. 사람 몸이 옆으로 겨우 들어간다.<br>
    틈 저편에서 집게차 엔진이 돈다. 컨테이너를 집어 옮기는 차다. 누가 운전석에 앉았다.<br><br>
    좁은 틈은 굴과 같다. 굴은 무너진다. 컨테이너는 옮겨진다.`,
  o:[
    { l:'① 틈에 몸을 비틀어 넣고 끝까지 지난다.', k:'steady', dc:22,
      doom:{ title:'좁아지는 틈', what:'컨테이너 사이에 끼었습니다', dc:18, sec:50,
        text:`옆으로 서서 틈에 들어갔다. 숨을 내쉬고 가슴을 줄였다. 굴에서 하던 대로.<br><br>반쯤 들어갔을 때 집게차가 컨테이너 하나를 집었다. 쇠가 끌리는 소리. 틈이 좁아진다.<br>앞으로 가려는데 가슴이 걸렸다. 뒤로 가려는데 등이 걸렸다.<br><br>쇠벽이 양쪽에서 한 치씩. 숨을 들이쉴 수가 없다. 내쉰 채로 멈췄다. 빗물이 틈 위에서 얼굴로 떨어진다.`,
        dieText:`좁은 틈은 굴과 같다. 굴은 무너진다. 컨테이너는 옮겨진다.<br><br>새벽에 집게차가 컨테이너 둘을 붙여 놓고 떠났다. 붙은 자리 위로 빗물이 흐른다.<br>그 밑 바닥에 곡괭이 자루 끝이 조금 나와 있다. 버팀목처럼 세로로.` },
      ok:`옆으로 서서 들어갔다. 반쯤 들어갔을 때 집게차가 컨테이너를 집었다. 틈이 좁아진다.<br><br>곡괭이를 세로로 세워 틈에 박았다. 자루가 양쪽 쇠벽 사이에 걸렸다. 버팀목이다. 쇠벽이 자루에서 멈췄다.<br>자루 옆으로 비집고 빠졌다. 일행도. 마지막에 자루를 뽑자 컨테이너가 쾅 붙었다. 굴 버팀목을 뽑을 때와 같은 소리다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 집게차 바퀴 밑 진흙을 곡괭이로 판다.', k:'break', dc:21,
      ok:`틈 저편으로 돌아 집게차 뒤로 갔다. 바퀴가 진흙에 반쯤 묻혔다. 비가 바닥을 무르게 했다.<br><br>바퀴 앞 진흙을 곡괭이로 파냈다. 깊게. 집게차가 컨테이너를 들고 움직이려다 바퀴가 구덩이에 빠졌다. 기울었다. 컨테이너를 내려놓았다.<br>틈이 그대로 남았다. 일행이 틈으로 빠졌다. 운전석의 사람은 내리지 않았다. 와이퍼만 움직였다.`,
      ng:`파는데 집게차가 먼저 움직였다. 바퀴가 이쪽 발 옆을 지났다.<br><br>진흙이 튀어 얼굴을 덮었다. 앞이 안 보인다. 컨테이너가 옮겨지는 쇳소리.<br>얼굴을 닦았을 때 틈은 닫혀 있었다. 일행은 틈 저편이다. 이쪽은 이편이다. 컨테이너 위로 기어올라 넘었다. 손바닥이 녹슨 모서리에 찢겼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-12 } }
  ] },

{ at:'B2', t:'원무과 — 경비원의 뒷문',
  x:`대기실 뒤편 복도에 경비원 오가 서 있다. 우산을 들었다. 젖었다.<br><br>
    이쪽이야. 뒷문. 정문은 당직이 지켜. 여기로 가면 주차장이 나와.<br>
    문 위 팻말 글씨가 테이프로 가려져 있다. 그는 웃는다. 서류를 쥔 엄지 끝이 둥글게 파였다.<br><br>
    문틈으로 바람이 나온다. 바람은 거짓말을 못 한다. 어디서 오는지 냄새로 말한다.`,
  o:[
    { l:'① 문틈 바람에 젖은 손가락을 대고 냄새를 맡는다.', k:'sense', dc:21,
      ok:`손가락에 침을 묻혀 문틈에 댔다. 굴에서 바람 오는 쪽을 찾을 때 하던 일이다.<br><br>바람이 차다. 손가락 바깥쪽이 식는다. 아래에서 올라오는 바람이다. 주차장은 같은 층 바깥에 있다. 바깥바람이면 비 냄새가 나야 한다. 이 바람은 표백제 냄새다. 지하 냄새다.<br>경비원을 봤다. 웃음이 굳었다. 고맙다고 하고 정문 쪽으로 걸었다. 등 뒤에서 그가 우산을 접는 소리가 났다.`,
      ng:`손가락을 댔는데 경비원이 문을 활짝 열었다. 바람이 한꺼번에 나왔다. 냄새를 가려낼 틈이 없다.<br><br>그가 등을 떠민다. 문턱까지 밀렸다. 문 너머가 계단이다. 아래로.<br>문틀을 잡고 버텼다. 그의 엄지가 이쪽 손등을 눌렀다. 파인 데가 손등에 닿는다. 차다. 손을 빼고 굴러 나왔다. 손등에 둥근 자국이 찍혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 테이프를 곡괭이 끝으로 긁어 팻말을 읽는다.', k:'gaze', dc:21,
      ok:`팻말 테이프를 곡괭이 끝으로 긁었다. 경비원이 말리기 전에.<br><br>테이프가 벗겨졌다. 글씨가 나왔다. 영안실.<br>경비원이 웃음을 거뒀다. 우산을 접었다. 접힌 우산 끝이 쇠다. 그가 한 걸음 다가왔다. 곡괭이를 고쳐 쥐었다. 그가 멈췄다. 한참 있다가 돌아서 복도 끝으로 걸어갔다. 딸깍 소리를 내며.`,
      ng:`긁는데 경비원이 곡괭이 자루를 잡았다. 힘이 세다.<br><br>그대로 끈다. 문 쪽으로. 곡괭이를 놓았다. 그가 곡괭이를 들고 문 안으로 들어갔다. 문이 닫혔다.<br>곡괭이가 없다. 손이 허전하다. 한참 문 앞에 서 있었다. 문 안에서 곡괭이로 무언가 파는 소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'기관실 옆 — 선로 전환 표지',
  x:`기관실 옆 좁은 발판이다. 처음으로 앞이 보인다. 선로가 빗속으로 곧게 뻗었다.<br><br>
    저 멀리 신호등이 빨갛다. 그 너머에 갈림길. 한쪽은 종착역 불빛으로, 다른 쪽은 어둠 속 녹슨 지선으로.<br>
    선로 전환 표지는 몸을 내밀어야 보이는 각도에 있다. 광차 레일에도 이런 표지가 있었다.<br><br>
    갱도 레일 갈림길은 표지 모양으로 읽는다. 어느 쪽으로 열렸는지.`,
  o:[
    { l:'① 발판 난간에 다리를 걸고 몸을 내밀어 표지를 읽는다.', k:'gaze', dc:22,
      ok:`난간에 무릎을 걸고 몸을 빗속으로 내밀었다. 바람이 얼굴을 친다. 표지가 보인다.<br><br>화살표가 아니라 판의 기울기로 읽는다. 판이 오른쪽으로 누웠다. 열린 쪽은 지선이다. 종착 불빛 쪽이 아니다.<br>몸을 거둬들이고 기관실 문을 두드렸다. 지선으로 간다고 외쳤다. 문 안 목소리 둘 중 하나가 멎었다. 멎은 쪽이 종착으로 가려던 쪽이다.`,
      ng:`내밀었는데 열차가 굽이를 돌았다. 몸이 바깥으로 쏠렸다.<br><br>무릎이 난간에서 미끄러졌다. 손이 발판 모서리를 잡았다. 몸 반이 허공이다. 침목이 발밑으로 날아간다.<br>기어올랐다. 표지는 못 읽었다. 손가락 둘이 발판 모서리에 짓이겨졌다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-14 } },
    { l:'② 곡괭이를 뻗어 표지 막대를 걸어 당긴다.', k:'steady', dc:22,
      ok:`몸 대신 곡괭이를 내밀었다. 날 끝으로 표지 막대를 걸었다. 당겼다.<br><br>표지 막대가 기울었다. 전환기가 철컥 소리를 냈다. 빗속에서도 들렸다. 광차 레일 바꿀 때와 같은 소리.<br>열차가 갈림길을 지났다. 종착 불빛이 옆으로 비켜 간다. 녹슨 지선 쪽으로. 곡괭이 날 끝이 휘었다. 쓸 만큼만.`,
      ng:`걸었는데 막대가 꿈쩍 않는다. 녹이 슬어 박혔다.<br><br>당기는 사이 열차가 다가간다. 곡괭이가 막대에 걸린 채 끌린다. 자루가 손에서 미끄러진다.<br>놓았다. 곡괭이가 빗속으로 날아갔다. 갈림길이 뒤로 지나갔다. 어느 쪽으로 갔는지는 모르겠다. 손이 허전하다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'B', t:'시계 — 가루가 떨어지는 간격',
  x:`낡은 건물 지하층이다. 위에서 쿵 소리가 났다. 무언가 터졌다.<br><br>
    천장에서 가루가 떨어진다. 한 줄로. 멎었다가 다시.<br>
    땅 밑에서 일하던 사람은 이 가루를 안다. 천장이 앓는 소리다. 떨어지는 간격이 짧아지면 끝이 가깝다.<br><br>
    출구까지 복도 하나. 일행 하나가 다리를 다쳐 늦다.`,
  o:[
    { l:'① 가루 떨어지는 간격을 세어 남은 시간을 짚는다.', k:'sense', dc:21,
      ok:`가루가 떨어지는 사이를 셌다. 숨 열. 숨 아홉. 숨 일곱. 짧아진다.<br><br>숨 셋이 되면 내려앉는다. 지금 일곱이면 숨 마흔쯤 남았다. 다친 사람 걸음으로 복도 끝까지 숨 서른다섯.<br>일행에게 말했다. 서두르지 말고 쉬지 말라고. 숨 서른여섯에 출구를 지났다. 마흔둘에 등 뒤 복도가 무너졌다. 셈이 맞았다.`,
      ng:`셌는데 간격이 들쭉날쭉하다. 짧아졌다가 길어졌다가.<br><br>셈이 안 선다. 서두르자고 했다. 다친 사람이 넘어졌다. 일으켰다.<br>복도 중간에서 천장 한 덩이가 떨어졌다. 다친 사람 바로 옆. 둘이 같이 쓰러졌다. 먼지를 뒤집어쓰고 기어 나갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 쇠파이프를 주워 천장 앓는 데에 버팀목을 세운다.', k:'steady', dc:21,
      ok:`복도에 굴러다니는 쇠파이프를 주웠다. 가루가 제일 많이 떨어지는 데 밑에 세웠다. 위는 천장에, 아래는 바닥 금 간 데를 피해.<br><br>곡괭이 머리로 아래를 두드려 박았다. 천장이 앓는 소리를 멈췄다. 잠깐이다. 잠깐이면 된다.<br>다친 사람을 부축해 지났다. 출구에서 돌아보니 쇠파이프가 휘어 있었다. 그래도 서 있었다.`,
      ng:`세웠는데 바닥이 금 간 데였다. 파이프가 바닥을 뚫고 내려갔다.<br><br>천장이 쿵 하고 반 치 내려앉았다. 가루가 쏟아진다. 눈에 들어갔다.<br>보이지 않는 채로 다친 사람을 업었다. 손으로 벽을 짚어 출구를 찾았다. 등 뒤에서 천장이 내려앉는 소리를 들었다. 아주 가까이서.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 다친 사람을 업고 먼저 뛴다.', k:'bond', dc:21,
      ok:`셈을 하지 않았다. 다친 사람을 업었다. 뛰었다.<br><br>무겁다. 굴에서 다친 동료를 업고 나온 적이 있다. 그때보다 가볍다. 그때는 더 멀었다.<br>출구를 지나 빗속에 내려놓았다. 숨이 터졌다. 등 뒤에서 복도가 무너지는 소리가 났다. 업은 사람이 이쪽 등에 대고 숨을 쉬었다. 둘 다 살았다.`,
      ng:`업고 뛰는데 복도 바닥이 젖어 미끄럽다. 무릎이 꺾였다.<br><br>둘이 같이 넘어졌다. 업힌 사람이 다친 다리부터 바닥에 닿았다. 비명.<br>다시 업었다. 천장 가루가 머리 위에 쏟아진다. 출구를 지날 때 무릎에서 물 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B', t:'문 — 벽돌 줄눈',
  x:`철문이 잠겼다. 열쇠는 없다. 철문 옆 벽은 벽돌이다. 오래됐다.<br><br>
    등 뒤 복도에서 손전등이 켜졌다. 문까지 백 걸음.<br>
    곡괭이로 철문을 치면 철문이 이긴다. 벽돌을 치면 벽돌이 진다. 그래도 시간이 든다.<br><br>
    빗물이 벽을 타고 흘러내린다. 줄눈을 따라서. 벽돌 사이로만.`,
  o:[
    { l:'① 벽돌 말고 줄눈만 곡괭이 끝으로 판다.', k:'break', dc:21, wake:1,
      ok:`빗물이 흐르는 줄눈을 봤다. 물이 흐르는 데는 무르다. 곡괭이 끝을 줄눈에만 넣었다. 벽돌은 안 쳤다.<br><br>줄눈이 모래처럼 부서져 나온다. 벽돌 하나가 헐거워진다. 손으로 뽑았다. 다음 것은 더 쉽다. 하나가 빠지면 옆이 다 헐거워진다.<br>여덟 개를 뽑았다. 사람 하나 지나는 구멍. 손전등이 마흔 걸음 뒤였다.<br><br>돌을 캘 때는 돌결을 봤다. 쌓은 벽은 줄눈이 결이다. 벽 하나를 볼 때 이제 벽돌이 아니라 그 사이가 먼저 보인다. 사이가 늘 먼저 진다.`,
      ng:`줄눈을 팠는데 이 벽은 줄눈에 쇠를 섞었다. 곡괭이 끝이 튕겼다.<br><br>손목이 꺾였다. 손전등이 칠십 걸음 뒤다. 다시. 또 튕긴다.<br>결국 벽돌을 쳤다. 깨진다. 느리다. 구멍이 났을 때 손전등이 등을 비추고 있었다. 기어 나가는 다리를 누가 잡았다. 차고 나왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 철문 경첩 쪽 틈에 곡괭이를 넣어 비튼다.', k:'steady', dc:21,
      ok:`철문과 문틀 사이 경첩 쪽 틈에 곡괭이 날을 넣었다. 자루를 어깨에 메고 비틀었다.<br><br>철문은 안 진다. 경첩 박은 벽은 진다. 벽 속 경첩 뿌리가 끙 하고 운다. 한 번 더. 경첩 하나가 벽째 뽑혔다.<br>철문이 기울었다. 틈으로 빠졌다. 곡괭이 자루에 금이 갔다. 한 번은 더 쓸 수 있다.`,
      ng:`비트는데 곡괭이 날이 미끄러졌다. 자루가 튕겨 어깨를 쳤다.<br><br>다시 넣었다. 비틀었다. 경첩은 그대로. 손전등이 오십 걸음.<br>세 번째에 자루가 부러졌다. 날만 틈에 박혀 남았다. 손전등이 얼굴을 쳤다. 반대쪽 복도로 뛰었다. 연장 없이.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'네온 아래 — 금 간 벽',
  x:`낡은 상가 건물 옆 골목이다. 붉은 네온이 벽을 칠한다. 벽에 금이 갔다. 위에서 아래로, 번개 모양으로.<br><br>
    쫓는 것들이 골목 끝으로 들어온다. 셋.<br>
    땅 밑에서 일하던 사람은 금 간 벽을 보면 어디가 먼저 떨어질지 안다. 금이 갈라지는 데. 거기에 무게가 모인다.<br><br>
    금 갈라지는 데 바로 밑에 녹슨 간판 틀이 매달려 있다.`,
  o:[
    { l:'① 금 갈라지는 데를 곡괭이로 쳐서 골목을 막는다.', k:'break', dc:22,
      ok:`일행을 먼저 골목 저편으로 보냈다. 금이 갈라지는 자리를 곡괭이로 찍었다. 한 번.<br><br>금이 소리를 내며 벌어졌다. 벽 한 덩이가 간판 틀째 떨어졌다. 골목 한가운데에 쌓였다. 사람 키만큼.<br>쫓는 것들이 그 앞에서 멈췄다. 넘으려면 시간이 든다. 이쪽은 이미 골목 끝을 돌았다. 먼지가 네온 빛 속에서 붉게 떠다녔다.`,
      ng:`찍었는데 금이 다른 쪽으로 갈라졌다. 이쪽으로.<br><br>벽 한 덩이가 머리 위로 왔다. 몸을 던졌다. 다리가 깔렸다. 간판 틀이 등 옆에 박혔다.<br>일행이 끌어냈다. 다리가 퍼렇게 부었다. 막힌 것은 골목 반이다. 쫓는 것들은 남은 반으로 왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 무게가 안 모이는 쪽 벽에 붙어 지나간다.', k:'steady', dc:21,
      ok:`금이 갈라지는 반대쪽 벽에 일행을 붙였다. 무게가 모이지 않는 쪽이다. 벽이 무너져도 이쪽은 마지막이다.<br><br>벽에 붙어 걸었다. 네온 빛을 등지고. 쫓는 것들이 골목 가운데로 온다. 금 밑으로.<br>그때 간판 틀이 떨어졌다. 혼자서. 쫓는 것 하나가 그 밑에 있었다. 나머지가 멈췄다. 그 사이 다 빠졌다. 금은 오래전부터 그 순간을 기다리고 있었다.`,
      ng:`붙어 걸었는데 반대쪽 벽에도 금이 있었다. 안 보이던 금. 네온 빛이 안 닿는 쪽이다.<br><br>벽돌 하나가 어깨에 떨어졌다. 작다. 그래도 아프다.<br>소리가 났다. 쫓는 것들이 이쪽을 봤다. 뛰었다. 어깨가 빠지지는 않았다. 팔이 한동안 안 올라갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'새벽 전 — 곡괭이를 짚고',
  x:`밤이 끝나 간다. 곡괭이 자루가 손바닥 굳은살에 꼭 맞는다. 몇 해를 쥔 자리다.<br><br>
    다리가 무겁다. 등이 무겁다. 곡괭이도 무겁다. 버리면 가볍다.<br>
    땅 밑에서 일하던 사람이 연장을 버리는 일은 없다. 연장을 버리면 나올 때 맨손이다.<br><br>
    마지막 문까지 남은 길이 오르막이다. 젖은 비탈.`,
  o:[
    { l:'① 곡괭이를 비탈에 찍어 가며 오른다.', k:'steady', dc:21,
      ok:`곡괭이를 앞 비탈에 찍었다. 자루를 당겨 몸을 끌어올렸다. 다시 찍었다.<br><br>무거운 연장이 무거운 몸을 끈다. 한 번 찍을 때마다 한 걸음. 일행이 이쪽이 찍은 자국을 밟고 따라왔다. 계단이 생겼다.<br>꼭대기 문에 닿았다. 곡괭이 날이 진흙투성이다. 날을 털었다. 버리지 않았다. 버리지 않아서 왔다.`,
      ng:`찍었는데 비탈이 무르다. 곡괭이가 진흙째 미끄러져 내려온다.<br><br>몸이 같이 미끄러졌다. 뒤의 일행을 덮쳤다. 다 같이 비탈 밑으로.<br>다시 올랐다. 이번엔 곡괭이를 등에 메고 손으로 기었다. 손톱이 진흙으로 찼다. 꼭대기에서 무릎이 펴지지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 곡괭이 자루에 일행을 줄줄이 매달아 끈다.', k:'bond', dc:21,
      ok:`먼저 올라가 곡괭이 날을 꼭대기 바위 틈에 박았다. 자루를 아래로 내렸다. 잡으라고.<br><br>하나씩 자루를 잡고 올라왔다. 자루가 손잡이고 날이 말뚝이다. 다섯 번.<br>다 올라온 뒤 곡괭이를 뽑았다. 날이 조금 휘었다. 다섯 사람 무게만큼. 펴지 않고 그대로 멨다.`,
      ng:`내렸는데 셋째 사람이 잡을 때 날이 바위 틈에서 빠졌다.<br><br>그 사람이 미끄러졌다. 자루를 놓지 않았다. 이쪽이 날 쪽을 잡았다. 날이 손바닥을 갈랐다.<br>놓지 않았다. 끌어올렸다. 손바닥에서 피가 자루를 타고 흘렀다. 그 사람 손에 묻었다. 둘 다 아무 말도 안 했다.`,
      win:{ exp:16, mind:6 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 비탈 옆 배수로를 따라 돌아 오른다.', k:'sense', dc:21,
      ok:`비탈 곧장은 무르다. 물이 흐르는 데는 단단하다. 물이 흙을 쓸어 가고 돌만 남겼다.<br><br>비탈 옆 배수로를 따라 올랐다. 돌을 밟고. 멀다. 그래도 미끄러지지 않는다.<br>꼭대기에서 비탈을 내려다봤다. 곧장 오르던 다른 발자국들이 중간에서 다 미끄러진 자국으로 끝났다. 물길은 늘 단단한 데로 간다.`,
      ng:`따라갔는데 배수로가 중간에서 끊겼다. 쇠 격자 뚜껑. 그 밑으로 물이 빨려 들어간다.<br><br>뚜껑을 건너려다 발이 격자에 끼었다. 물이 발을 끈다.<br>곡괭이로 격자를 비틀어 발을 뺐다. 발목이 퍼렇다. 남은 길은 결국 무른 비탈이었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-12 } }
  ] }

]);

